  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 8
    encrypted             = true
    delete_on_termination = true
  }

  user_data = <<-EOF
    #!/bin/bash
    yum update -y
    yum install -y httpd
    systemctl enable httpd
    systemctl start httpd
    echo "<h1>${var.server_name}</h1>" > /var/www/html/index.html
  EOF

  tags = {
    Name = var.server_name
  }
}

resource "aws_eip" "web" {
  domain = "vpc"

  tags = {
    Name = "${var.server_name}-eip"
  }
}

resource "aws_eip_association" "web" {
  instance_id   = aws_instance.web.id
  allocation_id = aws_eip.web.id
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  topic_names = {
    first  = "my-topic-with-policy"
    second = "my-topic-with-policy2"
    third  = "user-updates-topic"
  }

  # Full set of SNS actions granted to all principals by the shared topic
  # policy. Explicitly enumerated (rather than "SNS:*") because SNS validates
  # topic policies against a topic-scoped action list: the wildcard shorthand
  # and subscription/tagging scoped actions (e.g. SNS:Unsubscribe,
  # SNS:TagResource) are rejected as "action out of service scope".
  full_sns_actions = [
    "SNS:AddPermission",
    "SNS:DeleteTopic",
    "SNS:GetTopicAttributes",
    "SNS:ListSubscriptionsByTopic",
    "SNS:Publish",
    "SNS:RemovePermission",
    "SNS:SetTopicAttributes",
    "SNS:Subscribe",
  ]

  # Custom delivery policy enabling retry + throttling behavior for the
  # user-updates topic.
  user_updates_delivery_policy = {
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 20
        maxDelayTarget     = 600
        numRetries         = 5
        numMaxDelayRetries = 3
        numNoDelayRetries  = 0
        numMinDelayRetries = 2
        backoffFunction    = "exponential"
      }
      disableSubscriptionOverrides = false
      defaultThrottlePolicy = {
        maxReceivesPerSecond = 10
      }
    }
  }
}

# ---------------------------------------------------------------------------
# Customer-managed KMS key with automatic rotation, used to encrypt all topics
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNSServiceUsage"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "sns" {
  description             = "Customer-managed KMS key for SNS topic encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Topic 1: my-topic-with-policy (encrypted, carries the shared policy)
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "my_topic_with_policy" {
  name              = local.topic_names.first
  kms_master_key_id = aws_kms_key.sns.id
}

# ---------------------------------------------------------------------------
# Topic 2: my-topic-with-policy2 (encrypted, shares the same policy document)
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "my_topic_with_policy2" {
  name              = local.topic_names.second
  kms_master_key_id = aws_kms_key.sns.id
}

# ---------------------------------------------------------------------------
# Topic 3: user-updates-topic (encrypted, custom retry/throttle delivery policy)
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "user_updates_topic" {
  name              = local.topic_names.third
  kms_master_key_id = aws_kms_key.sns.id
  delivery_policy   = jsonencode(local.user_updates_delivery_policy)
}

# ---------------------------------------------------------------------------
# Shared topic policy: allows all AWS principals full SNS actions on the first
# topic. The same policy definition is shared by both policy-bound topics.
#
# SNS requires each policy statement to reference exactly one resource AND
# that resource to be the topic the policy is attached to, so the shared
# definition is declared once and rendered per topic.
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "shared_topic_first" {
  statement {
    sid       = "AllowAllPrincipalsFullSNSActions"
    effect    = "Allow"
    actions   = local.full_sns_actions
    resources = [aws_sns_topic.my_topic_with_policy.arn]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "shared_topic_second" {
  statement {
    sid       = "AllowAllPrincipalsFullSNSActions"
    effect    = "Allow"
    actions   = local.full_sns_actions
    resources = [aws_sns_topic.my_topic_with_policy2.arn]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [local.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "first" {
  arn    = aws_sns_topic.my_topic_with_policy.arn
  policy = data.aws_iam_policy_document.shared_topic_first.json
}

resource "aws_sns_topic_policy" "second" {
  arn    = aws_sns_topic.my_topic_with_policy2.arn
  policy = data.aws_iam_policy_document.shared_topic_second.json
}

