  global_secondary_index {
    name            = "recipientWalletId-Index"
    hash_key        = "recipientWalletId"
    projection_type = "ALL"
  }

  tags = merge(local.common_tags, {
    Name = "near-nft-shares"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_nfts" {
  name         = "near-nfts"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "nftId"

  attribute {
    name = "nftId"
    type = "S"
  }

  attribute {
    name = "ownerWalletId"
    type = "S"
  }

  attribute {
    name = "transactionId"
    type = "S"
  }

  global_secondary_index {
    name            = "ownerWalletId-Index"
    hash_key        = "ownerWalletId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "transactionId-Index"
    hash_key        = "transactionId"
    projection_type = "ALL"
  }

  tags = merge(local.common_tags, {
    Name = "near-nfts"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_otp" {
  name         = "near-otp"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "userId"
  range_key    = "ttl"

  attribute {
    name = "userId"
    type = "S"
  }

  attribute {
    name = "ttl"
    type = "N"
  }

  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  tags = merge(local.common_tags, {
    Name = "near-otp"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_shared_files" {
  name         = "near-shared-files"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "fileId"
  range_key    = "userId"

  attribute {
    name = "fileId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  tags = merge(local.common_tags, {
    Name = "near-shared-files"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_storage" {
  name             = "near-storage"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "pk"
  range_key        = "sk"
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "pk1"
    type = "S"
  }

  attribute {
    name = "sk1"
    type = "S"
  }

  global_secondary_index {
    name            = "GSI1"
    hash_key        = "pk1"
    range_key       = "sk1"
    projection_type = "ALL"
  }

  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  tags = merge(local.common_tags, {
    Name = "near-storage"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_transactions" {
  name         = "near-transactions"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "transactionId"

  attribute {
    name = "transactionId"
    type = "S"
  }

  attribute {
    name = "senderWalletId"
    type = "S"
  }

  attribute {
    name = "receiverWalletId"
    type = "S"
  }

  attribute {
    name = "jobId"
    type = "S"
  }

  attribute {
    name = "parentId"
    type = "S"
  }

  attribute {
    name = "created"
    type = "N"
  }

  global_secondary_index {
    name            = "senderWalletId-Index"
    hash_key        = "senderWalletId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "receiverWalletId-Index"
    hash_key        = "receiverWalletId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "jobId-created-Index"
    hash_key        = "jobId"
    range_key       = "created"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "parentId-created-Index"
    hash_key        = "parentId"
    range_key       = "created"
    projection_type = "ALL"
  }

  tags = merge(local.common_tags, {
    Name = "near-transactions"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_users" {
  name         = "near-users"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "userId"

