    projection_type = "ALL"
  }

  tags = merge(local.common_tags, {
    Name = "near-users"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_wallets_blockchain" {
  name         = "near-wallets-blockchain"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "wallet_id"

  attribute {
    name = "wallet_id"
    type = "S"
  }

  tags = merge(local.common_tags, {
    Name = "near-wallets-blockchain"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_wallets_private" {
  name         = "near-wallets-private"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "walletId"

  attribute {
    name = "walletId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  global_secondary_index {
    name            = "UserIdIndex"
    hash_key        = "userId"
    range_key       = "walletId"
    projection_type = "ALL"
  }

  tags = merge(local.common_tags, {
