  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "walletId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  attribute {
    name = "walletName"
    type = "S"
  }

  attribute {
    name = "jobId"
    type = "S"
  }

  global_secondary_index {
    name            = "userId-Index"
    hash_key        = "userId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "walletName-Index"
    hash_key        = "walletName"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "jobId-Index"
    hash_key        = "jobId"
    projection_type = "ALL"
  }

  tags = merge(local.common_tags, {
    Name = "near-wallets"
  })

  lifecycle {
    prevent_destroy = true
  }
}

