# 9. EC2 instances
resource "aws_iam_role_policy" "ec2_instances" {
  name = "CloudForecastEC2Instances"
  role = aws_iam_role.cloudforecast.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "CloudForecastEC2Instances"
        Effect   = "Allow"
        Action   = ["ec2:DescribeInstances", "ec2:DescribeInstanceStatus"]
        Resource = local.all_resources
      }
    ]
  })
}

# 10. RDS instances
resource "aws_iam_role_policy" "rds_instances" {
  name = "CloudForecastRDSInstances"
