###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region that defaults the deployment for the HealthOmics resources."
  type        = string
  default     = "us-east-1"
}

variable "output_bucket_name" {
  description = "Name of the S3 bucket used to store Amazon HealthOmics workflow results."
  type        = string
  default     = "tf-benchmark-omics-output-bucket"
}

variable "service_account_user_name" {
  description = "Name of the IAM user with programmatic access used for HealthOmics testing."
  type        = string
  default     = "workbench-health-omics"
}

variable "healthomics_role_name" {
  description = "Name of the IAM role that the Amazon HealthOmics service assumes."
  type        = string
  default     = "HealthOmicsRole"
}

variable "service_policy_name" {
  description = "Name of the IAM policy attached to the HealthOmics service role."
  type        = string
  default     = "HealthOmicsServicePolicy"
}

variable "user_policy_name" {
  description = "Name of the IAM policy attached to the HealthOmics service account user."
  type        = string
  default     = "HealthOmicsUserPolicy"
}

variable "ecr_repository_names" {
  description = "Set of ECR repository names to create for storing HealthOmics container images."
  type        = set(string)
  default     = ["healthomics-workflow"]
}

variable "additional_s3_bucket_arns" {
  description = "Optional list of additional S3 bucket ARNs to grant read-only access to."
  type        = list(string)
  default     = []
}

variable "cross_account_ids" {
  description = "List of external AWS account IDs granted cross-account ECR pull access."
  type        = list(string)
  default     = []
}

###############################################################################
# Data Sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  common_tags = {
    Project     = "healthomics-benchmark"
    ManagedBy   = "terraform"
    Environment = "testing"
    Region      = var.aws_region
  }

  ecr_pull_actions = [
    "ecr:BatchCheckLayerAvailability",
    "ecr:BatchGetImage",
    "ecr:GetDownloadUrlForLayer",
  ]

  ecr_cross_account_principals = [
    for id in var.cross_account_ids :
    "arn:${local.partition}:iam::${id}:root"
  ]

  # Repository policy: allow the HealthOmics service to pull images and grant
  # optional cross-account pull access to external accounts.
  ecr_repository_policy_statements = concat(
    [
      {
        Sid       = "AllowHealthOmicsServicePull"
        Effect    = "Allow"
        Principal = { Service = "omics.amazonaws.com" }
        Action    = local.ecr_pull_actions
      },
    ],
    length(local.ecr_cross_account_principals) > 0 ? [
      {
        Sid       = "AllowCrossAccountPull"
        Effect    = "Allow"
        Principal = { AWS = local.ecr_cross_account_principals }
        Action    = local.ecr_pull_actions
      },
    ] : [],
  )

  ecr_repository_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.ecr_repository_policy_statements
  })

  # Trust policy allowing the HealthOmics service to assume the role.
  healthomics_trust_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowHealthOmicsServiceAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "omics.amazonaws.com" }
        Action    = "sts:AssumeRole"
      },
    ]
  })

  # Customer managed KMS key policy for the output bucket.
  omics_output_kms_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowHealthOmicsRoleUse"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.healthomics.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
    ]
  })

  # Policy attached to the HealthOmics service role.
  service_policy_statements = concat(
    [
      {
        Sid      = "OmicsWorkflowAccess"
        Effect   = "Allow"
        Action   = ["omics:*"]
        Resource = ["*"]
      },
      {
        Sid    = "OutputBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts",
        ]
        Resource = [
          aws_s3_bucket.omics_output.arn,
          "${aws_s3_bucket.omics_output.arn}/*",
        ]
      },
      {
        Sid    = "EcrImagePullAccess"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer",
          "ecr:DescribeRepositories",
          "ecr:DescribeImages",
        ]
        Resource = [for repo in aws_ecr_repository.this : repo.arn]
      },
      {
        Sid    = "KmsEncryptionAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = [aws_kms_key.omics_output.arn]
      },
      {
        Sid    = "CloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          "arn:${local.partition}:logs:*:${local.account_id}:log-group:/aws/omics/*",
        ]
      },
    ],
    length(var.additional_s3_bucket_arns) > 0 ? [
      {
        Sid    = "AdditionalBucketReadAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket",
          "s3:GetBucketLocation",
        ]
        Resource = concat(
          var.additional_s3_bucket_arns,
          [for arn in var.additional_s3_bucket_arns : "${arn}/*"],
        )
      },
    ] : [],
  )

  service_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.service_policy_statements
  })

  # Policy attached to the programmatic HealthOmics test user.
  user_policy_statements = [
    {
      Sid      = "PassHealthOmicsRole"
      Effect   = "Allow"
      Action   = ["iam:PassRole"]
      Resource = [aws_iam_role.healthomics.arn]
      Condition = {
        StringEquals = {
          "iam:PassedToService" = "omics.amazonaws.com"
        }
      }
    },
    {
      Sid      = "FullOmicsAccess"
      Effect   = "Allow"
      Action   = ["omics:*"]
      Resource = ["*"]
    },
    {
      Sid    = "S3ReadOnlyAccess"
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:ListBucket",
        "s3:GetBucketLocation",
      ]
      Resource = concat(
        [
          aws_s3_bucket.omics_output.arn,
          "${aws_s3_bucket.omics_output.arn}/*",
        ],
        var.additional_s3_bucket_arns,
        [for arn in var.additional_s3_bucket_arns : "${arn}/*"],
      )
    },
    {
      Sid    = "OutputBucketKmsReadAccess"
      Effect = "Allow"
      Action = [
        "kms:Decrypt",
        "kms:DescribeKey",
      ]
      Resource = [aws_kms_key.omics_output.arn]
    },
  ]

  user_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.user_policy_statements
  })
}

###############################################################################
# KMS Customer Managed Key for the output bucket (SSE-KMS)
###############################################################################

resource "aws_kms_key" "omics_output" {
  description             = "Customer managed key used for HealthOmics output bucket SSE-KMS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = local.omics_output_kms_policy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "omics_output" {
  name          = "alias/${var.output_bucket_name}"
  target_key_id = aws_kms_key.omics_output.key_id
}

###############################################################################
# Output S3 Bucket
###############################################################################

resource "aws_s3_bucket" "omics_output" {
  bucket = var.output_bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "omics_output" {
  bucket = aws_s3_bucket.omics_output.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "omics_output" {
  bucket = aws_s3_bucket.omics_output.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.omics_output.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "omics_output" {
  bucket = aws_s3_bucket.omics_output.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# IAM Role assumed by the HealthOmics service
###############################################################################

resource "aws_iam_role" "healthomics" {
  name               = var.healthomics_role_name
  description        = "IAM role assumed by the Amazon HealthOmics service to run workflows"
  assume_role_policy = local.healthomics_trust_policy

  tags = local.common_tags
}

resource "aws_iam_policy" "service" {
  name        = var.service_policy_name
  description = "Permissions granted to the HealthOmics service role"
  policy      = local.service_policy

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "service" {
  role       = aws_iam_role.healthomics.name
  policy_arn = aws_iam_policy.service.arn
}

###############################################################################
# Programmatic HealthOmics test user
###############################################################################

resource "aws_iam_user" "service" {
  name = var.service_account_user_name
  path = "/"

  tags = local.common_tags
}

resource "aws_iam_access_key" "service" {
  user = aws_iam_user.service.name
}

resource "aws_iam_policy" "user" {
  name        = var.user_policy_name
  description = "Permissions granted to the HealthOmics programmatic test user"
  policy      = local.user_policy

  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "user" {
  user       = aws_iam_user.service.name
  policy_arn = aws_iam_policy.user.arn
}

###############################################################################
# ECR Repositories for HealthOmics container images
###############################################################################

resource "aws_ecr_repository" "this" {
  for_each = var.ecr_repository_names

  name                 = each.value
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_repository_policy" "this" {
  for_each = aws_ecr_repository.this

  repository = each.value.name
  policy     = local.ecr_repository_policy
}

###############################################################################
# Outputs
###############################################################################

output "aws_region" {
  description = "AWS region used for the HealthOmics resources."
  value       = var.aws_region
}

output "output_bucket_name" {
  description = "Name of the HealthOmics output bucket."
  value       = aws_s3_bucket.omics_output.id
}

output "output_bucket_arn" {
  description = "ARN of the HealthOmics output bucket."
  value       = aws_s3_bucket.omics_output.arn
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key used for output bucket encryption."
  value       = aws_kms_key.omics_output.arn
}

output "healthomics_role_arn" {
  description = "ARN of the IAM role assumed by the HealthOmics service."
  value       = aws_iam_role.healthomics.arn
}

output "healthomics_service_policy_arn" {
  description = "ARN of the HealthOmics service policy."
  value       = aws_iam_policy.service.arn
}

output "healthomics_user_policy_arn" {
  description = "ARN of the HealthOmics user policy."
  value       = aws_iam_policy.user.arn
}

output "service_user_name" {
  description = "Name of the programmatic HealthOmics test user."
  value       = aws_iam_user.service.name
}

output "service_user_access_key_id" {
  description = "Access key ID for the programmatic HealthOmics test user."
  value       = aws_iam_access_key.service.id
  sensitive   = true
}

output "ecr_repository_urls" {
  description = "Map of ECR repository names to their URLs."
  value       = { for name, repo in aws_ecr_repository.this : name => repo.repository_url }
}

variable "cluster_name" {
  description = "Name of the ECS cluster (used as a naming suffix across resources)."
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr_network_octets" {
  description = "Network octets used to derive the VPC and subnet CIDR blocks."
  type        = string
  default     = "10.0"
}

variable "default_tags" {
  description = "A map of tags applied to all resources created by this configuration."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # The first three availability zones (a, b and c) in the region.
  availability_zones = slice(data.aws_availability_zones.available.names, 0, 3)

  # Public /22 CIDR allocations, in AZ order.
  public_subnet_cidrs = [
    "${var.vpc_cidr_network_octets}.12.0/22",
    "${var.vpc_cidr_network_octets}.16.0/22",
    "${var.vpc_cidr_network_octets}.20.0/22",
  ]

  # Private /22 CIDR allocations, in AZ order.
  private_subnet_cidrs = [
    "${var.vpc_cidr_network_octets}.0.0/22",
    "${var.vpc_cidr_network_octets}.4.0/22",
    "${var.vpc_cidr_network_octets}.8.0/22",
  ]

  ecs_cluster_name = "dit-paas-${var.cluster_name}-cluster"
}

resource "aws_ecs_cluster" "this" {
  name = local.ecs_cluster_name

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = merge(var.default_tags, {
    Name = local.ecs_cluster_name
  })
}

resource "aws_vpc" "main" {
  cidr_block           = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false
  enable_dns_support   = true

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = local.availability_zones[count.index]

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-public-${local.availability_zones[count.index]}"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.availability_zones[count.index]

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-private-${local.availability_zones[count.index]}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-ig"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-nat-eip-${local.availability_zones[count.index]}"
  })
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-nat-${local.availability_zones[count.index]}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-private-rt-${local.availability_zones[count.index]}"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# Self-contained VPC module with VPC Flow Logs and flexible VPC endpoints
#
# This configuration provisions a complete, greenfield VPC stack including
# networking, flow logging, security groups for endpoints and optional SSM
# support. Every dependency is declared within this file.
###############################################################################

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region used to construct VPC endpoint service names."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC and prefix used for associated resources."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Tenancy of instances launched into the VPC."
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Whether to enable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "flow_logs_retention_days" {
  description = "Retention period (in days) for the VPC flow logs CloudWatch log group."
  type        = number
  default     = 180
}

variable "aws_endpoints" {
  description = "Set of standard AWS interface endpoint service short names (e.g. logs, ssm)."
  type        = set(string)
  default     = ["logs"]
}

variable "gateway_endpoints" {
  description = "Set of AWS gateway endpoint service short names."
  type        = set(string)
  default     = ["dynamodb", "s3"]
}

variable "custom_endpoints" {
  description = "Map of custom interface endpoint services keyed by a logical name."
  type = map(object({
    service_name = string
    port         = number
  }))
  default = {}
}

variable "endpoint_source_security_group_ids" {
  description = "Source security group IDs permitted to reach the standard interface endpoints over HTTPS."
  type        = list(string)
  default     = []
}

variable "custom_endpoint_source_security_group_ids" {
  description = "Source security group IDs permitted to reach the custom interface endpoints."
  type        = list(string)
  default     = []
}

variable "interface_endpoint_subnet_ids" {
  description = "Subnet IDs used for interface endpoints. Defaults to the module-managed private subnets."
  type        = list(string)
  default     = []
}

variable "gateway_endpoint_route_table_ids" {
  description = "Route table IDs associated with gateway endpoints. Defaults to the module-managed private route tables."
  type        = list(string)
  default     = []
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  private_subnet_cidrs = [cidrsubnet(var.vpc_cidr, 8, 10), cidrsubnet(var.vpc_cidr, 8, 11)]

  interface_subnet_ids    = length(var.interface_endpoint_subnet_ids) > 0 ? var.interface_endpoint_subnet_ids : aws_subnet.private[*].id
  gateway_route_table_ids = length(var.gateway_endpoint_route_table_ids) > 0 ? var.gateway_endpoint_route_table_ids : aws_route_table.private[*].id

  # Flattened ingress/egress rule matrix for custom endpoints:
  # one rule per (custom service port, source security group ID) combination.
  custom_endpoint_rule_matrix = merge([
    for ck, c in var.custom_endpoints : {
      for sg in var.custom_endpoint_source_security_group_ids :
      "${ck}-${sg}" => {
        port      = c.port
        source_sg = sg
      }
    }
  ]...)

  ssm_enabled = contains(var.aws_endpoints, "ssm")
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = true
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = {
    Name = var.vpc_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
  }
}

###############################################################################
# Route tables
###############################################################################

resource "aws_route_table" "private" {
  count = length(local.azs)

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
  }
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# Default security group management
###############################################################################

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-default"
  }
}

###############################################################################
# Endpoint security groups
###############################################################################

resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-${var.vpc_name}"
  description = "Security group for standard AWS interface VPC endpoints."
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "vpc-endpoints-${var.vpc_name}"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "custom_endpoints" {
  name        = "custom-endpoints-${var.vpc_name}"
  description = "Security group for custom interface VPC endpoint services."
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "custom-endpoints-${var.vpc_name}"
  }

  lifecycle {
    create_before_destroy = true
  }
}

# HTTPS 443 ingress from the specified source security group IDs.
resource "aws_security_group_rule" "endpoints_ingress_https" {
  for_each = toset(var.endpoint_source_security_group_ids)

  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = each.value
  description              = "HTTPS from source security group ${each.value}"
}

# HTTPS 443 egress to the specified source security group IDs.
resource "aws_security_group_rule" "endpoints_egress_https" {
  for_each = toset(var.endpoint_source_security_group_ids)

  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = each.value
  description              = "HTTPS to source security group ${each.value}"
}

# Custom endpoint ingress: one rule per service port / source security group combination.
resource "aws_security_group_rule" "custom_endpoints_ingress" {
  for_each = local.custom_endpoint_rule_matrix

  type                     = "ingress"
  from_port                = each.value.port
  to_port                  = each.value.port
  protocol                 = "tcp"
  security_group_id        = aws_security_group.custom_endpoints.id
  source_security_group_id = each.value.source_sg
  description              = "Custom endpoint port ${each.value.port} from ${each.value.source_sg}"
}

# Custom endpoint egress: one rule per service port / source security group combination.
resource "aws_security_group_rule" "custom_endpoints_egress" {
  for_each = local.custom_endpoint_rule_matrix

  type                     = "egress"
  from_port                = each.value.port
  to_port                  = each.value.port
  protocol                 = "tcp"
  security_group_id        = aws_security_group.custom_endpoints.id
  source_security_group_id = each.value.source_sg
  description              = "Custom endpoint port ${each.value.port} to ${each.value.source_sg}"
}

###############################################################################
# VPC Flow Logs (ALL traffic) -> CloudWatch Logs
###############################################################################

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc-flow-logs/${var.vpc_name}"
  retention_in_days = var.flow_logs_retention_days

  tags = {
    Name = "${var.vpc_name}-flow-logs"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "vpc_flow_logs_${var.vpc_name}"
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_logs.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn         = aws_iam_role.flow_logs.arn

  tags = {
    Name = "${var.vpc_name}-flow-logs"
  }
}

###############################################################################
# Gateway VPC endpoints
###############################################################################

resource "aws_vpc_endpoint" "gateway" {
  for_each = var.gateway_endpoints

  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.${each.value}"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = local.gateway_route_table_ids

  tags = {
    Name = "${var.vpc_name}-${each.value}"
  }
}

###############################################################################
# Standard AWS interface VPC endpoints (private DNS enabled)
###############################################################################

resource "aws_vpc_endpoint" "interface" {
  for_each = var.aws_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.aws_region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.interface_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-${each.value}"
  }
}

###############################################################################
# Custom interface VPC endpoints (private DNS disabled)
###############################################################################

resource "aws_vpc_endpoint" "custom" {
  for_each = var.custom_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.interface_subnet_ids
  security_group_ids  = [aws_security_group.custom_endpoints.id]
  private_dns_enabled = false

  tags = {
    Name = "${var.vpc_name}-${each.key}"
  }
}

###############################################################################
# SSM (Systems Manager) support - provisioned only when "ssm" is requested
###############################################################################

resource "aws_iam_role" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  name = "ssm_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "ssm_${var.vpc_name}"
  }
}

resource "aws_iam_role_policy_attachment" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  name = "ssm_${var.vpc_name}"
  role = aws_iam_role.ssm[0].name
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "Primary CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "vpc_endpoints_security_group_id" {
  description = "Security group ID for standard interface VPC endpoints."
  value       = aws_security_group.vpc_endpoints.id
}

output "custom_endpoints_security_group_id" {
  description = "Security group ID for custom interface VPC endpoints."
  value       = aws_security_group.custom_endpoints.id
}

output "flow_logs_log_group_name" {
  description = "CloudWatch log group name receiving VPC flow logs."
  value       = aws_cloudwatch_log_group.flow_logs.name
}

output "flow_logs_role_arn" {
  description = "ARN of the VPC flow logs IAM role."
  value       = aws_iam_role.flow_logs.arn
}

output "ssm_instance_profile_name" {
  description = "Name of the SSM instance profile (when ssm endpoint is enabled)."
  value       = try(aws_iam_instance_profile.ssm[0].name, null)
}

###############################################################################
# Variables
###############################################################################

variable "project_name" {
  description = "Project name used as the prefix for KMS key aliases and resource naming."
  type        = string
  default     = "baseline-security"
}

variable "kms_rotation_period_in_days" {
  description = "Number of days between automatic rotation of the customer-managed KMS keys."
  type        = number
  default     = 90

  validation {
    condition = (
      var.kms_rotation_period_in_days >= 90 &&
      var.kms_rotation_period_in_days <= 2560
    )
    error_message = "kms_rotation_period_in_days must be between 90 and 2560 days."
  }
}

variable "ebs_kms_key_arn" {
  description = "Optional external KMS key ARN to use as the account-level default EBS encryption key. When left blank, the internal compute KMS key is used."
  type        = string
  default     = ""
}

variable "ec2_instance_metadata_hop_limit" {
  description = "Maximum number of network hops allowed for EC2 instance metadata (IMDS) requests."
  type        = number
  default     = 1

  validation {
    condition = (
      var.ec2_instance_metadata_hop_limit >= 1 &&
      var.ec2_instance_metadata_hop_limit <= 64
    )
    error_message = "ec2_instance_metadata_hop_limit must be between 1 and 64."
  }
}

variable "enable_ec2_instance_metadata_defaults" {
  description = "When true, enforce account-level EC2 instance metadata defaults requiring IMDSv2."
  type        = bool
  default     = true
}

variable "enable_ec2_serial_console_access_disable" {
  description = "When true, disable account-level EC2 Serial Console access."
  type        = bool
  default     = true
}

variable "enable_emr_block_public_access" {
  description = "When true, enforce account-level EMR block public access."
  type        = bool
  default     = true
}

###############################################################################
# Data Sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition
  root_arn   = "arn:${local.partition}:iam::${local.account_id}:root"

  compute_key_alias       = "alias/${var.project_name}-compute"
  observability_key_alias = "alias/${var.project_name}-observability"
  storage_key_alias       = "alias/${var.project_name}-storage"

  ebs_default_kms_key_arn = var.ebs_kms_key_arn != "" ? var.ebs_kms_key_arn : aws_kms_key.compute.arn
}

###############################################################################
# KMS Key Policies
###############################################################################

data "aws_iam_policy_document" "compute_kms" {
  statement {
    sid     = "EnableIAMRootAccess"
    effect  = "Allow"
    actions = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }
  }

  statement {
    sid     = "AllowEC2ServiceUse"
    effect  = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "AllowAutoScalingServiceRoleUse"
    effect  = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["autoscaling.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "observability_kms" {
  statement {
    sid       = "EnableIAMRootAccess"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }
  }

  statement {
    sid     = "AllowCloudWatchLogs"
    effect  = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"]
    }
  }

  statement {
    sid     = "AllowCloudTrail"
    effect  = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "AllowCloudWatchAlarms"
    effect  = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "AllowSNS"
    effect  = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "AllowSQS"
    effect  = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "AllowEventBridge"
    effect  = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "storage_kms" {
  statement {
    sid       = "EnableIAMRootAccess"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }
  }

  statement {
    sid     = "AllowS3ServiceUse"
    effect  = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "AllowConfigEncryptedSnapshotDelivery"
    effect  = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "AllowCloudTrailLogEncryption"
    effect  = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

###############################################################################
# Compute Layer KMS Key
###############################################################################

resource "aws_kms_key" "compute" {
  description             = "Customer-managed KMS key for the ${var.project_name} compute layer"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.compute_kms.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "compute" {
  name          = local.compute_key_alias
  target_key_id = aws_kms_key.compute.key_id
}

###############################################################################
# Observability Layer KMS Key
###############################################################################

resource "aws_kms_key" "observability" {
  description             = "Customer-managed KMS key for the ${var.project_name} observability layer"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.observability_kms.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "observability" {
  name          = local.observability_key_alias
  target_key_id = aws_kms_key.observability.key_id
}

###############################################################################
# Storage Layer KMS Key
###############################################################################

resource "aws_kms_key" "storage" {
  description             = "Customer-managed KMS key for the ${var.project_name} storage layer"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.storage_kms.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "storage" {
  name          = local.storage_key_alias
  target_key_id = aws_kms_key.storage.key_id
}

###############################################################################
# Account-Level EBS Encryption Defaults
###############################################################################

resource "aws_ebs_encryption_by_default" "this" {
  enabled = true
}

resource "aws_ebs_default_kms_key" "this" {
  key_arn = local.ebs_default_kms_key_arn
}

###############################################################################
# Account-Level Public Access Restrictions
###############################################################################

resource "aws_ec2_image_block_public_access" "this" {
  state = "block-new-sharing"
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  state = "block-all-sharing"
}

resource "aws_ec2_instance_metadata_defaults" "this" {
  count = var.enable_ec2_instance_metadata_defaults ? 1 : 0

  http_tokens                 = "required"
  http_put_response_hop_limit = var.ec2_instance_metadata_hop_limit
}

resource "aws_ec2_serial_console_access" "this" {
  count = var.enable_ec2_serial_console_access_disable ? 1 : 0

  enabled = false
}

resource "aws_emr_block_public_access_configuration" "this" {
  count = var.enable_emr_block_public_access ? 1 : 0

  block_public_security_group_rules = true
}

###############################################################################
# Input variables
###############################################################################

variable "cluster_prefix" {
  description = "Short prefix applied to every cluster resource name (5-8 characters)."
  type        = string
  default     = "bench"

  validation {
    condition     = length(var.cluster_prefix) >= 5 && length(var.cluster_prefix) <= 8
    error_message = "cluster_prefix must be between 5 and 8 characters long."
  }
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "172.16.0.0/16"
}

variable "enable_dns_support" {
  description = "Whether DNS resolution is supported inside the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Whether instances launched in the VPC receive public DNS hostnames."
  type        = bool
  default     = true
}

variable "key_pair_name" {
  description = "Name of the deployment SSH key pair."
  type        = string
  default     = "benchmark-keypair"
}

variable "ssh_public_key" {
  description = "SSH public key material used for the deployment key pair. When empty a key pair is generated automatically."
  type        = string
  default     = ""
  sensitive   = true
}

variable "availability_zones" {
  description = "Availability zones to spread the subnets across. Empty picks the first three available zones in the region."
  type        = list(string)
  default     = []
}

variable "subnet_newbits" {
  description = "Number of additional bits added to the VPC prefix when calculating subnet CIDR allocations."
  type        = number
  default     = 8
}

variable "public_subnets" {
  description = "User-defined public subnet objects spread across availability zones."
  type = list(object({
    name              = string
    availability_zone = optional(string)
  }))
  default = [
    { name = "public-1", availability_zone = null },
    { name = "public-2", availability_zone = null },
  ]
}

variable "private_subnets" {
  description = "User-defined private subnet objects spread across availability zones."
  type = list(object({
    name              = string
    availability_zone = optional(string)
  }))
  default = [
    { name = "private-1", availability_zone = null },
    { name = "private-2", availability_zone = null },
  ]
}

variable "nat_gateway_enabled" {
  description = "Provision per-subnet public NAT gateways for the private subnets."
  type        = bool
  default     = true
}

variable "ingress_cidr_rules" {
  description = "Custom dynamic CIDR-based ingress rules added to the default security group."
  type = list(object({
    description = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = []
}

variable "ami_id" {
  description = "AMI used for the inventory nodes. Empty selects the most recent Amazon Linux 2 AMI."
  type        = string
  default     = ""
}

variable "inventory_nodes" {
  description = "Inventory node definitions used to build the compute cluster."
  type = list(object({
    name              = string
    instance_type     = string
    subnet_index      = number
    ami_id            = optional(string)
    assign_elastic_ip = bool
    root_volume = object({
      size = number
      type = string
    })
    data_volumes = list(object({
      device_name = string
      mount_point = string
      size        = number
      type        = string
    }))
  }))
  default = [
    {
      name              = "node-01"
      instance_type     = "t3.micro"
      subnet_index      = 0
      assign_elastic_ip = false
      root_volume       = { size = 20, type = "gp3" }
      data_volumes = [
        { device_name = "/dev/sdf", mount_point = "/data", size = 50, type = "gp3" }
      ]
    },
    {
      name              = "node-02"
      instance_type     = "t3.micro"
      subnet_index      = 1
      assign_elastic_ip = false
      root_volume       = { size = 20, type = "gp3" }
      data_volumes      = []
    },
  ]
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "node" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

###############################################################################
# Local values
###############################################################################

locals {
  common_tags = {
    Cluster   = var.cluster_prefix
    ManagedBy = "terraform"
  }

  azs = length(var.availability_zones) > 0 ? var.availability_zones : slice(
    data.aws_availability_zones.available.names,
    0,
    min(3, length(data.aws_availability_zones.available.names))
  )

  # Dynamic CIDR allocation for user-defined subnets.
  public_subnet_cidrs = [
    for i, s in var.public_subnets : cidrsubnet(var.vpc_cidr, var.subnet_newbits, i)
  ]

  private_subnet_cidrs = [
    for i, s in var.private_subnets : cidrsubnet(var.vpc_cidr, var.subnet_newbits, i + length(var.public_subnets))
  ]

  ami_id = var.ami_id != "" ? var.ami_id : data.aws_ami.node.id

  node_index_by_name = { for i, n in var.inventory_nodes : n.name => i }

  # Compute nodes are placed by index into the private subnets, falling back to
  # the public subnets when no private subnets are defined.
  compute_subnet_ids = length(aws_subnet.private) > 0 ? aws_subnet.private[*].id : aws_subnet.public[*].id
  compute_subnet_azs = length(aws_subnet.private) > 0 ? aws_subnet.private[*].availability_zone : aws_subnet.public[*].availability_zone

  node_volumes_by_node = {
    for n in var.inventory_nodes : n.name => [
      for v in n.data_volumes : {
        device_path = replace(v.device_name, "/dev/sd", "/dev/xvd")
        mount_point = v.mount_point
      }
    ]
  }

  node_data_volumes = flatten([
    for i, n in var.inventory_nodes : [
      for v in n.data_volumes : {
        key         = "${n.name}-${replace(v.device_name, "/dev/", "")}"
        node_index  = i
        node_name   = n.name
        device_name = v.device_name
        mount_point = v.mount_point
        size        = v.size
        type        = v.type
        az          = local.compute_subnet_azs[n.subnet_index % length(local.compute_subnet_azs)]
      }
    ]
  ])

  node_data_volumes_map = { for v in local.node_data_volumes : v.key => v }

  node_user_data = {
    for n in var.inventory_nodes : n.name => concat(
      [
        "#!/bin/bash",
        "set -euo pipefail",
        "hostnamectl set-hostname ${var.cluster_prefix}-${n.name}"
      ],
      flatten([
        for v in local.node_volumes_by_node[n.name] : [
          "mkfs.ext4 -F ${v.device_path}",
          "mkdir -p ${v.mount_point}",
          "mount ${v.device_path} ${v.mount_point}",
          "printf '%s %s ext4 defaults,nofail 0 2\\n' '${v.device_path}' '${v.mount_point}' >> /etc/fstab"
        ]
      ])
    )
  }
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = merge(local.common_tags, { Name = "${var.cluster_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${var.cluster_prefix}-igw" })
}

resource "aws_subnet" "public" {
  count = length(var.public_subnets)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = coalesce(var.public_subnets[count.index].availability_zone, local.azs[count.index % length(local.azs)])
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.cluster_prefix}-${var.public_subnets[count.index].name}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = length(var.private_subnets)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = coalesce(var.private_subnets[count.index].availability_zone, local.azs[count.index % length(local.azs)])
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.cluster_prefix}-${var.private_subnets[count.index].name}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${var.cluster_prefix}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnets)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = var.nat_gateway_enabled ? length(var.private_subnets) : 0

  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "${var.cluster_prefix}-nat-eip-${count.index}" })
}

resource "aws_nat_gateway" "main" {
  count = var.nat_gateway_enabled ? length(var.private_subnets) : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index % length(aws_subnet.public)].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "${var.cluster_prefix}-nat-${count.index}" })
}

resource "aws_route_table" "private" {
  count = length(var.private_subnets)

  vpc_id = aws_vpc.main.id

  dynamic "route" {
    for_each = var.nat_gateway_enabled ? [1] : []
    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.main[count.index].id
    }
  }

  tags = merge(local.common_tags, { Name = "${var.cluster_prefix}-private-rt-${count.index}" })
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnets)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# Security group
###############################################################################

resource "aws_security_group" "default" {
  name        = "${var.cluster_prefix}-default-sg"
  description = "Default security group for the ${var.cluster_prefix} cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all traffic between members of the group"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  dynamic "ingress" {
    for_each = var.ingress_cidr_rules
    content {
      description = ingress.value.description
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  egress {
    description = "Allow outbound traffic within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, { Name = "${var.cluster_prefix}-default-sg" })
}

###############################################################################
# Deployment SSH key pair
###############################################################################

resource "tls_private_key" "deployment" {
  count = var.ssh_public_key == "" ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "deployment" {
  key_name   = var.key_pair_name
  public_key = var.ssh_public_key != "" ? var.ssh_public_key : tls_private_key.deployment[0].public_key_openssh

  tags = merge(local.common_tags, { Name = var.key_pair_name })
}

###############################################################################
# Compute inventory nodes
###############################################################################

resource "aws_instance" "node" {
  count = length(var.inventory_nodes)

  ami                         = coalesce(var.inventory_nodes[count.index].ami_id, local.ami_id)
  instance_type               = var.inventory_nodes[count.index].instance_type
  subnet_id                   = local.compute_subnet_ids[var.inventory_nodes[count.index].subnet_index % length(local.compute_subnet_ids)]
  vpc_security_group_ids      = [aws_security_group.default.id]
  key_name                    = aws_key_pair.deployment.key_name
  ebs_optimized               = true
  monitoring                  = true
  associate_public_ip_address = false

  root_block_device {
    volume_size = var.inventory_nodes[count.index].root_volume.size
    volume_type = var.inventory_nodes[count.index].root_volume.type
    encrypted   = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  user_data = base64encode(join("\n", local.node_user_data[var.inventory_nodes[count.index].name]))

  tags = merge(local.common_tags, { Name = "${var.cluster_prefix}-${var.inventory_nodes[count.index].name}" })
}

resource "aws_eip" "node" {
  for_each = { for n in var.inventory_nodes : n.name => n if n.assign_elastic_ip }

  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "${var.cluster_prefix}-${each.key}-eip" })
}

resource "aws_eip_association" "node" {
  for_each = { for n in var.inventory_nodes : n.name => n if n.assign_elastic_ip }

  allocation_id = aws_eip.node[each.key].id
  instance_id   = aws_instance.node[local.node_index_by_name[each.key]].id
}

resource "aws_ebs_volume" "node" {
  for_each = local.node_data_volumes_map

  availability_zone = each.value.az
  size              = each.value.size
  type              = each.value.type
  encrypted         = true

  tags = merge(local.common_tags, {
    Name       = "${var.cluster_prefix}-${each.value.node_name}-${each.value.mount_point}"
    Node       = each.value.node_name
    MountPoint = each.value.mount_point
  })
}

resource "aws_volume_attachment" "node" {
  for_each = local.node_data_volumes_map

  device_name = each.value.device_name
  volume_id   = aws_ebs_volume.node[each.key].id
  instance_id = aws_instance.node[each.value.node_index].id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "security_group_id" {
  description = "ID of the default cluster security group."
  value       = aws_security_group.default.id
}

output "key_pair_name" {
  description = "Name of the deployment SSH key pair."
  value       = aws_key_pair.deployment.key_name
}

output "node_instance_ids" {
  description = "IDs of the provisioned inventory node instances."
  value       = aws_instance.node[*].id
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the VPC is created."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC and prefix for all child resources."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_private_subnets" {
  description = "When true, create two public subnets and two private subnets. When false, create four public subnets across four AZs."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "When true (and private subnets are enabled), deploy a redundant NAT Gateway in each public subnet with Elastic IPs and private route tables."
  type        = bool
  default     = false
}

variable "enable_nat_instance" {
  description = "When true (and private subnets are enabled), deploy a redundant NAT EC2 instance in each public subnet with private route tables pointing at their primary network interfaces."
  type        = bool
  default     = false
}

variable "enable_egress_only_igw" {
  description = "When true (and private subnets are enabled), create an Egress-Only Internet Gateway with IPv6 egress routes to ::/0."
  type        = bool
  default     = false
}

variable "subnet_cidrs" {
  description = "Ordered default subnet CIDR allocations for the VPC."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]
}

variable "nat_instance_type" {
  description = "Instance type used for NAT EC2 instances."
  type        = string
  default     = "m1.small"
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_name = var.vpc_name

  # Two public subnets (first two AZs, first two CIDRs) plus two private
  # subnets (same AZs, third/fourth CIDRs) when private subnets are enabled.
  # Otherwise four public subnets across four AZs using all four CIDRs.
  public_subnet_cidrs  = var.enable_private_subnets ? slice(var.subnet_cidrs, 0, 2) : slice(var.subnet_cidrs, 0, 4)
  private_subnet_cidrs = var.enable_private_subnets ? slice(var.subnet_cidrs, 2, 4) : []

  public_subnet_count  = length(local.public_subnet_cidrs)
  private_subnet_count = length(local.private_subnet_cidrs)

  # Egress routing strategies only apply to private routing infrastructure.
  nat_gateway_enabled  = var.enable_private_subnets && var.enable_nat_gateway
  nat_instance_enabled = var.enable_private_subnets && var.enable_nat_instance
  eigw_enabled         = var.enable_private_subnets && var.enable_egress_only_igw

  availability_zones = data.aws_availability_zones.available.names
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = local.eigw_enabled

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-igw"
  }
}

###############################################################################
# Security groups
###############################################################################

# Default VPC security group: self-referencing ingress and egress only.
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress {
    description = "Allow traffic from members of this security group"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    self        = true
  }

  egress {
    description = "Allow traffic to members of this security group"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    self        = true
  }

  tags = {
    Name = "${local.vpc_name}-default-sg"
  }
}

# Additional security group allowing inbound TLS (443).
resource "aws_security_group" "tls" {
  name        = "${local.vpc_name}-tls"
  description = "Allow inbound TLS traffic on port 443"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Inbound TLS"
    protocol    = "tcp"
    from_port   = 443
    to_port     = 443
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic within the VPC"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${local.vpc_name}-tls"
  }
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  count                   = local.public_subnet_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-public-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = local.private_subnet_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.availability_zones[count.index]

  tags = {
    Name = "${local.vpc_name}-private-${count.index + 1}"
  }
}

###############################################################################
# Public routing
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.public_subnet_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Private routing tables
###############################################################################

resource "aws_route_table" "private" {
  count  = local.private_subnet_count
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.private_subnet_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# Egress strategy: NAT Gateways (redundant, one per public subnet)
###############################################################################

resource "aws_eip" "nat" {
  count  = local.nat_gateway_enabled ? local.public_subnet_count : 0
  domain = "vpc"

  tags = {
    Name = "${local.vpc_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = local.nat_gateway_enabled ? local.public_subnet_count : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.vpc_name}-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route" "private_nat_gateway" {
  count                  = local.nat_gateway_enabled ? local.private_subnet_count : 0
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

###############################################################################
# Egress strategy: NAT instances (redundant, one per public subnet)
###############################################################################

data "aws_ami" "nat" {
  count       = local.nat_instance_enabled ? 1 : 0
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn-ami-vpc-nat-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_security_group" "nat_instance" {
  count       = local.nat_instance_enabled ? 1 : 0
  name        = "${local.vpc_name}-nat-instance"
  description = "Allow traffic from the VPC to NAT instances and outbound NAT traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all traffic from within the VPC"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.vpc_name}-nat-instance"
  }
}

resource "aws_instance" "nat" {
  count                       = local.nat_instance_enabled ? local.public_subnet_count : 0
  ami                         = data.aws_ami.nat[0].id
  instance_type               = var.nat_instance_type
  subnet_id                   = aws_subnet.public[count.index].id
  vpc_security_group_ids      = [aws_security_group.nat_instance[0].id]
  source_dest_check           = false
  associate_public_ip_address = true

  tags = {
    Name = "${local.vpc_name}-nat-instance-${count.index + 1}"
  }
}

resource "aws_route" "private_nat_instance" {
  count                  = local.nat_instance_enabled ? local.private_subnet_count : 0
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  network_interface_id   = aws_instance.nat[count.index].primary_network_interface_id
}

###############################################################################
# Egress strategy: Egress-Only Internet Gateway (IPv6 egress to ::/0)
###############################################################################

resource "aws_egress_only_internet_gateway" "main" {
  count  = local.eigw_enabled ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-eigw"
  }
}

resource "aws_route" "private_egress_only_igw" {
  count                       = local.eigw_enabled ? local.private_subnet_count : 0
  route_table_id              = aws_route_table.private[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main[0].id
}

###############################################################################
# Terraform & provider requirements
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

# The default (unaliased) AWS provider is configured externally by the
# deployment harness (region defaults to us-east-1). The aliased provider
# below targets the secondary region that hosts the replication destinations.
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

###############################################################################
# Input variables
###############################################################################

variable "environment" {
  description = "Environment name used to prefix the provisioned resources."
  type        = string
  default     = "benchmark"
}

variable "replica_region" {
  description = "Secondary AWS region that hosts the cross-region replication destinations."
  type        = string
  default     = "us-west-2"
}

variable "glacier_transition_days" {
  description = "Number of days after which access-log objects transition to Glacier."
  type        = number
  default     = 7
}

variable "expiration_days" {
  description = "Number of days after which access-log objects expire."
  type        = number
  default     = 30
}

###############################################################################
# Static lookups (account/partition only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Random suffix so bucket names stay globally unique across repeated runs
###############################################################################

resource "random_id" "suffix" {
  byte_length = 4
}

###############################################################################
# Local values
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  name_suffix = random_id.suffix.hex

  state_bucket_name         = "${var.environment}-tfstate-${local.name_suffix}"
  logs_bucket_name          = "${var.environment}-access-logs-${local.name_suffix}"
  replica_state_bucket_name = "${var.environment}-tfstate-replica-${local.name_suffix}"
  replica_logs_bucket_name  = "${var.environment}-access-logs-replica-${local.name_suffix}"

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Primary region buckets
###############################################################################

resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket_name

  tags = merge(local.common_tags, {
    Name    = local.state_bucket_name
    Purpose = "terraform-state"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "logs" {
  bucket = local.logs_bucket_name

  tags = merge(local.common_tags, {
    Name    = local.logs_bucket_name
    Purpose = "access-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

# State bucket: SSE-KMS with a customer-managed key.
resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

# Access logs bucket: default encryption with a dedicated customer-managed key.
resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logs.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

# The log-delivery-write canned ACL requires ACLs to be enabled on the bucket.
resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    object_ownership = "ObjectWriter"
  }
}

resource "aws_s3_bucket_acl" "logs" {
  bucket = aws_s3_bucket.logs.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.logs]
}

# Server access logging from the state bucket into the access logs bucket.
resource "aws_s3_bucket_logging" "state" {
  bucket = aws_s3_bucket.state.id

  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "state-access-logs/"
}

# Lifecycle management for the access logs bucket.
resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "glacier-transition-and-expiration"
    status = "Enabled"

    filter {}

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.expiration_days
    }
  }
}

###############################################################################
# Secondary region replica buckets
###############################################################################

resource "aws_s3_bucket" "replica_state" {
  provider = aws.replica
  bucket   = local.replica_state_bucket_name

  tags = merge(local.common_tags, {
    Name    = local.replica_state_bucket_name
    Purpose = "terraform-state-replica"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "replica_logs" {
  provider = aws.replica
  bucket   = local.replica_logs_bucket_name

  tags = merge(local.common_tags, {
    Name    = local.replica_logs_bucket_name
    Purpose = "access-logs-replica"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Replica state bucket: encrypted with its own customer-managed KMS key.
resource "aws_s3_bucket_server_side_encryption_configuration" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_state.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_logs.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

# Replica access logs bucket carries the same lifecycle rule as the primary.
resource "aws_s3_bucket_lifecycle_configuration" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  rule {
    id     = "glacier-transition-and-expiration"
    status = "Enabled"

    filter {}

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.expiration_days
    }
  }
}

###############################################################################
# Customer-managed KMS keys
###############################################################################

resource "aws_kms_key" "state" {
  description             = "Customer managed key for ${var.environment} Terraform state bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.state_bucket_name}-kms"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "replica_state" {
  provider                = aws.replica
  description             = "Customer managed key for ${var.environment} replica Terraform state bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.replica_state_bucket_name}-kms"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "logs" {
  description             = "Customer managed key for ${var.environment} access logs bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.logs_bucket_name}-kms"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "replica_logs" {
  provider                = aws.replica
  description             = "Customer managed key for ${var.environment} replica access logs bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.replica_logs_bucket_name}-kms"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Bucket policy: restrict all s3 actions to the owning account and require the
# bucket-owner-full-control ACL on incoming writes. Applied to both the state
# bucket and its replica.
###############################################################################

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid    = "RestrictToOwningAccountWithBucketOwnerFullControl"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json
}

data "aws_iam_policy_document" "replica_state_bucket" {
  statement {
    sid    = "RestrictToOwningAccountWithBucketOwnerFullControl"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["s3:*"]
    resources = [aws_s3_bucket.replica_state.arn, "${aws_s3_bucket.replica_state.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id
  policy   = data.aws_iam_policy_document.replica_state_bucket.json
}

###############################################################################
# IAM role + policy for S3 cross-region replication
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "${var.environment}-s3-replication-role-${local.name_suffix}"
  description        = "Role assumed by Amazon S3 to replicate state and access-log buckets cross-region"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "replication" {
  # Read the replication configuration and list the source buckets.
  statement {
    sid    = "AllowSourceBucketRead"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.state.arn,
      aws_s3_bucket.logs.arn,
    ]
  }

  # Read source object versions, ACLs and tags.
  statement {
    sid    = "AllowSourceObjectRead"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = [
      "${aws_s3_bucket.state.arn}/*",
      "${aws_s3_bucket.logs.arn}/*",
    ]
  }

  # Write (and delete) objects in the destination buckets, including delete
  # marker replication and tag replication.
  statement {
    sid    = "AllowDestinationObjectWrite"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = [
      "${aws_s3_bucket.replica_state.arn}/*",
      "${aws_s3_bucket.replica_logs.arn}/*",
    ]
  }

  # Use the source KMS key to decrypt and the replica KMS key to re-encrypt.
  statement {
    sid    = "AllowKmsUseForReplication"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.state.arn,
      aws_kms_key.logs.arn,
      aws_kms_key.replica_state.arn,
      aws_kms_key.replica_logs.arn,
    ]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "${var.environment}-s3-replication-policy-${local.name_suffix}"
  description = "Permissions for S3 cross-region replication of state and access-log buckets"
  policy      = data.aws_iam_policy_document.replication.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

###############################################################################
# Cross-region replication configuration for both source buckets
###############################################################################

resource "aws_s3_bucket_replication_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "state-cross-region-replication"
    status = "Enabled"

    filter {}

    # Replicate delete markers (in addition to object versions).
    delete_marker_replication {
      status = "Enabled"
    }

    # Replicate objects encrypted with SSE-KMS using the source key.
    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica_state.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_state.arn
      }
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.replication,
    aws_s3_bucket_versioning.state,
    aws_s3_bucket_versioning.replica_state,
    aws_kms_key.state,
    aws_kms_key.replica_state,
  ]
}

resource "aws_s3_bucket_replication_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "logs-cross-region-replication"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    # Replicate objects encrypted with SSE-KMS using the source key.
    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica_logs.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_logs.arn
      }
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.replication,
    aws_s3_bucket_versioning.logs,
    aws_s3_bucket_versioning.replica_logs,
    aws_kms_key.logs,
    aws_kms_key.replica_logs,
  ]
}

###############################################################################
# VPC Networking and Private Interface VPC Endpoints module
#
# Supports either provisioning a brand new VPC (default) or integrating with a
# pre-existing VPC / subnets / NAT gateway / security group when the relevant
# input variables are supplied.
###############################################################################

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Name to be used on all resources created by this module."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_id" {
  description = "Existing VPC ID. When set, no new VPC is created."
  type        = string
  default     = ""
}

variable "enable_dns_support" {
  description = "Whether to enable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Whether to enable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "map_public_ip_on_launch" {
  description = "Whether to auto-assign public IPs to instances in public subnets."
  type        = bool
  default     = false
}

variable "public_subnets" {
  description = "Map of availability zone to CIDR for public subnets. Defaults to a /24 map across two AZs."
  type        = map(string)
  default     = {}
}

variable "private_subnets" {
  description = "Map of availability zone to CIDR for private subnets. Defaults to a /24 map across two AZs."
  type        = map(string)
  default     = {}
}

variable "database_subnets" {
  description = "Map of availability zone to CIDR for database subnets. Defaults to a /24 map across two AZs."
  type        = map(string)
  default     = {}
}

variable "public_subnet_ids" {
  description = "Map of availability zone to pre-existing public subnet IDs (overrides subnet creation)."
  type        = map(string)
  default     = {}
}

variable "private_subnet_ids" {
  description = "Map of availability zone to pre-existing private subnet IDs (overrides subnet creation)."
  type        = map(string)
  default     = {}
}

variable "database_subnet_ids" {
  description = "Map of availability zone to pre-existing database subnet IDs (overrides subnet creation)."
  type        = map(string)
  default     = {}
}

variable "existing_nat_id" {
  description = "Pre-existing NAT Gateway ID used for outbound routing instead of creating a new one."
  type        = string
  default     = ""
}

variable "existing_security_group_id" {
  description = "Pre-existing security group ID to attach to the interface VPC endpoints."
  type        = string
  default     = ""
}

variable "vpc_endpoint_services" {
  description = "List of AWS service names to create interface VPC endpoints for."
  type        = list(string)
  default = [
    "ec2",
    "ecr.api",
    "ecr.dkr",
    "s3",
    "logs",
    "sts",
    "elasticloadbalancing",
    "autoscaling",
  ]
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  create_vpc = var.vpc_id == ""
  vpc_id     = local.create_vpc ? aws_vpc.this[0].id : var.vpc_id

  # Two default availability zones for the target region.
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  # Default CIDR maps (may be overridden by the *_subnets variables).
  public_subnet_cidrs = length(var.public_subnets) > 0 ? var.public_subnets : {
    for i, az in local.azs : az => cidrsubnet(var.vpc_cidr, 8, i + 1)
  }
  private_subnet_cidrs = length(var.private_subnets) > 0 ? var.private_subnets : {
    for i, az in local.azs : az => cidrsubnet(var.vpc_cidr, 8, i + 11)
  }
  database_subnet_cidrs = length(var.database_subnets) > 0 ? var.database_subnets : {
    for i, az in local.azs : az => cidrsubnet(var.vpc_cidr, 8, i + 21)
  }

  create_public   = length(var.public_subnet_ids) == 0
  create_private  = length(var.private_subnet_ids) == 0
  create_database = length(var.database_subnet_ids) == 0

  public_subnet_ids   = local.create_public ? aws_subnet.public[*].id : values(var.public_subnet_ids)
  private_subnet_ids  = local.create_private ? aws_subnet.private[*].id : values(var.private_subnet_ids)
  database_subnet_ids = local.create_database ? aws_subnet.database[*].id : values(var.database_subnet_ids)

  create_nat = var.existing_nat_id == "" && length(local.public_subnet_ids) > 0
  nat_id     = var.existing_nat_id != "" ? var.existing_nat_id : (local.create_nat ? aws_nat_gateway.this[0].id : null)

  # Plan-time known boolean so route "count" does not depend on the
  # (apply-time) NAT gateway ID.
  has_nat = var.existing_nat_id != "" || local.create_nat

  create_endpoint_sg = var.existing_security_group_id == ""
  endpoint_sg_id     = local.create_endpoint_sg ? aws_security_group.vpc_endpoints[0].id : var.existing_security_group_id
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "this" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = {
    Name = var.name
  }
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "this" {
  count = local.create_vpc ? 1 : 0

  vpc_id = local.vpc_id

  tags = {
    Name = var.name
  }
}

###############################################################################
# Public subnets
###############################################################################

resource "aws_subnet" "public" {
  count = local.create_public ? length(local.public_subnet_cidrs) : 0

  vpc_id                  = local.vpc_id
  cidr_block              = values(local.public_subnet_cidrs)[count.index]
  availability_zone       = keys(local.public_subnet_cidrs)[count.index]
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name = "${var.name}-public-${keys(local.public_subnet_cidrs)[count.index]}"
    Tier = "public"
  }
}

resource "aws_route_table" "public" {
  count = local.create_public ? 1 : 0

  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-public"
  }
}

resource "aws_route" "public_internet" {
  count = local.create_public && local.create_vpc ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = local.create_public ? length(local.public_subnet_cidrs) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# Private subnets
###############################################################################

resource "aws_subnet" "private" {
  count = local.create_private ? length(local.private_subnet_cidrs) : 0

  vpc_id            = local.vpc_id
  cidr_block        = values(local.private_subnet_cidrs)[count.index]
  availability_zone = keys(local.private_subnet_cidrs)[count.index]

  tags = {
    Name = "${var.name}-private-${keys(local.private_subnet_cidrs)[count.index]}"
    Tier = "private"
  }
}

resource "aws_route_table" "private" {
  count = local.create_private ? 1 : 0

  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-private"
  }
}

resource "aws_route" "private_nat" {
  count = local.create_private && local.has_nat ? 1 : 0

  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = local.nat_id
}

resource "aws_route_table_association" "private" {
  count = local.create_private ? length(local.private_subnet_cidrs) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

###############################################################################
# Database subnets
###############################################################################

resource "aws_subnet" "database" {
  count = local.create_database ? length(local.database_subnet_cidrs) : 0

  vpc_id            = local.vpc_id
  cidr_block        = values(local.database_subnet_cidrs)[count.index]
  availability_zone = keys(local.database_subnet_cidrs)[count.index]

  tags = {
    Name = "${var.name}-database-${keys(local.database_subnet_cidrs)[count.index]}"
    Tier = "database"
  }
}

resource "aws_db_subnet_group" "this" {
  name       = lower(var.name)
  subnet_ids = local.database_subnet_ids

  tags = {
    Name = lower(var.name)
  }
}

###############################################################################
# NAT Gateway (single, in the first public subnet)
###############################################################################

resource "aws_eip" "nat" {
  count = local.create_nat ? 1 : 0

  domain = "vpc"

  tags = {
    Name = "${var.name}-nat"
  }
}

resource "aws_nat_gateway" "this" {
  count = local.create_nat ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = local.public_subnet_ids[0]

  tags = {
    Name = "${var.name}-nat"
  }

  depends_on = [aws_internet_gateway.this]
}

###############################################################################
# Interface VPC endpoints security group
###############################################################################

resource "aws_security_group" "vpc_endpoints" {
  count = local.create_endpoint_sg ? 1 : 0

  name        = "${var.name}-vpc-endpoints"
  description = "Security group controlling access to interface VPC endpoints"
  vpc_id      = local.vpc_id

  ingress {
    description = "Allow HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow outbound traffic only within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.name}-vpc-endpoints"
  }
}

###############################################################################
# Interface VPC endpoints
###############################################################################

resource "aws_vpc_endpoint" "interface" {
  count = length(var.vpc_endpoint_services)

  vpc_id             = local.vpc_id
  service_name       = "com.amazonaws.${data.aws_region.current.region}.${var.vpc_endpoint_services[count.index]}"
  vpc_endpoint_type  = "Interface"
  subnet_ids         = local.private_subnet_ids
  security_group_ids = [local.endpoint_sg_id]
  # S3 interface endpoints cannot enable private DNS unless a matching gateway
  # endpoint exists in the VPC, so keep private DNS off for that service.
  private_dns_enabled = var.vpc_endpoint_services[count.index] == "s3" ? false : true

  tags = {
    Name = "${var.name}-${var.vpc_endpoint_services[count.index]}"
  }
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "The ID of the VPC (new or existing)."
  value       = local.vpc_id
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway (if created)."
  value       = local.create_vpc ? aws_internet_gateway.this[0].id : null
}

output "public_subnet_ids" {
  description = "List of public subnet IDs."
  value       = local.public_subnet_ids
}

output "private_subnet_ids" {
  description = "List of private subnet IDs."
  value       = local.private_subnet_ids
}

output "database_subnet_ids" {
  description = "List of database subnet IDs."
  value       = local.database_subnet_ids
}

output "database_subnet_group_name" {
  description = "Name of the RDS database subnet group."
  value       = aws_db_subnet_group.this.name
}

output "nat_gateway_id" {
  description = "The ID of the NAT Gateway used for outbound routing."
  value       = local.nat_id
}

output "vpc_endpoint_security_group_id" {
  description = "The security group ID attached to the interface VPC endpoints."
  value       = local.endpoint_sg_id
}

output "vpc_endpoint_ids" {
  description = "Map of service name to interface VPC endpoint ID."
  value       = { for idx, svc in var.vpc_endpoint_services : svc => aws_vpc_endpoint.interface[idx].id }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "app_shortcode" {
  description = "Short application code used as the prefix for the IAM role and instance profile names."
  type        = string
  default     = "bmk"

  validation {
    condition     = can(regex("^[a-z0-9]{2,10}$", var.app_shortcode))
    error_message = "The application shortcode must be between 2 and 10 lowercase alphanumeric characters."
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_cidr    = "10.8.0.0/16"
  subnet_cidr = "10.8.1.0/24"

  # Interface VPC endpoints required for SSM Session Manager to function
  # from an instance that has no internet access.
  interface_endpoints = {
    ssm         = "ssm"
    ec2messages = "ec2messages"
    ssmmessages = "ssmmessages"
    logs        = "logs"
  }

  common_tags = {
    Project = "ssm-session-manager-test"
  }
}

###############################################################################
# Data sources
###############################################################################

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

###############################################################################
# VPC and networking
###############################################################################

resource "aws_vpc" "test" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "ssm-test-vpc"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.test.id
  cidr_block              = local.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "ssm-test-private-subnet"
  })
}

###############################################################################
# Security groups
###############################################################################

# Common security group attached to every interface VPC endpoint.
# Allows inbound HTTPS only from within the VPC and has no egress rules.
resource "aws_security_group" "vpce" {
  name        = "ssm-test-vpce-sg"
  description = "Common security group for the SSM interface VPC endpoints"
  vpc_id      = aws_vpc.test.id

  ingress {
    description = "Allow HTTPS from the VPC CIDR to the interface endpoints"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "ssm-test-vpce-sg"
  })
}

# Security group attached to the test EC2 instance.
# No ingress rules; allows outbound HTTPS only within the VPC.
resource "aws_security_group" "instance" {
  name        = "ssm-test-instance-sg"
  description = "Security group for the SSM test EC2 instance"
  vpc_id      = aws_vpc.test.id

  egress {
    description = "Allow HTTPS to the interface endpoints within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "ssm-test-instance-sg"
  })
}

###############################################################################
# Interface VPC endpoints (private DNS enabled, auto-accepted within the VPC)
###############################################################################

resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoints

  vpc_id              = aws_vpc.test.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.vpce.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "ssm-test-${each.key}-endpoint"
  })
}

###############################################################################
# IAM: instance role, permissions and instance profile
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "test" {
  name_prefix        = "${var.app_shortcode}-ssm-test-"
  description        = "Instance role enabling SSM Session Manager for the test EC2 instance"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${var.app_shortcode}-ssm-test-role"
  })
}

data "aws_iam_policy_document" "instance" {
  # AWS Systems Manager core permissions required by the SSM agent.
  statement {
    sid    = "SSMCore"
    effect = "Allow"

    actions = [
      "ssm:DescribeAssociation",
      "ssm:GetDeployablePatchSnapshotForInstance",
      "ssm:GetDocument",
      "ssm:DescribeDocument",
      "ssm:GetManifest",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:ListAssociations",
      "ssm:PutInventory",
      "ssm:PutMetricData",
      "ssm:UpdateInstanceInformation",
    ]

    resources = ["*"]
  }

  # Session Manager data-channel messages.
  statement {
    sid    = "SSMMessages"
    effect = "Allow"

    actions = [
      "ssmmessages:CreateControlChannel",
      "ssmmessages:CreateDataChannel",
      "ssmmessages:OpenControlChannel",
      "ssmmessages:OpenDataChannel",
    ]

    resources = ["*"]
  }

  # EC2 message service used by the SSM agent.
  statement {
    sid    = "EC2Messages"
    effect = "Allow"

    actions = [
      "ec2messages:AckMessage",
      "ec2messages:FailMessage",
      "ec2messages:GetEndpoint",
      "ec2messages:GetMessages",
      "ec2messages:SendReply",
    ]

    resources = ["*"]
  }

  # CloudWatch Logs delivery for session/agent logging.
  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = ["*"]
  }

  # KMS data key generation for encrypted session logging.
  statement {
    sid    = "KMSDataKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]
  }

  # S3 object access used for patch/script artifacts.
  statement {
    sid    = "S3ObjectAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "test" {
  name   = "${var.app_shortcode}-ssm-test-policy"
  role   = aws_iam_role.test.id
  policy = data.aws_iam_policy_document.instance.json
}

resource "aws_iam_instance_profile" "test" {
  name_prefix = "${var.app_shortcode}-ssm-test-"
  role        = aws_iam_role.test.name

  tags = merge(local.common_tags, {
    Name = "${var.app_shortcode}-ssm-test-instance-profile"
  })
}

###############################################################################
# Test EC2 instance
###############################################################################

resource "aws_instance" "test" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = "t3.small"
  subnet_id                   = aws_subnet.private.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  iam_instance_profile        = aws_iam_instance_profile.test.name
  source_dest_check           = false
  associate_public_ip_address = false
  ebs_optimized               = true

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_type = "gp3"
    encrypted   = true
  }

  tags = merge(local.common_tags, {
    Name = "ssm-test-instance"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  region         = "us-east-1"
  vpc_cidr       = "10.0.0.0/16"
  public_cidrs   = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  private_cidrs  = ["10.0.10.0/24", "10.0.11.0/24", "10.0.12.0/24"]
  azs            = slice(data.aws_availability_zones.available.names, 0, 3)
  namespace_name = "private-fargate-crowdnews.hands-on.cloud.local"

  jumphost_private_ip = "10.0.0.10"

  interface_endpoints = {
    ecr_dkr        = "ecr.dkr"
    ecr_api        = "ecr.api"
    logs           = "logs"
    secretsmanager = "secretsmanager"
    ssm            = "ssm"
    kms            = "kms"
  }
}

###############################################################################
# VPC, Subnets, Gateways and Routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "private-fargate-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "private-fargate-igw"
  }
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "private-fargate-public-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "private-fargate-private-${count.index + 1}"
  }
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "private-fargate-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "private-fargate-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "private-fargate-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "private-fargate-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# VPC Endpoints
###############################################################################

resource "aws_security_group" "vpc_endpoint" {
  name        = "private-fargate-vpc-endpoint-sg"
  description = "Allow inbound HTTPS from the VPC CIDR to interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "private-fargate-vpc-endpoint-sg"
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${local.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "private-fargate-s3-endpoint"
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${local.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint.id]
  private_dns_enabled = true

  tags = {
    Name = "private-fargate-${each.key}-endpoint"
  }
}

###############################################################################
# Service Discovery (Cloud Map)
###############################################################################

resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = local.namespace_name
  description = "Private DNS namespace for internal service discovery"
  vpc         = aws_vpc.main.id

  tags = {
    Name = "private-fargate-namespace"
  }
}

resource "aws_service_discovery_service" "nginx" {
  name = "nginx"

  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.main.id

    dns_records {
      ttl  = 10
      type = "A"
    }

    dns_records {
      ttl  = 10
      type = "SRV"
    }

    routing_policy = "MULTIVALUE"
  }

  health_check_custom_config {
    failure_threshold = 1
  }

  tags = {
    Name = "private-fargate-nginx"
  }
}

###############################################################################
# ECR Repository
###############################################################################

resource "aws_ecr_repository" "app" {
  name                 = "private-fargate-nginx"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = {
    Name = "private-fargate-nginx"
  }
}

###############################################################################
# CloudWatch Log Group
###############################################################################

resource "aws_cloudwatch_log_group" "app" {
  name              = "/ecs/private-fargate-nginx"
  retention_in_days = 30

  tags = {
    Name = "private-fargate-nginx-logs"
  }
}

###############################################################################
# ECS Cluster
###############################################################################

resource "aws_ecs_cluster" "main" {
  name = "private-fargate-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = {
    Name = "private-fargate-cluster"
  }
}

###############################################################################
# IAM - ECS Task Execution Role
###############################################################################

resource "aws_iam_role" "ecs_task_execution" {
  name = "private-fargate-ecs-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "private-fargate-ecs-execution-role"
  }
}

resource "aws_iam_role_policy" "ecs_task_execution" {
  name = "private-fargate-ecs-execution-policy"
  role = aws_iam_role.ecs_task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EcrAuthorization"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken"
        ]
        Resource = "*"
      },
      {
        Sid    = "EcrPull"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = aws_ecr_repository.app.arn
      },
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.app.arn}:*"
      },
      {
        Sid    = "SsmParameterAccess"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:ssm:${local.region}:${data.aws_caller_identity.current.account_id}:parameter/private-fargate/*"
      }
    ]
  })
}

###############################################################################
# IAM - ECS Task Role
###############################################################################

resource "aws_iam_role" "ecs_task" {
  name = "private-fargate-ecs-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "private-fargate-ecs-task-role"
  }
}

resource "aws_iam_role_policy" "ecs_task" {
  name = "private-fargate-ecs-task-policy"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.app.arn}:*"
      },
      {
        Sid    = "SsmParameterAccess"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:ssm:${local.region}:${data.aws_caller_identity.current.account_id}:parameter/private-fargate/*"
      },
      {
        Sid    = "ServiceDiscovery"
        Effect = "Allow"
        Action = [
          "servicediscovery:DiscoverInstances",
          "servicediscovery:GetNamespace",
          "servicediscovery:GetService",
          "servicediscovery:RegisterInstance",
          "servicediscovery:DeregisterInstance"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# ECS Task Definition
###############################################################################

resource "aws_ecs_task_definition" "app" {
  family                   = "private-fargate-nginx"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "nginx"
      image     = "${aws_ecr_repository.app.repository_url}:latest"
      essential = true

      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE_ID"
          value = aws_service_discovery_private_dns_namespace.main.id
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.app.name
          "awslogs-region"        = local.region
          "awslogs-stream-prefix" = "nginx"
        }
      }

      linuxParameters = {
        initProcessEnabled = true
      }
    }
  ])

  tags = {
    Name = "private-fargate-nginx"
  }
}

###############################################################################
# ECS Service Security Group
###############################################################################

resource "aws_security_group" "ecs_task" {
  name        = "private-fargate-ecs-task-sg"
  description = "Allow inbound HTTP from the VPC to the NGINX task"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NGINX HTTP from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "private-fargate-ecs-task-sg"
  }
}

###############################################################################
# ECS Fargate Service
###############################################################################

resource "aws_ecs_service" "app" {
  name            = "private-fargate-nginx-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_task.id]
    assign_public_ip = false
  }

  service_registries {
    registry_arn   = aws_service_discovery_service.nginx.arn
    container_name = "nginx"
    container_port = 80
  }

  tags = {
    Name = "private-fargate-nginx-service"
  }

  depends_on = [
    aws_iam_role_policy.ecs_task_execution,
    aws_iam_role_policy.ecs_task,
  ]
}

###############################################################################
# EC2 SSM Jumphost
###############################################################################

resource "aws_iam_role" "jumphost" {
  name = "private-fargate-jumphost-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "private-fargate-jumphost-role"
  }
}

resource "aws_iam_role_policy_attachment" "jumphost_ssm" {
  role       = aws_iam_role.jumphost.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "jumphost" {
  name = "private-fargate-jumphost-profile"
  role = aws_iam_role.jumphost.name

  tags = {
    Name = "private-fargate-jumphost-profile"
  }
}

resource "aws_security_group" "jumphost" {
  name        = "private-fargate-jumphost-sg"
  description = "Allow all inbound traffic from the VPC to the jumphost"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "private-fargate-jumphost-sg"
  }
}

resource "aws_network_interface" "jumphost" {
  subnet_id       = aws_subnet.public[0].id
  private_ips     = [local.jumphost_private_ip]
  security_groups = [aws_security_group.jumphost.id]

  tags = {
    Name = "private-fargate-jumphost-eni"
  }
}

resource "aws_instance" "jumphost" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.micro"

  network_interface {
    network_interface_id = aws_network_interface.jumphost.id
    device_index         = 0
  }

  iam_instance_profile = aws_iam_instance_profile.jumphost.name

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 8
    encrypted             = true
    delete_on_termination = true
  }

  tags = {
    Name = "private-fargate-jumphost"
  }

  depends_on = [aws_iam_instance_profile.jumphost]
}

###############################################################################
# Outputs
###############################################################################

output "nginx_service_discovery_dns_name" {
  description = "Private service discovery DNS name of the NGINX service"
  value       = "${aws_service_discovery_service.nginx.name}.${aws_service_discovery_private_dns_namespace.main.name}"
}

output "nginx_curl_command" {
  description = "Exact curl command to reach the NGINX service via its private service discovery DNS name"
  value       = "curl http://${aws_service_discovery_service.nginx.name}.${aws_service_discovery_private_dns_namespace.main.name}"
}

# =============================================================================
# Benchmark environment: t3.micro Amazon Linux 2 EC2 + supporting networking
# and identity infrastructure in a greenfield AWS account.
# =============================================================================

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "project" {
  description = "Project name used as the first component of the naming convention."
  type        = string
  default     = "benchmark"
}

variable "application" {
  description = "Application name used as the second component of the naming convention."
  type        = string
  default     = "compute"
}

variable "environment" {
  description = "Deployment environment used as the third component of the naming convention."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "instance_type" {
  description = "EC2 instance type."
  type        = string
  default     = "t3.micro"
}

variable "root_volume_size" {
  description = "Size (GiB) of the encrypted root EBS volume."
  type        = number
  default     = 20
}

variable "create_ssh_key" {
  description = "When true, generate an SSH key pair and attach it to the instance."
  type        = bool
  default     = false
}

variable "associate_elastic_ip" {
  description = "When true, allocate and associate a static Elastic IP with the network interface."
  type        = bool
  default     = false
}

variable "attach_ssm_managed_policy" {
  description = "When true, attach the AWS managed AmazonSSMManagedInstanceCore policy to the role."
  type        = bool
  default     = true
}

variable "allowed_ssh_cidr" {
  description = "CIDR permitted to reach SSH when an SSH key pair is created."
  type        = string
  default     = "10.0.0.0/16"
}

variable "custom_routes" {
  description = "Additional route definitions injected into the public route table, keyed by a unique name."
  type = map(object({
    destination_cidr_block    = string
    gateway_id                = optional(string)
    nat_gateway_id            = optional(string)
    network_interface_id      = optional(string)
    vpc_peering_connection_id = optional(string)
    transit_gateway_id        = optional(string)
  }))
  default = {}
}

# -----------------------------------------------------------------------------
# Static provider metadata lookups
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# -----------------------------------------------------------------------------
# Local naming / tagging convention
#   <project>-<application>-<environment>[-<availability-zone>]
# -----------------------------------------------------------------------------
locals {
  name_prefix    = "${var.project}-${var.application}-${var.environment}"
  availability_zone = data.aws_availability_zones.available.names[0]
  name_prefix_az = "${local.name_prefix}-${local.availability_zone}"

  common_tags = {
    Project     = var.project
    Application = var.application
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking: VPC, internet gateway, public subnet
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = local.availability_zone
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name             = "${local.name_prefix_az}-public-subnet"
    AvailabilityZone = local.availability_zone
    Tier             = "public"
  })
}

# -----------------------------------------------------------------------------
# Routing: public route table, default route, custom routes, association
# -----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name             = "${local.name_prefix_az}-public-rt"
    AvailabilityZone = local.availability_zone
  })
}

resource "aws_route" "default_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "custom" {
  for_each = var.custom_routes

  route_table_id            = aws_route_table.public.id
  destination_cidr_block    = each.value.destination_cidr_block
  gateway_id                = each.value.gateway_id
  nat_gateway_id            = each.value.nat_gateway_id
  network_interface_id      = each.value.network_interface_id
  vpc_peering_connection_id = each.value.vpc_peering_connection_id
  transit_gateway_id        = each.value.transit_gateway_id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security group for the dedicated network interface (SSM management)
# -----------------------------------------------------------------------------
resource "aws_security_group" "main" {
  name        = "${local.name_prefix}-ec2-sg"
  description = "Management security group for the benchmark EC2 instance"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.create_ssh_key ? [1] : []
    content {
      description = "SSH access from approved CIDR"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = [var.allowed_ssh_cidr]
    }
  }

  egress {
    description = "HTTPS egress within the VPC for SSM Session Manager and package management"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix_az}-ec2-sg"
  })
}

# -----------------------------------------------------------------------------
# Dedicated network interface (no public IP auto-assignment)
# -----------------------------------------------------------------------------
resource "aws_network_interface" "main" {
  subnet_id       = aws_subnet.public.id
  security_groups = [aws_security_group.main.id]

  tags = merge(local.common_tags, {
    Name             = "${local.name_prefix_az}-eni"
    AvailabilityZone = local.availability_zone
  })
}

# -----------------------------------------------------------------------------
# Optional SSH key pair (generated when requested)
# -----------------------------------------------------------------------------
resource "tls_private_key" "main" {
  count = var.create_ssh_key ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "main" {
  count = var.create_ssh_key ? 1 : 0

  key_name   = "${local.name_prefix}-key"
  public_key = tls_private_key.main[0].public_key_openssh

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-key"
  })
}

# -----------------------------------------------------------------------------
# Optional static Elastic IP (allocate + associate when requested)
# -----------------------------------------------------------------------------
resource "aws_eip" "main" {
  count = var.associate_elastic_ip ? 1 : 0

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name             = "${local.name_prefix_az}-eip"
    AvailabilityZone = local.availability_zone
  })
}

resource "aws_eip_association" "main" {
  count = var.associate_elastic_ip ? 1 : 0

  allocation_id        = aws_eip.main[0].id
  network_interface_id = aws_network_interface.main.id
}

# -----------------------------------------------------------------------------
# IAM: role trusted by EC2 + SSM, Session Manager policy, instance profile
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEc2AndSsmAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com", "ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "main" {
  name               = "${local.name_prefix}-ec2-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  description        = "Instance role for the benchmark EC2 instance"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-role"
  })
}

data "aws_iam_policy_document" "ssm_session_manager" {
  statement {
    sid    = "SSMSessionManagerControlChannel"
    effect = "Allow"
    actions = [
      "ssmmessages:CreateControlChannel",
      "ssmmessages:OpenControlChannel",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSMSessionManagerDataChannel"
    effect = "Allow"
    actions = [
      "ssmmessages:CreateDataChannel",
      "ssmmessages:OpenDataChannel",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSMSessionManagerInstanceRegistration"
    effect = "Allow"
    actions = [
      "ssm:UpdateInstanceInformation",
      "ssm:DescribeAssociation",
      "ssm:GetDeployablePatchSnapshotForInstance",
      "ssm:GetDocument",
      "ssm:DescribeDocument",
      "ssm:ListAssociations",
      "ssm:ListInstanceAssociations",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ssm_session_manager" {
  name        = "${local.name_prefix}-ssm-session-manager"
  description = "Grants SSM Session Manager control and data channel permissions"
  policy      = data.aws_iam_policy_document.ssm_session_manager.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssm-session-manager"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_session_manager" {
  role       = aws_iam_role.main.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

resource "aws_iam_role_policy_attachment" "ssm_managed_core" {
  count = var.attach_ssm_managed_policy ? 1 : 0

  role       = aws_iam_role.main.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "main" {
  name = "${local.name_prefix}-ec2-profile"
  role = aws_iam_role.main.name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-profile"
  })
}

# -----------------------------------------------------------------------------
# EC2 instance: t3.micro Amazon Linux 2, IMDSv2 enforced, 20 GB encrypted root
# -----------------------------------------------------------------------------
resource "aws_instance" "main" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = var.instance_type
  key_name      = var.create_ssh_key ? aws_key_pair.main[0].key_name : null

  iam_instance_profile = aws_iam_instance_profile.main.name

  network_interface {
    network_interface_id = aws_network_interface.main.id
    device_index         = 0
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "enabled"
  }

  root_block_device {
    volume_size           = var.root_volume_size
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true

    tags = merge(local.common_tags, {
      Name             = "${local.name_prefix_az}-root-volume"
      AvailabilityZone = local.availability_zone
    })
  }

  tags = merge(local.common_tags, {
    Name             = "${local.name_prefix_az}-ec2"
    AvailabilityZone = local.availability_zone
    OS               = "Amazon Linux 2"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "ec2_instance_id" {
  description = "ID of the EC2 instance."
  value       = aws_instance.main.id
}

output "ec2_instance_arn" {
  description = "ARN of the EC2 instance."
  value       = aws_instance.main.arn
}

output "iam_role_id" {
  description = "Name (ID) of the IAM role."
  value       = aws_iam_role.main.id
}

output "iam_role_arn" {
  description = "ARN of the IAM role."
  value       = aws_iam_role.main.arn
}

output "iam_instance_profile_id" {
  description = "Name (ID) of the IAM instance profile."
  value       = aws_iam_instance_profile.main.id
}

output "iam_instance_profile_arn" {
  description = "ARN of the IAM instance profile."
  value       = aws_iam_instance_profile.main.arn
}

output "route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "route_table_arn" {
  description = "ARN of the public route table."
  value       = aws_route_table.public.arn
}

output "subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "subnet_arn" {
  description = "ARN of the public subnet."
  value       = aws_subnet.public.arn
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
  }
}

# Secondary provider used exclusively for the disaster-recovery replica bucket
# and its dedicated KMS key. The default provider (region supplied by the
# deployment environment) owns everything in the primary region.
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

data "aws_caller_identity" "current" {}

variable "primary_region" {
  description = "Region that hosts the primary Terraform remote state bucket."
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "Region that hosts the disaster-recovery replica state bucket."
  type        = string
  default     = "us-west-2"
}

variable "eks_stacks" {
  description = "Map of EKS stack names to the AWS region each stack is deployed in."
  type        = map(string)
  default = {
    "eks-dev"     = "us-east-1"
    "eks-staging" = "us-east-1"
    "eks-prod"    = "us-west-2"
  }
}

locals {
  account_id = data.aws_caller_identity.current.account_id

  state_management_tags = {
    Project     = "eks-terraform-state"
    ManagedBy   = "Terraform"
    Environment = "shared-services"
    Purpose     = "terraform-remote-state"
    Component   = "state-management"
  }

  primary_bucket_name = "eks-tfstate-${local.account_id}-${var.primary_region}"
  replica_bucket_name = "eks-tfstate-${local.account_id}-${var.replica_region}"
}

# ---------------------------------------------------------------------------
# KMS keys
# ---------------------------------------------------------------------------

resource "aws_kms_key" "primary" {
  description             = "CMK protecting the primary EKS Terraform state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.state_management_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name          = "alias/eks-tfstate-primary"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "CMK protecting the replica EKS Terraform state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.state_management_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name          = "alias/eks-tfstate-replica"
  target_key_id = aws_kms_key.replica.key_id
}

# ---------------------------------------------------------------------------
# Primary state bucket (us-east-1)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name
  tags   = local.state_management_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

data "aws_iam_policy_document" "primary_bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = data.aws_iam_policy_document.primary_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.primary]
}

# ---------------------------------------------------------------------------
# Replica state bucket (secondary region, disaster recovery)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = local.replica_bucket_name
  tags     = local.state_management_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

data "aws_iam_policy_document" "replica_bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  policy   = data.aws_iam_policy_document.replica_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

# ---------------------------------------------------------------------------
# Cross-region replication IAM role and policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ReplicationAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "eks-tfstate-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json
  tags               = local.state_management_tags
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "ReadSourceBucket"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:GetBucketVersioning",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    sid    = "ReadSourceObjects"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    sid    = "DecryptSourceObjects"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.primary.arn]
  }

  statement {
    sid    = "ReplicateObjects"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.replica.arn}/*"]
  }

  statement {
    sid    = "EncryptReplicasAtDestination"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.replica.arn]
  }
}

resource "aws_iam_role_policy" "replication" {
  name   = "eks-tfstate-replication-policy"
  role   = aws_iam_role.replication.id
  policy = data.aws_iam_policy_document.replication.json
}

resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-all-kms-objects"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy.replication,
  ]
}

# ---------------------------------------------------------------------------
# Per-stack state locking tables
# ---------------------------------------------------------------------------

resource "aws_dynamodb_table" "state_lock" {
  for_each = var.eks_stacks

  name         = "eks-tfstate-lock-${each.key}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.primary.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.state_management_tags, {
    Stack       = each.key
    StackRegion = each.value
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Per-stack IAM policies scoped to that stack's lock table, state prefix and key
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "stack" {
  for_each = var.eks_stacks

  statement {
    sid    = "StateLocking"
    effect = "Allow"

    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:DeleteItem",
    ]

    resources = [aws_dynamodb_table.state_lock[each.key].arn]
  }

  statement {
    sid    = "StateBucketPrefix"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]

    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/${each.key}/*",
    ]
  }

  statement {
    sid    = "StateEncryptionKey"
    effect = "Allow"

    actions = [
      "kms:DescribeKey",
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.primary.arn]
  }
}

resource "aws_iam_policy" "stack" {
  for_each = var.eks_stacks

  name        = "eks-tfstate-access-${each.key}"
  description = "Remote state access for the ${each.key} EKS stack"
  policy      = data.aws_iam_policy_document.stack[each.key].json

  tags = merge(local.state_management_tags, {
    Stack       = each.key
    StackRegion = each.value
  })
}

# ---------------------------------------------------------------------------
# Generated backend.tf files for each stack
# ---------------------------------------------------------------------------

resource "local_file" "backend" {
  for_each = var.eks_stacks

  filename = "${path.module}/eks-stacks/${each.key}/backend.tf"

  content = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.primary.id}"
        key            = "${each.key}/terraform.tfstate"
        region         = "${var.primary_region}"
        dynamodb_table = "${aws_dynamodb_table.state_lock[each.key].name}"
        kms_key_id     = "${aws_kms_key.primary.arn}"
        encrypt        = true
      }
    }
  EOT
}

locals {
  user_pool_name        = "box_things"
  app_client_name       = "box_things_client"
  callback_url          = "https://example.com/callback"
  logout_url            = "https://example.com/logout"
  token_validity_minutes = 60
}

resource "aws_cognito_user_pool" "box_things" {
  name = local.user_pool_name

  # Allow users to sign up and sign in with their email address.
  alias_attributes         = ["email"]
  auto_verified_attributes = ["email"]

  # Allow self sign-up.
  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  # Strong password policy: minimum 8 characters, mixed character types.
  password_policy {
    minimum_length                   = 8
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    require_uppercase                = true
    temporary_password_validity_days = 7
  }

  # Multi-factor authentication disabled.
  mfa_configuration = "OFF"

  # Auto-verify email via a confirmation link.
  verification_message_template {
    default_email_option = "CONFIRM_WITH_LINK"
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "box_things_client" {
  name         = local.app_client_name
  user_pool_id = aws_cognito_user_pool.box_things.id

  # 60-minute access and ID tokens.
  access_token_validity = local.token_validity_minutes
  id_token_validity     = local.token_validity_minutes

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  refresh_token_validity = 30

  # Supported authentication flows.
  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  callback_urls = [local.callback_url]
  logout_urls   = [local.logout_url]

  supported_identity_providers = ["COGNITO"]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

locals {
  # Configurable map of users. The key is the IAM user name and the value is
  # the value of the "Owner" tag used to determine group membership.
  users = {
    dev1  = "Devel"
    dev2  = "Devel"
    guest = "Guest"
  }

  devel_group_name = "Ersia_Devel_Group"
  guest_group_name = "Ersia_Guest_Group"

  # AWS-managed policy names attached to each group.
  devel_policy_name = "ReadOnlyAccess"
  guest_policy_name = "IAMReadOnlyAccess"

  # Owner tag value that maps to the developer group.
  devel_owner = "Devel"
}

# Well-known AWS-managed policies (static, account-independent lookups).
data "aws_iam_policy" "read_only_access" {
  name = local.devel_policy_name
}

data "aws_iam_policy" "iam_read_only_access" {
  name = local.guest_policy_name
}

resource "aws_iam_group" "devel" {
  name = local.devel_group_name
}

resource "aws_iam_group" "guest" {
  name = local.guest_group_name
}

resource "aws_iam_group_policy_attachment" "devel" {
  group      = aws_iam_group.devel.name
  policy_arn = data.aws_iam_policy.read_only_access.arn
}

resource "aws_iam_group_policy_attachment" "guest" {
  group      = aws_iam_group.guest.name
  policy_arn = data.aws_iam_policy.iam_read_only_access.arn
}

resource "aws_iam_user" "users" {
  for_each = local.users

  name = each.key

  tags = {
    Owner = each.value
  }
}

# Joins each user to the developer group when its Owner tag is "Devel",
# otherwise the user joins the guest group.
resource "aws_iam_user_group_membership" "users" {
  for_each = local.users

  user = aws_iam_user.users[each.key].name

  groups = [
    each.value == local.devel_owner
    ? aws_iam_group.devel.name
    : aws_iam_group.guest.name
  ]
}

###############################################################################
# Random two-word pet name used for both the WebSocket API and the SQS queue
###############################################################################

resource "random_pet" "this" {
  length = 2
}

locals {
  name = random_pet.this.id
}

###############################################################################
# Customer managed KMS key (with automatic rotation) used to encrypt the queue
###############################################################################

resource "aws_kms_key" "this" {
  description             = "Customer managed key for ${local.name} SQS queue encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# SQS queue (server-side encrypted with the customer managed KMS key)
###############################################################################

resource "aws_sqs_queue" "this" {
  name                              = local.name
  kms_master_key_id                 = aws_kms_key.this.id
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# CloudWatch log group for API Gateway access logs
###############################################################################

resource "aws_cloudwatch_log_group" "this" {
  name              = "/aws/apigateway/${local.name}"
  retention_in_days = 1
}

###############################################################################
# IAM execution role assumed by API Gateway (SQS + CloudWatch Logs access)
###############################################################################

data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    sid     = "ApiGatewayAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "this" {
  name               = "${local.name}-apigw-role"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json
}

data "aws_iam_policy_document" "apigw" {
  statement {
    sid       = "SendMessagesToQueue"
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.this.arn]
  }

  statement {
    sid     = "UseKmsKeyForQueueEncryption"
    effect  = "Allow"
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
    ]
    resources = [aws_kms_key.this.arn]
  }

  statement {
    sid     = "ApiGatewayCloudWatchLogs"
    effect  = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "this" {
  name   = "${local.name}-apigw-policy"
  role   = aws_iam_role.this.id
  policy = data.aws_iam_policy_document.apigw.json
}

###############################################################################
# Account-level CloudWatch Logs role required for API Gateway access logging
###############################################################################

resource "aws_api_gateway_account" "this" {
  cloudwatch_role_arn = aws_iam_role.this.arn

  depends_on = [aws_iam_role_policy.this]
}

###############################################################################
# WebSocket API
###############################################################################

resource "aws_apigatewayv2_api" "this" {
  name                       = local.name
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

###############################################################################
# $connect - MOCK integration returning HTTP 200
###############################################################################

resource "aws_apigatewayv2_integration" "connect" {
  api_id             = aws_apigatewayv2_api.this.id
  integration_type   = "MOCK"
  integration_method = "POST"

  request_templates = {
    "application/json" = jsonencode({ statusCode = 200 })
  }
}

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

###############################################################################
# $default - forward the raw message body to SQS via SQS-SendMessage
###############################################################################

resource "aws_apigatewayv2_integration" "default" {
  api_id              = aws_apigatewayv2_api.this.id
  integration_type    = "AWS_PROXY"
  integration_subtype = "SQS-SendMessage"
  credentials_arn     = aws_iam_role.this.arn

  request_parameters = {
    "QueueUrl"    = aws_sqs_queue.this.id
    "MessageBody" = "$request.body"
  }
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default.id}"
}

resource "aws_apigatewayv2_route_response" "default" {
  api_id             = aws_apigatewayv2_api.this.id
  route_id           = aws_apigatewayv2_route.default.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration_response" "default" {
  api_id                   = aws_apigatewayv2_api.this.id
  integration_id           = aws_apigatewayv2_integration.default.id
  integration_response_key = "$default"
}

###############################################################################
# $disconnect - send a fixed "Client disconnected" message to the same queue
###############################################################################

resource "aws_apigatewayv2_integration" "disconnect" {
  api_id              = aws_apigatewayv2_api.this.id
  integration_type    = "AWS_PROXY"
  integration_subtype = "SQS-SendMessage"
  credentials_arn     = aws_iam_role.this.arn

  request_parameters = {
    "QueueUrl"    = aws_sqs_queue.this.id
    "MessageBody" = "Client disconnected"
  }
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

###############################################################################
# Auto-deployed stage "dev" with CloudWatch access logging
###############################################################################

resource "aws_apigatewayv2_stage" "this" {
  api_id      = aws_apigatewayv2_api.this.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.this.arn

    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestTime    = "$context.requestTime"
      routeKey       = "$context.routeKey"
      status         = "$context.status"
      connectionId   = "$context.connectionId"
      integrationErr = "$context.integrationErrorMessage"
    })
  }

  depends_on = [aws_api_gateway_account.this]
}

###############################################################################
# Outputs
###############################################################################

output "websocket_endpoint_url" {
  description = "Full WebSocket endpoint URL including the stage name"
  value       = aws_apigatewayv2_stage.this.invoke_url
}

###############################################################################
# Variables - CIDR, tag and DNS values for each standalone test VPC
###############################################################################

variable "instance_tenancy" {
  description = "The allowed tenancy of instances launched into the VPCs."
  type        = string
  default     = "default"
}

# --- VPC 1: "XXXX-vpc-test" (DNS support enabled) ----------------------------
variable "vpc_test_cidr_block" {
  description = "CIDR block for the XXXX-vpc-test VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_test_name" {
  description = "Name tag for the XXXX-vpc-test VPC."
  type        = string
  default     = "XXXX-vpc-test"
}

variable "vpc_test_enable_dns_support" {
  description = "Whether DNS support is enabled for the XXXX-vpc-test VPC."
  type        = bool
  default     = true
}

variable "vpc_test_enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled for the XXXX-vpc-test VPC."
  type        = bool
  default     = false
}

# --- VPC 2: "Default" (DNS support + DNS hostnames enabled) ------------------
variable "default_vpc_cidr_block" {
  description = "CIDR block for the Default VPC."
  type        = string
  default     = "172.31.0.0/16"
}

variable "default_vpc_name" {
  description = "Name tag for the Default VPC."
  type        = string
  default     = "Default"
}

variable "default_vpc_enable_dns_support" {
  description = "Whether DNS support is enabled for the Default VPC."
  type        = bool
  default     = true
}

variable "default_vpc_enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled for the Default VPC."
  type        = bool
  default     = true
}

# --- VPC 3: "eksctl-eks-cluster-px-cluster/VPC" (DNS enabled + eksctl tags) ---
variable "eksctl_vpc_cidr_block" {
  description = "CIDR block for the eksctl cluster VPC."
  type        = string
  default     = "192.168.0.0/16"
}

variable "eksctl_vpc_name" {
  description = "Name tag for the eksctl cluster VPC."
  type        = string
  default     = "eksctl-eks-cluster-px-cluster/VPC"
}

variable "eksctl_vpc_enable_dns_support" {
  description = "Whether DNS support is enabled for the eksctl cluster VPC."
  type        = bool
  default     = true
}

variable "eksctl_vpc_enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled for the eksctl cluster VPC."
  type        = bool
  default     = true
}

variable "eksctl_cluster_name" {
  description = "eksctl cluster name recorded on the eksctl cluster VPC."
  type        = string
  default     = "eks-cluster-px"
}

variable "eksctl_version" {
  description = "eksctl version recorded on the eksctl cluster VPC."
  type        = string
  default     = "0.94.0"
}

# --- VPC 4: untagged (DNS support enabled) -----------------------------------
variable "untagged_vpc_cidr_block" {
  description = "CIDR block for the untagged VPC."
  type        = string
  default     = "10.0.0.0/24"
}

variable "untagged_vpc_enable_dns_support" {
  description = "Whether DNS support is enabled for the untagged VPC."
  type        = bool
  default     = true
}

variable "untagged_vpc_enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled for the untagged VPC."
  type        = bool
  default     = false
}

# --- VPC 5: empty Name tag (DNS support enabled) -----------------------------
variable "empty_name_vpc_cidr_block" {
  description = "CIDR block for the VPC with an empty Name tag."
  type        = string
  default     = "10.0.0.0/16"
}

variable "empty_name_vpc_name" {
  description = "Name tag for the VPC with an empty Name tag."
  type        = string
  default     = ""
}

variable "empty_name_vpc_enable_dns_support" {
  description = "Whether DNS support is enabled for the VPC with an empty Name tag."
  type        = bool
  default     = true
}

variable "empty_name_vpc_enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled for the VPC with an empty Name tag."
  type        = bool
  default     = false
}

###############################################################################
# VPC 1: "XXXX-vpc-test"
###############################################################################

resource "aws_vpc" "vpc_test" {
  cidr_block           = var.vpc_test_cidr_block
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = var.vpc_test_enable_dns_support
  enable_dns_hostnames = var.vpc_test_enable_dns_hostnames

  tags = {
    Name = var.vpc_test_name
  }
}

###############################################################################
# VPC 2: "Default"
###############################################################################

resource "aws_vpc" "default" {
  cidr_block           = var.default_vpc_cidr_block
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = var.default_vpc_enable_dns_support
  enable_dns_hostnames = var.default_vpc_enable_dns_hostnames

  tags = {
    Name = var.default_vpc_name
  }
}

###############################################################################
# VPC 3: "eksctl-eks-cluster-px-cluster/VPC" with eksctl tags
###############################################################################

resource "aws_vpc" "eksctl" {
  cidr_block           = var.eksctl_vpc_cidr_block
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = var.eksctl_vpc_enable_dns_support
  enable_dns_hostnames = var.eksctl_vpc_enable_dns_hostnames

  tags = {
    Name                            = var.eksctl_vpc_name
    "alpha.eksctl.io/cluster-name"  = var.eksctl_cluster_name
    "alpha.eksctl.io/eksctl-version" = var.eksctl_version
  }
}

###############################################################################
# VPC 4: untagged
###############################################################################

resource "aws_vpc" "untagged" {
  cidr_block           = var.untagged_vpc_cidr_block
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = var.untagged_vpc_enable_dns_support
  enable_dns_hostnames = var.untagged_vpc_enable_dns_hostnames
}

###############################################################################
# VPC 5: empty Name tag
###############################################################################

resource "aws_vpc" "empty_name" {
  cidr_block           = var.empty_name_vpc_cidr_block
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = var.empty_name_vpc_enable_dns_support
  enable_dns_hostnames = var.empty_name_vpc_enable_dns_hostnames

  tags = {
    Name = var.empty_name_vpc_name
  }
}

###############################################################################
# Inputs
###############################################################################

variable "tags" {
  description = "Optional tags to apply to the IAM resources. Any tag that is already set with an identical value in the provider's default_tags configuration is skipped."
  type        = map(string)
  default     = {}
}

###############################################################################
# Static provider metadata / lookups
###############################################################################

data "aws_partition" "current" {}

# Reads the tags configured via the provider-level `default_tags` block so that
# caller-supplied tags that are already applied identically can be skipped.
data "aws_default_tags" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  # Caller-supplied tags, minus any tag that is already set to the same value
  # by the provider default_tags configuration.
  caller_tags = {
    for key, value in var.tags : key => value
    if !contains(keys(data.aws_default_tags.current.tags), key) || data.aws_default_tags.current.tags[key] != value
  }

  aws_managed_policy_prefix = "arn:${data.aws_partition.current.partition}:iam::aws:policy"

  # Well-known AWS managed policy ARNs.
  ecs_service_role_policy_arn     = "${local.aws_managed_policy_prefix}/service-role/AmazonEC2ContainerServiceRole"
  ecs_task_execution_policy_arn   = "${local.aws_managed_policy_prefix}/service-role/AmazonECSTaskExecutionRolePolicy"
  cloudwatch_logs_full_access_arn = "${local.aws_managed_policy_prefix}/CloudWatchLogsFullAccess"
}

###############################################################################
# Assume role policy documents
###############################################################################

data "aws_iam_policy_document" "ecs_assume_role" {
  statement {
    sid     = "AllowECSServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    sid     = "AllowECSTasksToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "events_assume_role" {
  statement {
    sid     = "AllowEventBridgeToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

###############################################################################
# ECS service role ("ecs-role")
###############################################################################

resource "aws_iam_role" "ecs_role" {
  name                  = "ecs-role"
  description           = "Service role used by the ECS service scheduler."
  path                  = "/"
  force_detach_policies = true
  assume_role_policy    = data.aws_iam_policy_document.ecs_assume_role.json
  tags                  = local.caller_tags
}

resource "aws_iam_role_policy_attachment" "ecs_role_managed" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = local.ecs_service_role_policy_arn
}

###############################################################################
# ECS task execution role ("ecs-tasks-role")
###############################################################################

resource "aws_iam_role" "ecs_tasks_role" {
  name                  = "ecs-tasks-role"
  description           = "Task execution role used by ECS tasks to pull images and publish logs."
  path                  = "/"
  force_detach_policies = true
  assume_role_policy    = data.aws_iam_policy_document.ecs_tasks_assume_role.json
  tags                  = local.caller_tags
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_role_managed" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = local.ecs_task_execution_policy_arn
}

###############################################################################
# EventBridge role ("events-role")
###############################################################################

data "aws_iam_policy_document" "ecs_policy" {
  # Allow EventBridge to launch ECS tasks.
  statement {
    sid       = "RunECSTasks"
    effect    = "Allow"
    actions   = ["ecs:RunTask"]
    resources = ["*"]
  }

  # Allow passing only the ECS task execution role, and only to ECS tasks.
  statement {
    sid       = "PassTaskExecutionRoleOnly"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_tasks_role.arn]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "ecs_policy" {
  name        = "ecs-policy"
  description = "Allows running ECS tasks and passing only the ECS task execution role."
  path        = "/"
  policy      = data.aws_iam_policy_document.ecs_policy.json
  tags        = local.caller_tags
}

resource "aws_iam_role" "events_role" {
  name                  = "events-role"
  description           = "Role assumed by EventBridge to run scheduled ECS tasks."
  path                  = "/"
  force_detach_policies = true
  assume_role_policy    = data.aws_iam_policy_document.events_assume_role.json
  tags                  = local.caller_tags
}

resource "aws_iam_role_policy_attachment" "events_role_ecs_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

resource "aws_iam_role_policy_attachment" "events_role_cloudwatch_logs" {
  role       = aws_iam_role.events_role.name
  policy_arn = local.cloudwatch_logs_full_access_arn
}

terraform {
  required_version = ">= 1.0"
}

###############################################################################
# Inputs
###############################################################################

variable "primary_bucket_name" {
  description = "Base name of the primary S3 bucket; the AWS account ID is appended."
  type        = string
  default     = "example1"
}

variable "secondary_bucket_name" {
  description = "Base name of the secondary S3 bucket; the AWS account ID is appended."
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the S3 Multi-Region Access Point."
  type        = string
  default     = "example-mrap"
}

###############################################################################
# Providers
#
# A Multi-Region Access Point must be created (and its policy managed) from the
# control-plane region that AWS requires for Multi-Region Access Point
# operations: us-west-2. The buckets themselves live in two different regions,
# so an aliased provider is required for the secondary region.
###############################################################################

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "us_west_2"
  region = "us-west-2"
}

###############################################################################
# Static provider metadata
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # AWS account IDs make the globally-unique bucket names deterministic and
  # collision-free across accounts.
  primary_bucket_name   = "${var.primary_bucket_name}-${local.account_id}"
  secondary_bucket_name = "${var.secondary_bucket_name}-${local.account_id}"
}

###############################################################################
# Customer-managed KMS keys (one per bucket, automatic rotation enabled)
###############################################################################

resource "aws_kms_key" "primary" {
  provider = aws

  description             = "Customer-managed key for SSE-KMS encryption of the primary S3 bucket."
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_key" "secondary" {
  provider = aws.us_west_2

  description             = "Customer-managed key for SSE-KMS encryption of the secondary S3 bucket."
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

###############################################################################
# Buckets
###############################################################################

resource "aws_s3_bucket" "primary" {
  provider = aws
  bucket   = local.primary_bucket_name
}

resource "aws_s3_bucket" "secondary" {
  provider = aws.us_west_2
  bucket   = local.secondary_bucket_name
}

###############################################################################
# Object ownership (required before a private ACL can be applied)
###############################################################################

resource "aws_s3_bucket_ownership_controls" "primary" {
  provider = aws
  bucket   = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

###############################################################################
# Private ACLs
###############################################################################

resource "aws_s3_bucket_acl" "primary" {
  provider = aws
  bucket   = aws_s3_bucket.primary.id
  acl      = "private"

  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_acl" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id
  acl      = "private"

  depends_on = [aws_s3_bucket_ownership_controls.secondary]
}

###############################################################################
# Versioning (required for replication and for Multi-Region Access Points)
###############################################################################

resource "aws_s3_bucket_versioning" "primary" {
  provider = aws
  bucket   = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Default SSE-KMS encryption using each bucket's own customer-managed key
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  provider = aws
  bucket   = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Block all public access
###############################################################################

resource "aws_s3_bucket_public_access_block" "primary" {
  provider = aws
  bucket   = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Cross-region replication IAM role (assumable by S3)
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ReplicationToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "${var.mrap_name}-replication-role"
  description        = "Role assumed by Amazon S3 to replicate objects between the primary and secondary buckets."
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json
}

data "aws_iam_policy_document" "replication" {
  # Read the source bucket's replication configuration and object listing.
  statement {
    sid    = "SourceBucketRead"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:GetBucketVersioning",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.primary.arn]
  }

  # Read the KMS-encrypted object versions from the source bucket.
  statement {
    sid    = "SourceObjectRead"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  # Write (replicate) objects into the destination bucket.
  statement {
    sid    = "DestinationObjectReplicate"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }

  # Decrypt source objects with the primary key.
  statement {
    sid    = "SourceKmsDecrypt"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.primary.arn]
  }

  # Encrypt replica objects with the secondary key.
  statement {
    sid    = "DestinationKmsEncrypt"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.secondary.arn]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "${var.mrap_name}-replication-policy"
  description = "Least-privilege permissions for replicating KMS-encrypted S3 objects."
  policy      = data.aws_iam_policy_document.replication.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

###############################################################################
# Replication configuration (primary -> secondary, STANDARD storage class)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "primary_to_secondary" {
  provider = aws
  role     = aws_iam_role.replication.arn
  bucket   = aws_s3_bucket.primary.id

  rule {
    id     = "replicate-kms-objects"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
  ]
}

###############################################################################
# Multi-Region Access Point (created in the required us-west-2 control region)
###############################################################################

resource "aws_s3control_multi_region_access_point" "this" {
  provider   = aws.us_west_2
  account_id = local.account_id

  details {
    name = var.mrap_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

###############################################################################
# Multi-Region Access Point policy: allow only the owning account to get/put
###############################################################################

data "aws_iam_policy_document" "mrap" {
  statement {
    sid    = "AllowOwningAccountObjectAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = [
      "${aws_s3control_multi_region_access_point.this.arn}/object/*",
    ]
  }
}

resource "aws_s3control_multi_region_access_point_policy" "this" {
  provider   = aws.us_west_2
  account_id = local.account_id

  details {
    name   = aws_s3control_multi_region_access_point.this.details[0].name
    policy = data.aws_iam_policy_document.mrap.json
  }
}

################################################################################
# Static / provider metadata lookups
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

################################################################################
# Cloud Posse null-label (naming + tagging conventions)
################################################################################

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  tenant      = var.tenant
  environment = var.environment
  stage       = var.stage
  name        = var.name
  delimiter   = var.delimiter
  attributes  = var.attributes
  tags        = var.tags
  label_order = var.label_order
}

################################################################################
# Locals
################################################################################

locals {
  scan_targets = (
    var.scan_targets != null
    ? var.scan_targets
    : [{ key = "tag:Patch Group", values = [var.scan_patch_group] }]
  )

  install_targets = (
    var.install_targets != null
    ? var.install_targets
    : [{ key = "tag:Patch Group", values = [var.install_patch_group] }]
  )

  s3_bucket_name = var.s3_log_bucket_name != "" ? var.s3_log_bucket_name : "${module.this.id}-ssm-logs"
  s3_bucket_id   = var.create_s3_bucket ? one(aws_s3_bucket.logs[*].id) : var.s3_log_bucket_name
  s3_bucket_arn = (
    var.create_s3_bucket
    ? one(aws_s3_bucket.logs[*].arn)
    : "arn:${data.aws_partition.current.partition}:s3:::${local.s3_bucket_name}"
  )
}

################################################################################
# S3 log bucket (versioned, private)
################################################################################

resource "aws_s3_bucket" "logs" {
  count = var.create_s3_bucket ? 1 : 0

  bucket        = local.s3_bucket_name
  force_destroy = false

  tags = module.this.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  count = var.create_s3_bucket ? 1 : 0

  bucket                  = aws_s3_bucket.logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "logs" {
  count = var.create_s3_bucket ? 1 : 0

  description             = "Customer managed key for ${module.this.id} SSM command output"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = module.this.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "logs" {
  count = var.create_s3_bucket ? 1 : 0

  name          = "alias/${module.this.id}-ssm-logs"
  target_key_id = aws_kms_key.logs[0].key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  count = var.create_s3_bucket ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.logs[0].arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  count = var.create_s3_bucket ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "s3_log" {
  count = var.create_s3_bucket ? 1 : 0

  statement {
    sid    = "AllowAccountReadWrite"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:GetObjectAcl",
      "s3:PutObjectAcl",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.logs[0].arn,
      "${aws_s3_bucket.logs[0].arn}/*",
    ]
  }
}

resource "aws_s3_bucket_policy" "logs" {
  count = var.create_s3_bucket ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id
  policy = data.aws_iam_policy_document.s3_log[0].json

  depends_on = [aws_s3_bucket_public_access_block.logs]
}

################################################################################
# IAM role assumed by the Systems Manager maintenance windows
################################################################################

data "aws_iam_policy_document" "assume_role" {
  statement {
    sid     = "AllowSSMAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "mw" {
  name               = "${module.this.id}-mw-task"
  description        = "Service role used by the ${module.this.id} maintenance windows"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json

  tags = module.this.tags
}

data "aws_iam_policy_document" "mw_task" {
  statement {
    sid    = "AllowSSMCommands"
    effect = "Allow"

    actions = [
      "ssm:SendCommand",
      "ssm:CancelCommand",
      "ssm:GetCommandInvocation",
      "ssm:ListCommands",
      "ssm:ListCommandInvocations",
      "ssm:DescribeInstanceInformation",
      "ssm:GetDocument",
      "ssm:DescribeDocument",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowS3Output"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:GetObjectAcl",
      "s3:PutObjectAcl",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      local.s3_bucket_arn,
      "${local.s3_bucket_arn}/*",
    ]
  }

  dynamic "statement" {
    for_each = var.create_s3_bucket ? [1] : []

    content {
      sid    = "AllowKMSForS3Output"
      effect = "Allow"

      actions = [
        "kms:Decrypt",
        "kms:GenerateDataKey",
        "kms:DescribeKey",
      ]

      resources = [aws_kms_key.logs[0].arn]
    }
  }

  dynamic "statement" {
    for_each = var.enable_sns_notifications ? [1] : []

    content {
      sid       = "AllowSNSPublish"
      effect    = "Allow"
      actions   = ["sns:Publish"]
      resources = [var.sns_topic_arn]
    }
  }

  dynamic "statement" {
    for_each = var.enable_cloudwatch_logs ? [1] : []

    content {
      sid    = "AllowCloudWatchLogs"
      effect = "Allow"

      actions = [
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogStreams",
      ]

      resources = [
        "arn:${data.aws_partition.current.partition}:logs:*:${data.aws_caller_identity.current.account_id}:log-group:${var.cloudwatch_log_group_name}:*",
      ]
    }
  }
}

resource "aws_iam_role_policy" "mw" {
  name   = "${module.this.id}-mw-task"
  role   = aws_iam_role.mw.id
  policy = data.aws_iam_policy_document.mw_task.json
}

################################################################################
# Scan maintenance window
################################################################################

resource "aws_ssm_maintenance_window" "scan" {
  name              = "${module.this.id}-scan"
  description       = "Weekly scan of EC2 instances for missing patches"
  schedule          = var.scan_window_schedule
  schedule_timezone = var.maintenance_window_timezone
  duration          = var.maintenance_window_duration
  cutoff            = var.maintenance_window_cutoff

  tags = module.this.tags
}

resource "aws_ssm_maintenance_window_target" "scan" {
  window_id     = aws_ssm_maintenance_window.scan.id
  name          = "${module.this.id}-scan-target"
  description   = "Instances targeted by the patch scan window"
  resource_type = "INSTANCE"

  dynamic "targets" {
    for_each = local.scan_targets

    content {
      key    = targets.value.key
      values = targets.value.values
    }
  }
}

resource "aws_ssm_maintenance_window_task" "scan" {
  window_id        = aws_ssm_maintenance_window.scan.id
  name             = "${module.this.id}-scan-task"
  description      = "Run AWS-RunPatchBaseline in Scan mode"
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  service_role_arn = aws_iam_role.mw.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      comment              = "Scan EC2 instances for missing patches"
      document_version     = "$LATEST"
      output_s3_bucket     = local.s3_bucket_id
      output_s3_key_prefix = var.s3_log_prefix

      parameter {
        name   = "Operation"
        values = ["Scan"]
      }

      dynamic "notification_config" {
        for_each = var.enable_sns_notifications ? [1] : []

        content {
          notification_events = ["All"]
          notification_type   = "Command"
          notification_arn    = var.sns_topic_arn
        }
      }
    }
  }
}

################################################################################
# Install maintenance window
################################################################################

resource "aws_ssm_maintenance_window" "install" {
  name              = "${module.this.id}-install"
  description       = "Weekly installation of missing patches on EC2 instances"
  schedule          = var.install_window_schedule
  schedule_timezone = var.maintenance_window_timezone
  duration          = var.maintenance_window_duration
  cutoff            = var.maintenance_window_cutoff

  tags = module.this.tags
}

resource "aws_ssm_maintenance_window_target" "install" {
  window_id     = aws_ssm_maintenance_window.install.id
  name          = "${module.this.id}-install-target"
  description   = "Instances targeted by the patch install window"
  resource_type = "INSTANCE"

  dynamic "targets" {
    for_each = local.install_targets

    content {
      key    = targets.value.key
      values = targets.value.values
    }
  }
}

resource "aws_ssm_maintenance_window_task" "install" {
  window_id        = aws_ssm_maintenance_window.install.id
  name             = "${module.this.id}-install-task"
  description      = "Run AWS-RunPatchBaseline in Install mode"
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  service_role_arn = aws_iam_role.mw.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      comment              = "Install missing patches on EC2 instances"
      document_version     = "$LATEST"
      output_s3_bucket     = local.s3_bucket_id
      output_s3_key_prefix = var.s3_log_prefix

      parameter {
        name   = "Operation"
        values = ["Install"]
      }

      parameter {
        name   = "RebootOption"
        values = [var.reboot_option]
      }

      dynamic "notification_config" {
        for_each = var.enable_sns_notifications ? [1] : []

        content {
          notification_events = ["All"]
          notification_type   = "Command"
          notification_arn    = var.sns_topic_arn
        }
      }
    }
  }
}

################################################################################
# Amazon Linux 2 patch baseline and patch groups
################################################################################

resource "aws_ssm_patch_baseline" "this" {
  name             = "${module.this.id}-amazon-linux-2"
  description      = "Patch baseline for Amazon Linux 2"
  operating_system = "AMAZON_LINUX_2"

  approved_patches_compliance_level = "HIGH"

  approval_rule {
    approve_after_days  = var.approve_after_days
    compliance_level    = "HIGH"
    enable_non_security = true

    patch_filter {
      key    = "PRODUCT"
      values = ["AmazonLinux2", "AmazonLinux2.0"]
    }

    patch_filter {
      key    = "CLASSIFICATION"
      values = ["Security", "Bugfix", "Recommended"]
    }

    patch_filter {
      key    = "SEVERITY"
      values = ["Critical", "Important", "Medium"]
    }
  }

  tags = module.this.tags
}

resource "aws_ssm_patch_group" "scan" {
  baseline_id = aws_ssm_patch_baseline.this.id
  patch_group = var.scan_patch_group
}

resource "aws_ssm_patch_group" "install" {
  baseline_id = aws_ssm_patch_baseline.this.id
  patch_group = var.install_patch_group
}

################################################################################
# Variables
################################################################################

variable "namespace" {
  type        = string
  description = "Cloud Posse namespace for the null-label module."
  default     = ""
}

variable "tenant" {
  type        = string
  description = "Cloud Posse tenant for the null-label module."
  default     = ""
}

variable "environment" {
  type        = string
  description = "Cloud Posse environment for the null-label module."
  default     = ""
}

variable "stage" {
  type        = string
  description = "Cloud Posse stage for the null-label module."
  default     = ""
}

variable "name" {
  type        = string
  description = "Cloud Posse name for the null-label module."
  default     = "ssm-patch-manager"
}

variable "delimiter" {
  type        = string
  description = "Delimiter used by the null-label module."
  default     = "-"
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes for the null-label module."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags for the null-label module."
  default     = {}
}

variable "label_order" {
  type        = list(string)
  description = "Label order for the null-label module."
  default     = ["namespace", "tenant", "environment", "stage", "name", "attributes"]
}

variable "scan_window_schedule" {
  type        = string
  description = "Cron or rate expression for the patch scan maintenance window."
  default     = "cron(0 0 18 ? * WED *)"
}

variable "install_window_schedule" {
  type        = string
  description = "Cron or rate expression for the patch install maintenance window."
  default     = "cron(0 0 21 ? * WED *)"
}

variable "maintenance_window_duration" {
  type        = number
  description = "Duration of each maintenance window in hours."
  default     = 3
}

variable "maintenance_window_cutoff" {
  type        = number
  description = "Cutoff (in hours) after which no new tasks are started."
  default     = 1
}

variable "maintenance_window_timezone" {
  type        = string
  description = "Timezone in which the maintenance window schedule is evaluated."
  default     = "UTC"
}

variable "scan_patch_group" {
  type        = string
  description = "Patch Group tag value targeted by the scan window."
  default     = "TOSCAN"
}

variable "install_patch_group" {
  type        = string
  description = "Patch Group tag value targeted by the install window."
  default     = "TOPATCH"
}

variable "scan_targets" {
  type = list(object({
    key    = string
    values = list(string)
  }))
  description = "Explicit instance targets for the scan window. Defaults to the TOSCAN Patch Group tag."
  default     = null
}

variable "install_targets" {
  type = list(object({
    key    = string
    values = list(string)
  }))
  description = "Explicit instance targets for the install window. Defaults to the TOPATCH Patch Group tag."
  default     = null
}

variable "max_concurrency" {
  type        = string
  description = "Maximum number of targets processed concurrently by a maintenance window task."
  default     = "20"
}

variable "max_errors" {
  type        = string
  description = "Maximum number of errors tolerated before a maintenance window task stops."
  default     = "50"
}

variable "reboot_option" {
  type        = string
  description = "Reboot behavior used by the patch install task."
  default     = "RebootIfNeeded"
}

variable "create_s3_bucket" {
  type        = bool
  description = "Whether to create the versioned private S3 bucket used for command output."
  default     = true
}

variable "s3_log_bucket_name" {
  type        = string
  description = "Name of the S3 bucket used for command output. Defaults to the generated label."
  default     = ""
}

variable "s3_log_prefix" {
  type        = string
  description = "Key prefix under which command output is stored in the S3 bucket."
  default     = "scanning"
}

variable "enable_sns_notifications" {
  type        = bool
  description = "Whether to send SNS notifications for maintenance window task events."
  default     = false
}

variable "sns_topic_arn" {
  type        = string
  description = "ARN of the SNS topic used for notifications when enable_sns_notifications is true."
  default     = ""
}

variable "enable_cloudwatch_logs" {
  type        = bool
  description = "Whether to stream command output to CloudWatch Logs."
  default     = false
}

variable "cloudwatch_log_group_name" {
  type        = string
  description = "CloudWatch log group name used when enable_cloudwatch_logs is true."
  default     = ""
}

variable "approve_after_days" {
  type        = number
  description = "Number of days to wait after a patch is released before it is auto-approved."
  default     = 7
}

###############################################################################
# Account Activity Monitoring Stack
#
# Creates a multi-region CloudTrail trail that records management events,
# delivers encrypted logs to S3, streams them to CloudWatch Logs, and raises
# CloudWatch alarms (in the "management_activities" namespace) that notify an
# encrypted SNS topic for sensitive management changes.
###############################################################################

###############################################################################
# Static provider metadata
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Inputs
###############################################################################

variable "alarm_email_recipients" {
  description = "List of email addresses that receive notifications from the management-updates SNS topic."
  type        = list(string)
  default     = ["placeholder@example.com"]
}

###############################################################################
# Locals
###############################################################################

locals {
  trail_name       = "monitor_account_activities"
  log_group_name   = "cloudtrail_to_cloudwatch_logs"
  sns_topic_name   = "management-updates"
  metric_namespace = "management_activities"

  account_id       = data.aws_caller_identity.current.account_id
  partition        = data.aws_partition.current.partition
  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"
  bucket_name      = "cloudtrail-monitor-management-event-logs-${local.account_id}"

  # Wildcard region keeps the SourceArn condition valid for the multi-region
  # trail without depending on regional provider metadata.
  trail_arn_pattern = "arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/${local.trail_name}"

  common_tags = {
    Project   = "account-activity-monitoring"
    ManagedBy = "Terraform"
  }

  # CloudWatch Logs metric filter patterns mapped to their metric names.
  management_metric_filters = {
    SecurityGroupChanges = "{ ($.eventName = \"AuthorizeSecurityGroupIngress\") || ($.eventName = \"AuthorizeSecurityGroupEgress\") || ($.eventName = \"RevokeSecurityGroupIngress\") || ($.eventName = \"RevokeSecurityGroupEgress\") || ($.eventName = \"CreateSecurityGroup\") || ($.eventName = \"DeleteSecurityGroup\") }"
    IAMUserChanges       = "{ ($.eventName = \"CreateUser\") || ($.eventName = \"DeleteUser\") }"
    FailedConsoleLogins  = "{ ($.eventName = \"ConsoleLogin\") && ($.errorMessage = \"Failed authentication\") }"
    IAMGroupRoleUserPolicyChanges = "{ ($.eventName = \"PutGroupPolicy\") || ($.eventName = \"DeleteGroupPolicy\") || ($.eventName = \"PutRolePolicy\") || ($.eventName = \"DeleteRolePolicy\") || ($.eventName = \"PutUserPolicy\") || ($.eventName = \"DeleteUserPolicy\") }"
    IAMPolicyChanges = "{ ($.eventName = \"CreatePolicy\") || ($.eventName = \"DeletePolicy\") || ($.eventName = \"CreatePolicyVersion\") || ($.eventName = \"DeletePolicyVersion\") || ($.eventName = \"SetDefaultPolicyVersion\") || ($.eventName = \"AttachRolePolicy\") || ($.eventName = \"DetachRolePolicy\") || ($.eventName = \"AttachUserPolicy\") || ($.eventName = \"DetachUserPolicy\") || ($.eventName = \"AttachGroupPolicy\") || ($.eventName = \"DetachGroupPolicy\") }"
    UsersAddedToGroups   = "{ ($.eventName = \"AddUserToGroup\") }"
    IAMRoleChanges       = "{ ($.eventName = \"CreateRole\") || ($.eventName = \"DeleteRole\") }"
  }
}

###############################################################################
# KMS key used to encrypt CloudTrail log files and the S3 log bucket
###############################################################################

data "aws_iam_policy_document" "trail_kms" {
  statement {
    sid    = "AllowAccountRootFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:Decrypt",
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "trail" {
  description             = "Customer-managed key used to encrypt the ${local.trail_name} CloudTrail logs"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.trail_kms.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "trail" {
  name          = "alias/${local.trail_name}-logs"
  target_key_id = aws_kms_key.trail.key_id
}

###############################################################################
# S3 bucket that receives the CloudTrail log files
###############################################################################

resource "aws_s3_bucket" "cloudtrail" {
  bucket = local.bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.trail.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]

    condition {
      test     = "StringLike"
      variable = "aws:SourceArn"
      values   = [local.trail_arn_pattern]
    }
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${local.account_id}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringLike"
      variable = "aws:SourceArn"
      values   = [local.trail_arn_pattern]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail]
}

###############################################################################
# CloudWatch Logs group and role for the CloudTrail -> CloudWatch integration
###############################################################################

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = 365
  tags              = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    sid    = "AllowCloudTrailToAssumeRole"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cloudtrail_to_cloudwatch" {
  name               = "cloudtrail-to-cloudwatch-logs-role"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_to_cloudwatch" {
  statement {
    sid    = "AllowCloudTrailToWriteLogEvents"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:*"]
  }
}

resource "aws_iam_role_policy" "cloudtrail_to_cloudwatch" {
  name   = "cloudtrail-to-cloudwatch-logs-policy"
  role   = aws_iam_role.cloudtrail_to_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_to_cloudwatch.json
}

###############################################################################
# Multi-region CloudTrail trail
###############################################################################

resource "aws_cloudtrail" "monitor" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.trail.arn

  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_to_cloudwatch.arn

  event_selector {
    read_write_type           = "All"
    include_management_events = true

    # Record every management event except KMS and RDS Data API events.
    exclude_management_event_sources = [
      "kms.amazonaws.com",
      "rdsdata.amazonaws.com",
    ]
  }

  tags = local.common_tags

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_iam_role_policy.cloudtrail_to_cloudwatch,
  ]
}

###############################################################################
# SNS topic that receives alarm notifications
###############################################################################

data "aws_iam_policy_document" "sns_kms" {
  statement {
    sid    = "AllowAccountRootFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "sns" {
  description             = "Customer-managed key used to encrypt the ${local.sns_topic_name} SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sns" {
  name          = "alias/${local.sns_topic_name}"
  target_key_id = aws_kms_key.sns.key_id
}

resource "aws_sns_topic" "management_updates" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.sns.arn
  tags              = local.common_tags
}

data "aws_iam_policy_document" "sns_topic" {
  statement {
    sid    = "AllowCloudWatchToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.management_updates.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "management_updates" {
  arn    = aws_sns_topic.management_updates.arn
  policy = data.aws_iam_policy_document.sns_topic.json
}

resource "aws_sns_topic_subscription" "email" {
  for_each = toset(var.alarm_email_recipients)

  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = each.value
}

###############################################################################
# CloudWatch Logs metric filters and matching alarms
###############################################################################

resource "aws_cloudwatch_log_metric_filter" "management_activities" {
  for_each = local.management_metric_filters

  name           = each.key
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name
  pattern        = each.value

  metric_transformation {
    name      = each.key
    namespace = local.metric_namespace
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "management_activities" {
  for_each = local.management_metric_filters

  alarm_name          = each.key
  alarm_description   = "Alerts when the ${each.key} management activity is detected in CloudTrail logs."
  namespace           = local.metric_namespace
  metric_name         = aws_cloudwatch_log_metric_filter.management_activities[each.key].metric_transformation[0].name
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"

  alarm_actions = [aws_sns_topic.management_updates.arn]

  tags = local.common_tags
}

###############################################################################
# Outputs
###############################################################################

output "cloudtrail_trail_arn" {
  description = "ARN of the account activity monitoring CloudTrail trail."
  value       = aws_cloudtrail.monitor.arn
}

output "cloudtrail_log_bucket" {
  description = "Name of the S3 bucket receiving CloudTrail logs."
  value       = aws_s3_bucket.cloudtrail.id
}

output "management_updates_topic_arn" {
  description = "ARN of the SNS topic that receives management activity alarm notifications."
  value       = aws_sns_topic.management_updates.arn
}

###############################################################################
# Variables
###############################################################################

variable "name_prefix" {
  description = "Optional prefix prepended to the names of the AWS Config resources created by this configuration. Leave empty to use the default names."
  type        = string
  default     = ""
}

variable "days_to_expiration" {
  description = "Number of days before an ACM certificate expires at which the AWS Config managed rule reports the resource as NON_COMPLIANT."
  type        = number
  default     = 30
}

variable "delivery_frequency" {
  description = "Frequency with which AWS Config delivers configuration snapshots to the delivery channel's S3 bucket."
  type        = string
  default     = "TwentyFour_Hours"
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = var.name_prefix != "" ? "${var.name_prefix}-" : ""

  rule_name             = "${local.name_prefix}acm-certificate-expiration-check"
  recorder_name         = "${local.name_prefix}config-recorder"
  delivery_channel_name = "${local.name_prefix}config-delivery-channel"
  role_name_prefix      = substr("${local.name_prefix}config-role-", 0, 32)

  bucket_name_prefix = var.name_prefix != "" ? "${lower(replace(var.name_prefix, "_", "-"))}-aws-config-" : "aws-config-"

  config_role_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"

  common_tags = {
    ManagedBy = "Terraform"
    Purpose   = "AWS Config - ACM certificate expiration monitoring"
  }
}

###############################################################################
# IAM role assumed by AWS Config
###############################################################################

data "aws_iam_policy_document" "config_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config" {
  name_prefix        = local.role_name_prefix
  description        = "Service role assumed by AWS Config to record resource configuration and deliver snapshots."
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "config" {
  role       = aws_iam_role.config.name
  policy_arn = local.config_role_policy_arn
}

###############################################################################
# Customer managed KMS key used to encrypt the AWS Config delivery bucket
###############################################################################

resource "aws_kms_key" "config" {
  description             = "Customer managed key used to encrypt objects in the AWS Config delivery bucket."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "config_kms_access" {
  statement {
    sid    = "AllowUseOfConfigKmsKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.config.arn]
  }
}

resource "aws_iam_role_policy" "config_kms_access" {
  name   = "${local.name_prefix}config-kms-access"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_kms_access.json
}

###############################################################################
# S3 bucket used as the AWS Config delivery channel target
###############################################################################

resource "aws_s3_bucket" "config" {
  bucket_prefix = local.bucket_name_prefix
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "config" {
  bucket = aws_s3_bucket.config.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config" {
  bucket = aws_s3_bucket.config.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "config" {
  bucket = aws_s3_bucket.config.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "config_bucket" {
  statement {
    sid    = "AllowAwsConfigGetBucketAcl"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.config.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowAwsConfigPutObject"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.config.arn}/config/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "config" {
  bucket = aws_s3_bucket.config.id
  policy = data.aws_iam_policy_document.config_bucket.json
}

###############################################################################
# AWS Config recorder and delivery channel
###############################################################################

resource "aws_config_configuration_recorder" "this" {
  name     = local.recorder_name
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "this" {
  name           = local.delivery_channel_name
  s3_bucket_name = aws_s3_bucket.config.bucket
  s3_key_prefix  = "config"

  snapshot_delivery_properties {
    delivery_frequency = var.delivery_frequency
  }

  depends_on = [aws_config_configuration_recorder.this]
}

resource "aws_config_configuration_recorder_status" "this" {
  name       = aws_config_configuration_recorder.this.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.this]
}

###############################################################################
# AWS Config managed rule - ACM certificate expiration check
###############################################################################

resource "aws_config_config_rule" "acm_certificate_expiration" {
  name        = local.rule_name
  description = "Checks whether ACM certificates in the account are close to expiring (non-compliant when fewer than ${var.days_to_expiration} days remain)."

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  input_parameters = jsonencode({
    daysToExpiration = tostring(var.days_to_expiration)
  })

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder_status.this]
}

###############################################################################
# Outputs
###############################################################################

output "config_rule_name" {
  description = "Name of the AWS Config managed rule monitoring ACM certificate expiration."
  value       = aws_config_config_rule.acm_certificate_expiration.name
}

output "config_rule_arn" {
  description = "ARN of the AWS Config managed rule monitoring ACM certificate expiration."
  value       = aws_config_config_rule.acm_certificate_expiration.arn
}

output "config_recorder_name" {
  description = "Name of the AWS Config configuration recorder."
  value       = aws_config_configuration_recorder.this.name
}

output "config_delivery_bucket" {
  description = "Name of the S3 bucket used as the AWS Config delivery channel target."
  value       = aws_s3_bucket.config.bucket
}

locals {
  user_pool_name = "fiap-hackathon-cognito-pool"
  app_client_name = "cognito-pool-client"
}

resource "aws_cognito_user_pool" "main" {
  name = local.user_pool_name

  # Use email as the username and automatically verify it
  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  # MFA disabled
  mfa_configuration = "OFF"

  # Required "name" attribute
  schema {
    name                = "name"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  # Basic password policy with 8-character minimum
  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_numbers   = true
    require_symbols   = false
    require_uppercase = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "main" {
  name         = local.app_client_name
  user_pool_id = aws_cognito_user_pool.main.id

  # No client secret
  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]
}

##############################################################################
# Azure AD (Microsoft Entra ID) OIDC federation for Sentinel function apps
#
# Creates:
#   - An IAM OpenID Connect identity provider for the Azure AD tenant
#   - An IAM role that Sentinel function apps assume via web identity when the
#     token audience matches the registered Azure AD client ID
##############################################################################

locals {
  # Azure AD (Microsoft Entra ID) directory tenant ID
  tenant_id = "221ca1d3-b3f2-4346-8abc-88f802495c7d"

  # Azure AD application (client) ID presented as the token audience (`aud`)
  client_id = "c8b9cf86-e2b4-4428-b356-14313412a4d1"

  # OIDC issuer as published by the Azure AD tenant
  issuer_url = "https://sts.windows.net/${local.tenant_id}/"

  # Thumbprint used by IAM to validate the issuer's TLS certificate.
  #
  # IAM requires the SHA-1 fingerprint of a certificate in the issuer's TLS
  # chain (AWS recommends the trusted root CA so that it remains valid across
  # the leaf/intermediate rotations Azure AD performs). This is the SHA-1
  # fingerprint of the DigiCert Global Root G2 root CA that signs the
  # sts.windows.net TLS certificate. It is a public, well-known certificate
  # fingerprint (not account- or secret-specific), so it is safe to declare
  # here rather than resolving it dynamically over the network.
  issuer_thumbprint = "DF3C24F9BFD666761B268073FEF542E2DC9D7B49"

  # Name of the IAM role used by Sentinel function apps
  role_name = "Sentinel-OIDC-Organizations-ReadOnly"

  common_tags = {
    Application = "Sentinel"
    ManagedBy   = "Terraform"
  }
}

##############################################################################
# Provider metadata
##############################################################################

data "aws_partition" "current" {}

##############################################################################
# IAM OIDC identity provider for the Azure AD tenant
##############################################################################

resource "aws_iam_openid_connect_provider" "azure_ad" {
  url = local.issuer_url

  # The audience (`aud`) claim that identifies tokens issued for Sentinel
  client_id_list = [local.client_id]

  # SHA-1 thumbprint validating the issuer's TLS certificate
  thumbprint_list = [local.issuer_thumbprint]

  tags = merge(local.common_tags, {
    Name = "Sentinel-AzureAD-OIDC"
  })
}

##############################################################################
# IAM role assumable by Sentinel function apps via OIDC web identity
##############################################################################

resource "aws_iam_role" "sentinel_oidc_organizations_readonly" {
  name        = local.role_name
  description = "Read-only AWS Organizations access for Sentinel function apps federated through Azure AD OIDC."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAzureADWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.azure_ad.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            # Restrict assumption to tokens whose audience matches the
            # registered Azure AD client ID.
            "sts.windows.net/${local.tenant_id}/:aud" = local.client_id
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = local.role_name
  })
}

##############################################################################
# AWS managed read-only AWS Organizations policy attached to the role
##############################################################################

resource "aws_iam_role_policy_attachment" "organizations_readonly" {
  role       = aws_iam_role.sentinel_oidc_organizations_readonly.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSOrganizationsReadOnlyAccess"
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

locals {
  # ARN of the single, specifically named RDS cluster "foo_cluster".
  foo_cluster_arn = "arn:${data.aws_partition.current.partition}:rds:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:cluster:foo_cluster"

  # ARN pattern matching all RDS clusters in any region and any account.
  all_rds_clusters_arn = "arn:${data.aws_partition.current.partition}:rds:*:*:cluster:*"
}

resource "aws_iam_role" "wildcard_test" {
  name        = "iam-wildcard-test-role"
  description = "Role assumed by EC2 for testing IAM policy wildcard checks"

  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name = "iam-wildcard-test-role"
  }
}

# Inline policy 1: allow rds:AddRoleToDBCluster on the single specific RDS cluster "foo_cluster".
resource "aws_iam_role_policy" "specific_cluster_allow" {
  name = "rds-add-role-to-specific-cluster"
  role = aws_iam_role.wildcard_test.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAddRoleToDBClusterOnFooCluster"
        Effect   = "Allow"
        Action   = "rds:AddRoleToDBCluster"
        Resource = local.foo_cluster_arn
      }
    ]
  })
}

# Inline policy 2: allow rds:Add* on all RDS clusters in any region and any account.
resource "aws_iam_role_policy" "all_clusters_allow" {
  name = "rds-add-wildcard-allow"
  role = aws_iam_role.wildcard_test.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAddWildcardOnAllClusters"
        Effect   = "Allow"
        Action   = "rds:Add*"
        Resource = local.all_rds_clusters_arn
      }
    ]
  })
}

# Inline policy 3: deny rds:Add* on all RDS clusters in any region and any account.
resource "aws_iam_role_policy" "all_clusters_deny" {
  name = "rds-add-wildcard-deny"
  role = aws_iam_role.wildcard_test.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DenyAddWildcardOnAllClusters"
        Effect   = "Deny"
        Action   = "rds:Add*"
        Resource = local.all_rds_clusters_arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "environment" {
  description = "Environment name used to namespace the Terraform remote state backend resources."
  type        = string
  default     = "dev"
}

locals {
  account_id           = data.aws_caller_identity.current.account_id
  frontend_bucket_name = "s3-frontend-nft-maker-v2-${local.account_id}"
  tfstate_bucket_name  = "near-frontend-${var.environment}-terraform-state-${local.account_id}"
  tfstate_table_name   = "near-frontend-terraform-state"
  origin_id            = "S3-${local.frontend_bucket_name}"
}

###############################################################################
# Frontend KMS key (SSE-KMS for the static site bucket)
###############################################################################

data "aws_iam_policy_document" "frontend_kms" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowOriginAccessIdentityToDecrypt"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.frontend.iam_arn]
    }

    actions   = ["kms:Decrypt", "kms:DescribeKey"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "frontend" {
  description             = "Customer managed key used for SSE-KMS on the ${local.frontend_bucket_name} static site bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.frontend_kms.json
}

###############################################################################
# Frontend S3 bucket (private static website origin for CloudFront)
###############################################################################

resource "aws_s3_bucket" "frontend" {
  bucket = local.frontend_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.frontend.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

###############################################################################
# CloudFront origin access identity + bucket policy
###############################################################################

resource "aws_cloudfront_origin_access_identity" "frontend" {
  comment = "Origin access identity for ${local.frontend_bucket_name}"
}

data "aws_iam_policy_document" "frontend_bucket" {
  statement {
    sid    = "AllowCloudFrontOriginAccessIdentityRead"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.frontend.iam_arn]
    }

    actions = [
      "s3:GetObject",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.frontend.arn,
      "${aws_s3_bucket.frontend.arn}/*",
    ]
  }
}

resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  policy = data.aws_iam_policy_document.frontend_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.frontend]
}

###############################################################################
# AWS WAFv2 web ACL protecting CloudFront (allow by default + common rules)
###############################################################################

resource "aws_wafv2_web_acl" "frontend" {
  name        = "near-frontend-waf"
  description = "WAFv2 web ACL protecting the static frontend CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "near-frontend-waf"
    sampled_requests_enabled   = true
  }
}

###############################################################################
# CloudFront distribution serving the private S3 bucket via OAI
###############################################################################

resource "aws_cloudfront_distribution" "frontend" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Static frontend distribution for ${local.frontend_bucket_name}"
  default_root_object = "index.html"
  price_class         = "PriceClass_200"
  web_acl_id          = aws_wafv2_web_acl.frontend.arn

  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = local.origin_id

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.frontend.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = local.origin_id
    viewer_protocol_policy = "redirect-to-https"
    compress               = true
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern           = "/content/immutable/*"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    target_origin_id       = local.origin_id
    viewer_protocol_policy = "redirect-to-https"
    compress               = true
    min_ttl                = 0
    default_ttl            = 31536000
    max_ttl                = 31536000

    forwarded_values {
      query_string = false
      headers      = ["Origin"]

      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern           = "/content/*"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = local.origin_id
    viewer_protocol_policy = "redirect-to-https"
    compress               = true
    min_ttl                = 0
    default_ttl            = 86400
    max_ttl                = 31536000

    forwarded_values {
      query_string = false
      headers      = ["Origin"]

      cookies {
        forward = "none"
      }
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

###############################################################################
# Terraform remote state backend
###############################################################################

resource "aws_kms_key" "tfstate" {
  description             = "Customer managed key used for SSE-KMS on the Terraform remote state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "tfstate" {
  bucket = local.tfstate_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.tfstate.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_dynamodb_table" "tfstate_lock" {
  name           = local.tfstate_table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.tfstate.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "frontend_bucket_name" {
  description = "Name of the private static frontend S3 bucket."
  value       = aws_s3_bucket.frontend.bucket
}

output "cloudfront_distribution_domain_name" {
  description = "Domain name of the CloudFront distribution serving the frontend."
  value       = aws_cloudfront_distribution.frontend.domain_name
}

output "terraform_state_bucket_name" {
  description = "Name of the S3 bucket used for Terraform remote state."
  value       = aws_s3_bucket.tfstate.bucket
}

output "terraform_state_lock_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking."
  value       = aws_dynamodb_table.tfstate_lock.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, var.az_count)

  cluster_tags = {
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }

  karpenter_tags = {
    "karpenter.sh/discovery" = var.cluster_name
  }
}

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Base name applied to all network resources."
  type        = string
  default     = "stackx-network"
}

variable "cluster_name" {
  description = "Name of the EKS cluster that will use this network."
  type        = string
  default     = "stackx"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.1.0.0/16"
}

variable "az_count" {
  description = "Number of availability zones / subnet tiers to create."
  type        = number
  default     = 3
}

variable "private_subnet_cidrs" {
  description = "IPv4 CIDRs for the private (Karpenter/EKS node) subnets, one per AZ."
  type        = list(string)
  default     = ["10.1.0.0/18", "10.1.64.0/18", "10.1.128.0/18"]
}

variable "public_subnet_cidrs" {
  description = "IPv4 CIDRs for the public (load balancer) subnets, one per AZ."
  type        = list(string)
  default     = ["10.1.192.0/22", "10.1.196.0/22", "10.1.200.0/22"]
}

variable "enable_database_subnets" {
  description = "Whether to create the isolated database subnet tier (disabled by default)."
  type        = bool
  default     = false
}

variable "database_subnet_cidrs" {
  description = "IPv4 CIDRs for the database subnets, one per AZ."
  type        = list(string)
  default     = ["10.1.204.0/22", "10.1.208.0/22", "10.1.212.0/22"]
}

variable "enable_cache_subnets" {
  description = "Whether to create the isolated cache subnet tier (disabled by default)."
  type        = bool
  default     = false
}

variable "cache_subnet_cidrs" {
  description = "IPv4 CIDRs for the cache subnets, one per AZ."
  type        = list(string)
  default     = ["10.1.216.0/22", "10.1.220.0/22", "10.1.224.0/22"]
}

variable "enable_intranet_subnets" {
  description = "Whether to create the internal (no internet access) subnet tier (disabled by default)."
  type        = bool
  default     = false
}

variable "intranet_subnet_cidrs" {
  description = "IPv4 CIDRs for the internal subnets, one per AZ."
  type        = list(string)
  default     = ["10.1.228.0/22", "10.1.232.0/22", "10.1.236.0/22"]
}

###############################################################################
# VPC (dual-stack)
###############################################################################

resource "aws_vpc" "this" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = merge(local.cluster_tags, {
    Name = var.name
  })
}

###############################################################################
# Gateways
###############################################################################

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = var.name
  }
}

resource "aws_egress_only_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = var.name
  }
}

###############################################################################
# Public subnets (one shared route table)
###############################################################################

resource "aws_subnet" "public" {
  count = var.az_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  ipv6_cidr_block         = cidrsubnet(aws_vpc.this.ipv6_cidr_block, 8, count.index + var.az_count)

  tags = merge(local.cluster_tags, local.karpenter_tags, {
    Name                     = "${var.name}-public-${local.azs[count.index]}"
    "kubernetes.io/role/elb" = "1"
    Tier                     = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.name}-public"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  count = var.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Private subnets (per-AZ route table, NAT + egress-only gateway)
###############################################################################

resource "aws_subnet" "private" {
  count = var.az_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  ipv6_cidr_block         = cidrsubnet(aws_vpc.this.ipv6_cidr_block, 8, count.index)

  tags = merge(local.cluster_tags, local.karpenter_tags, {
    Name                              = "${var.name}-private-${local.azs[count.index]}"
    "kubernetes.io/role/internal-elb" = "1"
    Tier                              = "private"
  })
}

resource "aws_eip" "nat" {
  count  = var.az_count
  domain = "vpc"

  tags = {
    Name = "${var.name}-nat-${local.azs[count.index]}"
  }

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  count = var.az_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.name}-nat-${local.azs[count.index]}"
  }

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  count = var.az_count

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.name}-private-${local.azs[count.index]}"
  }
}

resource "aws_route" "private_ipv4" {
  count = var.az_count

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index].id
}

resource "aws_route" "private_ipv6" {
  count = var.az_count

  route_table_id              = aws_route_table.private[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this.id
}

resource "aws_route_table_association" "private" {
  count = var.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# S3 gateway VPC endpoint (attached to the private route tables)
###############################################################################

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.name}-s3"
  }
}

###############################################################################
# Optional: isolated database subnet tier
###############################################################################

resource "aws_subnet" "database" {
  count = var.enable_database_subnets ? var.az_count : 0

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.database_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.cluster_tags, {
    Name = "${var.name}-database-${local.azs[count.index]}"
    Tier = "database"
  })
}

resource "aws_route_table" "database" {
  count = var.enable_database_subnets ? var.az_count : 0

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.name}-database-${local.azs[count.index]}"
  }
}

resource "aws_route_table_association" "database" {
  count = var.enable_database_subnets ? var.az_count : 0

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database[count.index].id
}

resource "aws_db_subnet_group" "database" {
  count = var.enable_database_subnets ? 1 : 0

  name       = "${var.name}-database"
  subnet_ids = aws_subnet.database[*].id

  tags = {
    Name = "${var.name}-database"
  }
}

###############################################################################
# Optional: isolated cache subnet tier
###############################################################################

resource "aws_subnet" "cache" {
  count = var.enable_cache_subnets ? var.az_count : 0

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.cache_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.cluster_tags, {
    Name = "${var.name}-cache-${local.azs[count.index]}"
    Tier = "cache"
  })
}

resource "aws_route_table" "cache" {
  count = var.enable_cache_subnets ? var.az_count : 0

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.name}-cache-${local.azs[count.index]}"
  }
}

resource "aws_route_table_association" "cache" {
  count = var.enable_cache_subnets ? var.az_count : 0

  subnet_id      = aws_subnet.cache[count.index].id
  route_table_id = aws_route_table.cache[count.index].id
}

resource "aws_elasticache_subnet_group" "cache" {
  count = var.enable_cache_subnets ? 1 : 0

  name       = "${var.name}-cache"
  subnet_ids = aws_subnet.cache[*].id

  tags = {
    Name = "${var.name}-cache"
  }
}

###############################################################################
# Optional: internal subnet tier (no internet access)
###############################################################################

resource "aws_subnet" "intranet" {
  count = var.enable_intranet_subnets ? var.az_count : 0

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.intranet_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.cluster_tags, {
    Name = "${var.name}-intranet-${local.azs[count.index]}"
    Tier = "intranet"
  })
}

resource "aws_route_table" "intranet" {
  count = var.enable_intranet_subnets ? var.az_count : 0

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.name}-intranet-${local.azs[count.index]}"
  }
}

resource "aws_route_table_association" "intranet" {
  count = var.enable_intranet_subnets ? var.az_count : 0

  subnet_id      = aws_subnet.intranet[count.index].id
  route_table_id = aws_route_table.intranet[count.index].id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.this.id
}

output "vpc_ipv6_cidr_block" {
  description = "Amazon-provided IPv6 CIDR block of the VPC."
  value       = aws_vpc.this.ipv6_cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "database_subnet_group_name" {
  description = "Name of the RDS database subnet group (if enabled)."
  value       = try(aws_db_subnet_group.database[0].name, null)
}

output "cache_subnet_group_name" {
  description = "Name of the ElastiCache subnet group (if enabled)."
  value       = try(aws_elasticache_subnet_group.cache[0].name, null)
}

output "nat_gateway_ids" {
  description = "IDs of the NAT gateways."
  value       = aws_nat_gateway.this[*].id
}

###############################################################################
# Scheduled weather-data lake pipeline on AWS Glue, Step Functions & EventBridge
#
# Everything is created from scratch (greenfield account): the six data-lake
# buckets, the shared rotating KMS CMK used for their default encryption, the
# Glue service role, the two Glue 4.0 jobs, the Athena "silver" database, the
# Step Functions orchestration state machine and its hourly EventBridge trigger.
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.region

  tags = {
    Project   = "benchmark-weather-datalake"
    ManagedBy = "terraform"
  }

  # Every bucket name is the requested prefix followed by the AWS account ID,
  # which keeps the globally-unique S3 namespace partitioned per account.
  buckets = {
    artefacts = "benchmark-glue-artefacts-${local.account_id}"
    staging   = "benchmark-datalake-staging-${local.account_id}"
    bronze    = "benchmark-datalake-bronze-${local.account_id}"
    silver    = "benchmark-datalake-silver-${local.account_id}"
    gold      = "benchmark-datalake-gold-${local.account_id}"
    logs      = "benchmark-datalake-logs-${local.account_id}"
  }

  # Versioning is required only on the artefacts, bronze, silver and gold buckets.
  versioned_buckets = toset(["artefacts", "bronze", "silver", "gold"])

  # Local folder holding the Glue job sources.
  glue_source_folder = "glueClima"

  glue_extract_job_name   = "glue-job-extrai-dados"
  glue_transform_job_name = "glue-job-transforma-dados"

  glue_role_name          = "benchmark-glue-service-role"
  sfn_role_name           = "benchmark-stepfunctions-role"
  eventbridge_role_name   = "benchmark-eventbridge-sfn-role"
  kms_alias_name          = "benchmark-weather-datalake"
}

###############################################################################
# Shared, rotating customer-managed KMS key (and alias) for the data lake
###############################################################################

resource "aws_kms_key" "data_lake" {
  description             = "Shared CMK for the benchmark weather data lake"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.tags
}

resource "aws_kms_alias" "data_lake" {
  name          = "alias/${local.kms_alias_name}"
  target_key_id = aws_kms_key.data_lake.key_id
}

###############################################################################
# The six data-lake S3 buckets
###############################################################################

resource "aws_s3_bucket" "data_lake" {
  for_each = local.buckets

  bucket        = each.value
  force_destroy = true
  tags          = local.tags
}

# Block all public access on every bucket.
resource "aws_s3_bucket_public_access_block" "data_lake" {
  for_each = aws_s3_bucket.data_lake

  bucket                  = each.value.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Default SSE-KMS encryption with the shared customer-managed key.
resource "aws_s3_bucket_server_side_encryption_configuration" "data_lake" {
  for_each = aws_s3_bucket.data_lake

  bucket = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }
    bucket_key_enabled = true
  }
}

# Versioning on the artefacts, bronze, silver and gold buckets only.
resource "aws_s3_bucket_versioning" "data_lake" {
  for_each = local.versioned_buckets

  bucket = aws_s3_bucket.data_lake[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Upload the local Glue job sources into the artefacts bucket
#
# try(...) keeps the template deployable when the local folder is absent while
# still uploading the real sources whenever they are present.
###############################################################################

resource "aws_s3_object" "glue_extract_script" {
  bucket       = aws_s3_bucket.data_lake["artefacts"].id
  key          = "${local.glue_source_folder}/extraiDados.py"
  content      = try(file("${path.module}/${local.glue_source_folder}/extraiDados.py"), "# placeholder for extraiDados.py\n")
  content_type = "text/x-python"
  tags         = local.tags
}

resource "aws_s3_object" "glue_transform_script" {
  bucket       = aws_s3_bucket.data_lake["artefacts"].id
  key          = "${local.glue_source_folder}/transformaDados.py"
  content      = try(file("${path.module}/${local.glue_source_folder}/transformaDados.py"), "# placeholder for transformaDados.py\n")
  content_type = "text/x-python"
  tags         = local.tags
}

resource "aws_s3_object" "glue_lib" {
  bucket         = aws_s3_bucket.data_lake["artefacts"].id
  key            = "${local.glue_source_folder}/lib.zip"
  content_base64 = try(filebase64("${path.module}/${local.glue_source_folder}/lib.zip"), base64encode("placeholder"))
  content_type   = "application/zip"
  tags           = local.tags
}

###############################################################################
# Athena database backed by the silver bucket and encrypted with the shared CMK
###############################################################################

resource "aws_athena_database" "silver" {
  name   = "silver"
  bucket = aws_s3_bucket.data_lake["silver"].bucket

  encryption_configuration {
    encryption_option = "SSE_KMS"
    kms_key           = aws_kms_key.data_lake.arn
  }
}

###############################################################################
# IAM role + least-privilege policy for the Glue jobs
###############################################################################

resource "aws_iam_role" "glue" {
  name = local.glue_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "glue.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "glue" {
  name = "${local.glue_role_name}-policy"
  role = aws_iam_role.glue.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GlueServiceAccess"
        Effect = "Allow"
        Action = [
          "glue:GetDatabase",
          "glue:GetDatabases",
          "glue:GetTable",
          "glue:GetTables",
          "glue:GetPartition",
          "glue:GetPartitions",
          "glue:CreateTable",
          "glue:UpdateTable",
          "glue:DeleteTable",
          "glue:BatchCreatePartition",
          "glue:BatchUpdatePartition",
          "glue:BatchDeletePartition",
          "glue:GetConnection",
          "glue:GetConnections",
          "glue:GetJob",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:StartJobRun",
          "glue:BatchStopJobRun",
          "glue:GetCatalogImportStatus",
          "glue:GetDataCatalogEncryptionSettings",
          "glue:GetTags",
          "glue:TagResource"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents",
          "logs:AssociateKmsKey"
        ]
        Resource = "*"
      },
      {
        Sid      = "CloudWatchMetricsAccess"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"
      },
      {
        Sid    = "KmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.data_lake.arn
      },
      {
        Sid      = "DataLakeObjectAccess"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
        Resource = [for b in aws_s3_bucket.data_lake : "${b.arn}/*"]
      },
      {
        Sid      = "DataLakeBucketListing"
        Effect   = "Allow"
        Action   = ["s3:ListBucket", "s3:GetBucketLocation", "s3:ListBucketMultipartUploads"]
        Resource = [for b in aws_s3_bucket.data_lake : b.arn]
      }
    ]
  })
}

###############################################################################
# Glue 4.0 Python jobs
###############################################################################

resource "aws_glue_job" "extrai_dados" {
  name              = local.glue_extract_job_name
  role_arn          = aws_iam_role.glue.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.data_lake["artefacts"].bucket}/${local.glue_source_folder}/extraiDados.py"
    python_version  = "3"
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.data_lake["logs"].bucket}/tmp"
    "--job-language"                     = "python"
    "--enable-glue-datacatalog"          = "true"
    "--enable-metrics"                   = "true"
    "--enable-continuous-cloudwatch-log" = "true"
  }

  tags = local.tags
}

resource "aws_glue_job" "transforma_dados" {
  name              = local.glue_transform_job_name
  role_arn          = aws_iam_role.glue.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.data_lake["artefacts"].bucket}/${local.glue_source_folder}/transformaDados.py"
    python_version  = "3"
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.data_lake["logs"].bucket}/tmp"
    "--job-language"                     = "python"
    "--enable-glue-datacatalog"          = "true"
    "--enable-metrics"                   = "true"
    "--enable-continuous-cloudwatch-log" = "true"
    "--datalake-formats"                 = "iceberg"
    "--extra-py-files"                   = "s3://${aws_s3_bucket.data_lake["artefacts"].bucket}/${local.glue_source_folder}/lib.zip"
    "--additional-python-modules"        = "python-dateutil==2.9.0.post0"
  }

  tags = local.tags
}

###############################################################################
# Step Functions state machine orchestrating the two Glue jobs
###############################################################################

resource "aws_iam_role" "sfn" {
  name = local.sfn_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "states.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

# The orchestrator may only start/monitor the two Glue jobs it drives.
resource "aws_iam_role_policy" "sfn" {
  name = "${local.sfn_role_name}-policy"
  role = aws_iam_role.sfn.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StartAndMonitorGlueJobs"
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:BatchStopJobRun"
        ]
        Resource = [
          aws_glue_job.extrai_dados.arn,
          aws_glue_job.transforma_dados.arn
        ]
      }
    ]
  })
}

resource "aws_sfn_state_machine" "weather_pipeline" {
  name     = "benchmark-weather-pipeline"
  role_arn = aws_iam_role.sfn.arn

  definition = jsonencode({
    Comment = "Extract weather data then transform it into the bronze/silver layers"
    StartAt = "ExtractWeatherData"
    States = {
      ExtractWeatherData = {
        Type     = "Task"
        Resource = "arn:${local.partition}:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extrai_dados.name
          Arguments = {
            "--city"           = "Sao Paulo"
            "--staging_bucket" = local.buckets.staging
            "--api_key"        = "REPLACE_WITH_API_KEY"
          }
        }
        Next = "TransformWeatherData"
      }
      TransformWeatherData = {
        Type     = "Task"
        Resource = "arn:${local.partition}:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transforma_dados.name
          Arguments = {
            "--staging_bucket"  = local.buckets.staging
            "--bronze_bucket"   = local.buckets.bronze
            "--silver_bucket"   = local.buckets.silver
            "--translation_key" = "REPLACE_WITH_TRANSLATION_KEY"
          }
        }
        End = true
      }
    }
  })

  tags = local.tags
}

###############################################################################
# Hourly EventBridge schedule triggering the state machine
###############################################################################

resource "aws_cloudwatch_event_rule" "hourly_pipeline" {
  name                = "benchmark-weather-hourly"
  description         = "Runs the weather data lake pipeline every hour"
  schedule_expression = "rate(1 hour)"
  tags                = local.tags
}

resource "aws_iam_role" "eventbridge" {
  name = local.eventbridge_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "events.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

# The schedule may only start this state machine's executions.
resource "aws_iam_role_policy" "eventbridge" {
  name = "${local.eventbridge_role_name}-policy"
  role = aws_iam_role.eventbridge.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "StartStateMachineExecution"
        Effect   = "Allow"
        Action   = ["states:StartExecution"]
        Resource = [aws_sfn_state_machine.weather_pipeline.arn]
      }
    ]
  })
}

resource "aws_cloudwatch_event_target" "hourly_pipeline" {
  rule     = aws_cloudwatch_event_rule.hourly_pipeline.name
  arn      = aws_sfn_state_machine.weather_pipeline.arn
  role_arn = aws_iam_role.eventbridge.arn
}

###############################################################################
# Benchmark CI/CD static website pipeline
#
# Creates:
#   - Target S3 bucket for the static site (CloudFront origin)
#   - Artifact S3 bucket for CodePipeline  (+ optional access logging)
#   - Customer managed KMS key (rotation enabled) used for default encryption
#   - CloudFront distribution (OAC) in front of the site bucket
#   - CodeBuild project (small Linux container, 5 minute timeout)
#   - CodePipeline wired to a GitHub source (OAuth token OR CodeStar connection)
#   - SSM SecureString parameters + GitHub HMAC webhook
#   - Optional SNS pipeline notifications
###############################################################################

###############################################################################
# Provider metadata lookups (static / local only)
###############################################################################

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "Region the workload is nominally deployed to (defaults to us-east-1)."
  type        = string
  default     = "us-east-1"
}

variable "target_bucket_prefix" {
  description = "Prefix for the static site (target) S3 bucket. Account ID is appended."
  type        = string
  default     = "benchmark-cicd-target"
}

variable "artifact_bucket_prefix" {
  description = "Prefix for the CodePipeline artifact S3 bucket. Account ID is appended."
  type        = string
  default     = "benchmark-cicd-artifacts"
}

variable "github_owner" {
  description = "GitHub repository owner (user or organization)."
  type        = string
  default     = "example-org"
}

variable "github_repo" {
  description = "GitHub repository name."
  type        = string
  default     = "example-site"
}

variable "github_branch" {
  description = "GitHub branch the pipeline tracks."
  type        = string
  default     = "master"
}

variable "github_oauth_token" {
  description = "Placeholder GitHub OAuth token stored as an SSM SecureString parameter."
  type        = string
  default     = "placeholder-set-github-oauth-token"
  sensitive   = true
}

variable "github_webhook_secret" {
  description = "Placeholder GitHub webhook HMAC secret stored as an SSM SecureString parameter."
  type        = string
  default     = "placeholder-set-github-webhook-secret"
  sensitive   = true
}

variable "codestar_connection_arn" {
  description = "Optional CodeStar (CodeConnections) ARN. When set, it replaces the GitHub OAuth source."
  type        = string
  default     = ""
}

variable "invalidate_flag" {
  description = "Value passed to CodeBuild to decide whether a CloudFront invalidation is issued."
  type        = string
  default     = "true"
}

variable "enable_notifications" {
  description = "Whether to create SNS pipeline notifications (off by default)."
  type        = bool
  default     = false
}

variable "enable_artifact_logging" {
  description = "Whether to enable S3 access logging on the artifact bucket (off by default)."
  type        = bool
  default     = false
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  target_bucket_name   = "${var.target_bucket_prefix}-${local.account_id}"
  artifact_bucket_name = "${var.artifact_bucket_prefix}-${local.account_id}"
  log_bucket_name      = "${var.artifact_bucket_prefix}-logs-${local.account_id}"

  codebuild_name = "benchmark-cicd-build"
  pipeline_name  = "benchmark-cicd-pipeline"
  log_group_name = "/aws/codebuild/benchmark-cicd-build"

  common_tags = {
    Project   = "benchmark-cicd"
    ManagedBy = "terraform"
    Region    = var.aws_region
  }
}

###############################################################################
# KMS key (customer managed, rotation enabled)
###############################################################################

resource "aws_kms_key" "this" {
  description             = "Customer managed key for the benchmark CI/CD pipeline"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  is_enabled              = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAdmin"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowCloudWatchLogs"
        Effect    = "Allow"
        Principal = { Service = "logs.${local.region}.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource  = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"
          }
        }
      },
      {
        Sid       = "AllowSSM"
        Effect    = "Allow"
        Principal = { Service = "ssm.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Target (static site) S3 bucket
###############################################################################

resource "aws_s3_bucket" "target" {
  bucket = local.target_bucket_name

  tags = merge(local.common_tags, { Name = local.target_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "target" {
  bucket = aws_s3_bucket.target.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "target" {
  bucket = aws_s3_bucket.target.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "target" {
  bucket = aws_s3_bucket.target.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target" {
  bucket = aws_s3_bucket.target.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "target" {
  bucket = aws_s3_bucket.target.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontServicePrincipalRead"
        Effect    = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.target.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.this.arn
          }
        }
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.target.arn,
          "${aws_s3_bucket.target.arn}/*"
        ]
        Condition = {
          Bool = { "aws:SecureTransport" = "false" }
        }
      }
    ]
  })
}

###############################################################################
# Artifact S3 bucket
###############################################################################

resource "aws_s3_bucket" "artifact" {
  bucket = local.artifact_bucket_name

  tags = merge(local.common_tags, { Name = local.artifact_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact" {
  bucket = aws_s3_bucket.artifact.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "artifact" {
  bucket = aws_s3_bucket.artifact.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "artifact" {
  bucket = aws_s3_bucket.artifact.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact" {
  bucket = aws_s3_bucket.artifact.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# Deny any request that is not made over TLS.
resource "aws_s3_bucket_policy" "artifact" {
  bucket = aws_s3_bucket.artifact.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
        Condition = {
          Bool = { "aws:SecureTransport" = "false" }
        }
      }
    ]
  })
}

###############################################################################
# Optional access-logging bucket for the artifact bucket (off by default)
###############################################################################

resource "aws_s3_bucket" "log" {
  count = var.enable_artifact_logging ? 1 : 0

  bucket = local.log_bucket_name

  tags = merge(local.common_tags, { Name = local.log_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "log" {
  count = var.enable_artifact_logging ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "log" {
  count = var.enable_artifact_logging ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "log" {
  count = var.enable_artifact_logging ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log" {
  count = var.enable_artifact_logging ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "log" {
  count = var.enable_artifact_logging ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3ServerAccessLogging"
        Effect    = "Allow"
        Principal = { Service = "logging.s3.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.log[0].arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.artifact.arn
          }
        }
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.log[0].arn,
          "${aws_s3_bucket.log[0].arn}/*"
        ]
        Condition = {
          Bool = { "aws:SecureTransport" = "false" }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "artifact" {
  count = var.enable_artifact_logging ? 1 : 0

  bucket        = aws_s3_bucket.artifact.id
  target_bucket = aws_s3_bucket.log[0].id
  target_prefix = "artifact-access-logs/"
}

###############################################################################
# AWS WAFv2 (CLOUDFRONT scope) protecting the distribution
###############################################################################

resource "aws_wafv2_web_acl" "this" {
  name        = "benchmark-cicd-waf"
  description = "WAF protecting the benchmark CI/CD static site distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = true
    }
  }

  rule {
    name     = "AWSManagedRulesKnownBadInputsRuleSet"
    priority = 2

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesKnownBadInputsRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesKnownBadInputsRuleSet"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "benchmarkCicdWaf"
    sampled_requests_enabled   = true
  }

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "waf" {
  name              = "aws-waf-logs-benchmark-cicd"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.this.arn

  tags = local.common_tags
}

resource "aws_wafv2_web_acl_logging_configuration" "this" {
  log_destination_configs = [aws_cloudwatch_log_group.waf.arn]
  resource_arn            = aws_wafv2_web_acl.this.arn
}

###############################################################################
# CloudFront distribution (Origin Access Control) in front of the site bucket
###############################################################################

resource "aws_cloudfront_origin_access_control" "this" {
  name                              = "benchmark-cicd-oac"
  description                       = "OAC for the benchmark CI/CD static site bucket"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "this" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "benchmark-cicd static site distribution"
  default_root_object = "index.html"
  price_class         = "PriceClass_100"
  web_acl_id          = aws_wafv2_web_acl.this.arn

  origin {
    domain_name              = aws_s3_bucket.target.bucket_regional_domain_name
    origin_id                = "s3-${local.target_bucket_name}"
    origin_access_control_id = aws_cloudfront_origin_access_control.this.id
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "s3-${local.target_bucket_name}"
    viewer_protocol_policy = "redirect-to-https"
    compress               = true

    # AWS managed "CachingOptimized" cache policy.
    cache_policy_id = "658327ea-f89d-4fab-a63d-7e88639e58f6"

    min_ttl     = 0
    default_ttl = 3600
    max_ttl     = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = local.common_tags
}

###############################################################################
# CloudWatch log group for CodeBuild
###############################################################################

resource "aws_cloudwatch_log_group" "codebuild" {
  name              = local.log_group_name
  retention_in_days = 30
  kms_key_id        = aws_kms_key.this.arn

  tags = local.common_tags
}

###############################################################################
# SSM SecureString parameters (placeholder values)
###############################################################################

resource "aws_ssm_parameter" "github_token" {
  name   = "/benchmark-cicd/github/oauth-token"
  type   = "SecureString"
  value  = var.github_oauth_token
  key_id = aws_kms_key.this.arn

  tags = local.common_tags
}

resource "aws_ssm_parameter" "webhook_secret" {
  name   = "/benchmark-cicd/github/webhook-secret"
  type   = "SecureString"
  value  = var.github_webhook_secret
  key_id = aws_kms_key.this.arn

  tags = local.common_tags
}

###############################################################################
# CodeBuild service role
###############################################################################

resource "aws_iam_role" "codebuild" {
  name = "benchmark-cicd-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codebuild.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "codebuild" {
  name = "benchmark-cicd-codebuild-policy"
  role = aws_iam_role.codebuild.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild.arn,
          "${aws_cloudwatch_log_group.codebuild.arn}:*"
        ]
      },
      {
        Sid    = "BucketsAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:AbortMultipartUpload",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.target.arn,
          "${aws_s3_bucket.target.arn}/*",
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
      },
      {
        Sid    = "KmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.this.arn]
      },
      {
        Sid    = "CloudFrontInvalidation"
        Effect = "Allow"
        Action = [
          "cloudfront:CreateInvalidation",
          "cloudfront:GetInvalidation"
        ]
        Resource = [aws_cloudfront_distribution.this.arn]
      },
      {
        Sid    = "SsmRead"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters"
        ]
        Resource = [
          aws_ssm_parameter.github_token.arn,
          aws_ssm_parameter.webhook_secret.arn
        ]
      }
    ]
  })
}

###############################################################################
# CodeBuild project
###############################################################################

resource "aws_codebuild_project" "this" {
  name          = local.codebuild_name
  description   = "Builds the benchmark static site and syncs it to S3"
  build_timeout = 5
  service_role  = aws_iam_role.codebuild.arn
  encryption_key = aws_kms_key.this.arn

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "TARGET_BUCKET"
      value = aws_s3_bucket.target.bucket
    }

    environment_variable {
      name  = "CLOUDFRONT_DISTRIBUTION_ID"
      value = aws_cloudfront_distribution.this.id
    }

    environment_variable {
      name  = "INVALIDATE_FLAG"
      value = var.invalidate_flag
    }

    environment_variable {
      name  = "ARTIFACT_BUCKET"
      value = aws_s3_bucket.artifact.bucket
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild.name
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = <<-BUILDSPEC
      version: 0.2
      phases:
        pre_build:
          commands:
            - echo "Deploying site to $TARGET_BUCKET"
        build:
          commands:
            - aws s3 sync . "s3://$TARGET_BUCKET" --delete --exclude ".git/*"
        post_build:
          commands:
            - |
              if [ "$INVALIDATE_FLAG" = "true" ]; then
                aws cloudfront create-invalidation \
                  --distribution-id "$CLOUDFRONT_DISTRIBUTION_ID" \
                  --paths "/*"
              fi
      artifacts:
        files:
          - '**/*'
        base-directory: .
    BUILDSPEC
  }

  tags = local.common_tags
}

###############################################################################
# CodePipeline service role
###############################################################################

resource "aws_iam_role" "codepipeline" {
  name = "benchmark-cicd-codepipeline-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codepipeline.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "codepipeline" {
  name = "benchmark-cicd-codepipeline-policy"
  role = aws_iam_role.codepipeline.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "ArtifactStoreAccess"
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:GetObjectVersion",
            "s3:PutObject",
            "s3:GetBucketVersioning",
            "s3:GetBucketLocation",
            "s3:ListBucket",
            "s3:ListBucketMultipartUploads",
            "s3:AbortMultipartUpload"
          ]
          Resource = [
            aws_s3_bucket.artifact.arn,
            "${aws_s3_bucket.artifact.arn}/*"
          ]
        },
        {
          Sid    = "CodeBuildActions"
          Effect = "Allow"
          Action = [
            "codebuild:StartBuild",
            "codebuild:BatchGetBuilds",
            "codebuild:StopBuild"
          ]
          Resource = [aws_codebuild_project.this.arn]
        },
        {
          Sid    = "KmsAccess"
          Effect = "Allow"
          Action = [
            "kms:Encrypt",
            "kms:Decrypt",
            "kms:GenerateDataKey",
            "kms:DescribeKey"
          ]
          Resource = [aws_kms_key.this.arn]
        },
        {
          Sid    = "SsmRead"
          Effect = "Allow"
          Action = [
            "ssm:GetParameter",
            "ssm:GetParameters"
          ]
          Resource = [
            aws_ssm_parameter.github_token.arn,
            aws_ssm_parameter.webhook_secret.arn
          ]
        }
      ],
      var.codestar_connection_arn != "" ? [
        {
          Sid      = "UseCodeStarConnection"
          Effect   = "Allow"
          Action   = ["codestar-connections:UseConnection"]
          Resource = [var.codestar_connection_arn]
        }
      ] : [],
      var.enable_notifications ? [
        {
          Sid      = "SnsPublish"
          Effect   = "Allow"
          Action   = ["sns:Publish"]
          Resource = [aws_sns_topic.notifications[0].arn]
        }
      ] : []
    )
  })
}

###############################################################################
# CodePipeline
###############################################################################

resource "aws_codepipeline" "this" {
  name     = local.pipeline_name
  role_arn = aws_iam_role.codepipeline.arn

  artifact_store {
    location = aws_s3_bucket.artifact.bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.this.arn
      type = "KMS"
    }
  }

  stage {
    name = "Source"

    action {
      name             = "Source"
      category         = "Source"
      owner            = var.codestar_connection_arn != "" ? "AWS" : "ThirdParty"
      provider         = var.codestar_connection_arn != "" ? "CodeStarSourceConnection" : "GitHub"
      version          = "1"
      output_artifacts = ["source_output"]

      configuration = var.codestar_connection_arn != "" ? {
        ConnectionArn        = var.codestar_connection_arn
        FullRepositoryId     = "${var.github_owner}/${var.github_repo}"
        BranchName           = var.github_branch
        OutputArtifactFormat = "CODE_ZIP"
        } : {
        Owner      = var.github_owner
        Repo       = var.github_repo
        Branch     = var.github_branch
        OAuthToken = aws_ssm_parameter.github_token.value
      }
    }
  }

  stage {
    name = "Build"

    action {
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      version          = "1"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]

      configuration = {
        ProjectName = aws_codebuild_project.this.name
      }
    }
  }

  tags = local.common_tags
}

###############################################################################
# GitHub HMAC webhook (only used when OAuth source is active)
###############################################################################

resource "aws_codepipeline_webhook" "this" {
  count = var.codestar_connection_arn == "" ? 1 : 0

  name            = "benchmark-cicd-webhook"
  authentication  = "GITHUB_HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.this.name

  authentication_configuration {
    secret_token = aws_ssm_parameter.webhook_secret.value
  }

  filter {
    json_path    = "$.ref"
    match_equals = "refs/heads/${var.github_branch}"
  }

  tags = local.common_tags
}

###############################################################################
# Optional SNS pipeline notifications (off by default)
###############################################################################

resource "aws_sns_topic" "notifications" {
  count = var.enable_notifications ? 1 : 0

  name = "benchmark-cicd-notifications"

  tags = local.common_tags
}

resource "aws_codestarnotifications_notification_rule" "this" {
  count = var.enable_notifications ? 1 : 0

  name        = "benchmark-cicd-notifications"
  detail_type = "BASIC"

  event_type_ids = [
    "codepipeline-pipeline-pipeline-execution-started",
    "codepipeline-pipeline-pipeline-execution-succeeded",
    "codepipeline-pipeline-pipeline-execution-failed"
  ]

  resource = aws_codepipeline.this.arn

  target {
    address = aws_sns_topic.notifications[0].arn
  }

  tags = local.common_tags
}

##############################################################################
# Input variables
##############################################################################

variable "create_vpc" {
  description = "Module-level toggle that controls whether the VPC and all of its associated resources are created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name to be used on all resources as an identifier. The default VPC is named \"main\"."
  type        = string
  default     = "main"
}

variable "cidr" {
  description = "The IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "A tenancy option for instances launched into the VPC."
  type        = string
  default     = "default"

  validation {
    condition     = contains(["default", "dedicated", "host"], var.instance_tenancy)
    error_message = "The instance_tenancy value must be one of: default, dedicated, host."
  }
}

variable "enable_dns_support" {
  description = "Should be true to enable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Should be true to enable DNS hostnames in the VPC."
  type        = bool
  default     = false
}

variable "enable_ipv6" {
  description = "Should be true to request an Amazon-provided IPv6 CIDR block for the VPC."
  type        = bool
  default     = false
}

variable "azs" {
  description = "A list of availability zone names in the region. When empty, all available AZs are used."
  type        = list(string)
  default     = []
}

variable "subnet_newbits" {
  description = "Number of additional bits used to extend the VPC CIDR block when carving out subnet CIDRs."
  type        = number
  default     = 8
}

variable "single_nat_gateway" {
  description = "Should be true to provision a single shared NAT gateway for all private subnets, or false to provision one NAT gateway per availability zone."
  type        = bool
  default     = true
}

variable "map_public_ip_on_launch" {
  description = "Should be true to auto-assign public IP addresses to instances launched into public subnets."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of additional tags to add to all resources."
  type        = map(string)
  default     = {}
}

variable "subnets" {
  description = <<-EOT
    Optional list of subnet definitions. Each definition groups a set of subnets
    sharing a `name` and a `class` (public, private or intra). One subnet is
    created per availability zone for every definition, with CIDRs allocated
    automatically from the VPC CIDR block. Definitions can optionally be
    registered in the database and/or ElastiCache subnet groups.
  EOT
  type = list(object({
    name                     = string
    class                    = string
    database_subnet_group    = optional(bool, false)
    elasticache_subnet_group = optional(bool, false)
  }))
  default = []

  validation {
    condition = alltrue([
      for definition in var.subnets : contains(["public", "private", "intra"], definition.class)
    ])
    error_message = "Each subnet definition `class` must be one of: public, private, intra."
  }
}

##############################################################################
# Data sources
##############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

##############################################################################
# Local values
##############################################################################

locals {
  # Availability zones to spread subnets across.
  azs     = length(var.azs) > 0 ? var.azs : data.aws_availability_zones.available.names
  num_azs = length(local.azs)

  # Only consider subnet definitions when the module is enabled.
  subnet_definitions = var.create_vpc ? var.subnets : []

  # Expand every definition into one subnet per availability zone.
  subnet_objects = flatten([
    for definition_index, definition in local.subnet_definitions : [
      for az_index, az in local.azs : {
        key         = "${definition.name}-${az}"
        name        = definition.name
        class       = definition.class
        az          = az
        cidr        = cidrsubnet(var.cidr, var.subnet_newbits, definition_index * local.num_azs + az_index)
        database    = definition.database_subnet_group
        elasticache = definition.elasticache_subnet_group
      }
    ]
  ])

  subnets = { for subnet in local.subnet_objects : subnet.key => subnet }

  # Subnets partitioned by class.
  public_subnets  = { for key, subnet in local.subnets : key => subnet if subnet.class == "public" }
  private_subnets = { for key, subnet in local.subnets : key => subnet if subnet.class == "private" }
  intra_subnets   = { for key, subnet in local.subnets : key => subnet if subnet.class == "intra" }

  # Deterministically ordered public subnet keys used to place NAT gateways.
  public_subnet_keys = sort([for key, subnet in local.public_subnets : key])

  # Distinct AZs that contain private subnets.
  private_azs = distinct([for key, subnet in local.private_subnets : subnet.az])

  # NAT gateways are only created when both public and private subnets exist.
  nat_gateway_count = (
    length(local.private_subnets) == 0 || length(local.public_subnets) == 0 ? 0 :
    var.single_nat_gateway ? 1 : length(local.private_azs)
  )

  # Subnet group membership.
  database_subnet_keys    = [for key, subnet in local.subnets : key if subnet.database]
  elasticache_subnet_keys = [for key, subnet in local.subnets : key if subnet.elasticache]

  # Shared tag set applied to every resource.
  tags = merge(var.tags, { Name = var.name })
}

##############################################################################
# VPC
##############################################################################

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block                       = var.cidr
  instance_tenancy                 = var.instance_tenancy
  enable_dns_support               = var.enable_dns_support
  enable_dns_hostnames             = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = var.enable_ipv6

  tags = local.tags
}

##############################################################################
# Subnets
##############################################################################

resource "aws_subnet" "this" {
  for_each = local.subnets

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = var.map_public_ip_on_launch && each.value.class == "public"

  tags = merge(var.tags, {
    Name  = "${var.name}-${each.value.name}-${each.value.az}"
    Class = each.value.class
  })
}

##############################################################################
# Internet gateway and public routing
##############################################################################

resource "aws_internet_gateway" "this" {
  count = (var.create_vpc && length(local.public_subnets) > 0) ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.tags, { Name = "${var.name}-igw" })
}

resource "aws_route_table" "public" {
  count = (var.create_vpc && length(local.public_subnets) > 0) ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.tags, { Name = "${var.name}-public" })
}

resource "aws_route" "public_internet_gateway" {
  count = (var.create_vpc && length(local.public_subnets) > 0) ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public[0].id
}

##############################################################################
# NAT gateways and private routing
##############################################################################

resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(local.tags, { Name = "${var.name}-nat-${count.index}" })
}

resource "aws_nat_gateway" "this" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.this[local.public_subnet_keys[(var.single_nat_gateway ? 0 : count.index) % length(local.public_subnet_keys)]].id

  tags = merge(local.tags, { Name = "${var.name}-nat-${count.index}" })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  count = local.nat_gateway_count

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.tags, { Name = "${var.name}-private-${count.index}" })
}

resource "aws_route" "private_nat_gateway" {
  count = local.nat_gateway_count

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index].id
}

resource "aws_route_table_association" "private" {
  for_each = local.nat_gateway_count > 0 ? local.private_subnets : {}

  subnet_id = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private[
    var.single_nat_gateway ? 0 : index(local.private_azs, each.value.az)
  ].id
}

##############################################################################
# Intra routing (no route to the internet)
##############################################################################

resource "aws_route_table" "intra" {
  count = (var.create_vpc && length(local.intra_subnets) > 0) ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.tags, { Name = "${var.name}-intra" })
}

resource "aws_route_table_association" "intra" {
  for_each = local.intra_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.intra[0].id
}

##############################################################################
# Database and ElastiCache subnet groups
##############################################################################

resource "aws_db_subnet_group" "this" {
  count = (var.create_vpc && length(local.database_subnet_keys) > 0) ? 1 : 0

  name        = "${var.name}-db"
  description = "Database subnet group for ${var.name}"
  subnet_ids  = [for key in local.database_subnet_keys : aws_subnet.this[key].id]

  tags = merge(local.tags, { Name = "${var.name}-db" })
}

resource "aws_elasticache_subnet_group" "this" {
  count = (var.create_vpc && length(local.elasticache_subnet_keys) > 0) ? 1 : 0

  name        = "${var.name}-elasticache"
  description = "ElastiCache subnet group for ${var.name}"
  subnet_ids  = [for key in local.elasticache_subnet_keys : aws_subnet.this[key].id]
}

##############################################################################
# Outputs
##############################################################################

output "vpc_id" {
  description = "The ID of the VPC."
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC."
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "vpc_ipv6_cidr_block" {
  description = "The IPv6 CIDR block of the VPC (if enabled)."
  value       = try(aws_vpc.this[0].ipv6_cidr_block, null)
}

output "internet_gateway_id" {
  description = "The ID of the internet gateway."
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "public_subnets" {
  description = "List of IDs of the public subnets."
  value       = [for key in sort(keys(local.public_subnets)) : aws_subnet.this[key].id]
}

output "private_subnets" {
  description = "List of IDs of the private subnets."
  value       = [for key in sort(keys(local.private_subnets)) : aws_subnet.this[key].id]
}

output "intra_subnets" {
  description = "List of IDs of the intra subnets."
  value       = [for key in sort(keys(local.intra_subnets)) : aws_subnet.this[key].id]
}

output "nat_gateway_ids" {
  description = "List of IDs of the NAT gateways."
  value       = aws_nat_gateway.this[*].id
}

output "database_subnet_group" {
  description = "The name of the database subnet group (if created)."
  value       = try(aws_db_subnet_group.this[0].name, null)
}

output "elasticache_subnet_group" {
  description = "The name of the ElastiCache subnet group (if created)."
  value       = try(aws_elasticache_subnet_group.this[0].name, null)
}

data "aws_partition" "current" {}

locals {
  role_name             = "ec2-ssm-association"
  instance_profile_name = "ec2-s3-ssm-association"
  ssm_core_policy_arn   = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role" "ec2_ssm_association" {
  name        = local.role_name
  description = "IAM role assumed by EC2 instances managed through AWS Systems Manager"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = local.role_name
  }
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ec2_ssm_association.name
  policy_arn = local.ssm_core_policy_arn
}

resource "aws_iam_instance_profile" "ec2_s3_ssm_association" {
  name = local.instance_profile_name
  role = aws_iam_role.ec2_ssm_association.name

  tags = {
    Name = local.instance_profile_name
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  dlq_name              = "aggregation-lambda-dead-letter-queue"
  dlq_retention_seconds = 14 * 24 * 60 * 60 # 14 days
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# Customer-managed KMS key used to encrypt the dead-letter queue
resource "aws_kms_key" "dlq" {
  description             = "Customer-managed KMS key for ${local.dlq_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSQSServiceUsage"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = local.dlq_name
  }
}

# SQS dead-letter queue, 14-day retention, encrypted with the CMK above
resource "aws_sqs_queue" "dlq" {
  name                              = local.dlq_name
  message_retention_seconds         = local.dlq_retention_seconds
  kms_master_key_id                 = aws_kms_key.dlq.arn
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Name = local.dlq_name
  }
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

locals {
  # Account-level SNS SMS default messaging type.
  # "Transactional" is used for time-sensitive, one-time messages (e.g. OTPs).
  default_sms_type = "Transactional"

  # Sampling rate (percentage) of successful delivery-status events logged.
  # "0" disables successful-delivery event logging entirely.
  delivery_status_success_sampling_rate = "0"
}

# Account-level Amazon SNS SMS messaging preferences.
# The sender ID, monthly spend limit, delivery-status IAM role, and usage-report
# bucket are intentionally left unset so the account defaults are preserved.
resource "aws_sns_sms_preferences" "this" {
  default_sms_type                      = local.default_sms_type
  delivery_status_success_sampling_rate = local.delivery_status_success_sampling_rate
}

output "default_sms_type" {
  description = "The default SMS type configured for the account."
  value       = aws_sns_sms_preferences.this.default_sms_type
}

output "delivery_status_success_sampling_rate" {
  description = "The sampling rate for successful delivery-status events."
  value       = aws_sns_sms_preferences.this.delivery_status_success_sampling_rate
}

output "default_sender_id" {
  description = "The default sender ID (unset, so the account default is used)."
  value       = aws_sns_sms_preferences.this.default_sender_id
}

output "monthly_spend_limit" {
  description = "The monthly spend limit (unset, so the account default is used)."
  value       = aws_sns_sms_preferences.this.monthly_spend_limit
}

output "delivery_status_iam_role_arn" {
  description = "The IAM role used for delivery-status logging (unset by default)."
  value       = aws_sns_sms_preferences.this.delivery_status_iam_role_arn
}

output "usage_report_s3_bucket" {
  description = "The S3 bucket for usage reports (unset by default)."
  value       = aws_sns_sms_preferences.this.usage_report_s3_bucket
}

data "aws_partition" "current" {}

locals {
  eks_role_name = "eks-cluster-sadcloud-example"
}

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    sid     = "AllowEKSClusterServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = local.eks_role_name
  description        = "IAM service role assumed by the Amazon EKS service for the sadcloud cluster"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json

  tags = {
    Name = local.eks_role_name
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSServicePolicy"
}

locals {
  log_group_name    = "logs-${random_pet.suffix.id}"
  retention_in_days = 7
}

# Random pet-name suffix used to make the log group name unique.
resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

# CloudWatch Logs log group holding application logs.
resource "aws_cloudwatch_log_group" "main" {
  name              = local.log_group_name
  retention_in_days = local.retention_in_days

  lifecycle {
    prevent_destroy = true
  }
}

# Least-privilege policy: only stream create/describe and event puts,
# scoped exclusively to the log group created above.
data "aws_iam_policy_document" "logs_access" {
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      "${aws_cloudwatch_log_group.main.arn}:*",
    ]
  }
}

resource "aws_iam_policy" "logs_access" {
  name        = "${local.log_group_name}-access"
  description = "Allows creating and describing log streams and putting log events on the ${local.log_group_name} log group."
  policy      = data.aws_iam_policy_document.logs_access.json
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "enable_ssm_automation_logging" {
  description = "When enabled (default), creates the SSM Automation CloudWatch log group, sends Automation script output to it, and disables public sharing of Systems Manager documents."
  type        = bool
  default     = true
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  ssm_service_setting_arn_prefix = "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:servicesetting"
  automation_log_group_name      = "/aws/ssm/automation/executeScript"
}

# CloudWatch log group that receives SSM Automation (aws:executeScript) output.
resource "aws_cloudwatch_log_group" "ssm_automation" {
  count = var.enable_ssm_automation_logging ? 1 : 0

  name              = local.automation_log_group_name
  retention_in_days = 14

  tags = {
    Name = local.automation_log_group_name
  }
}

# Send Automation customer script output to CloudWatch Logs.
resource "aws_ssm_service_setting" "automation_log_destination" {
  count = var.enable_ssm_automation_logging ? 1 : 0

  setting_id    = "${local.ssm_service_setting_arn_prefix}/ssm/automation/customer-script-log-destination"
  setting_value = "CloudWatch"
}

# Name of the CloudWatch log group that receives Automation script output.
resource "aws_ssm_service_setting" "automation_log_group" {
  count = var.enable_ssm_automation_logging ? 1 : 0

  setting_id    = "${local.ssm_service_setting_arn_prefix}/ssm/automation/customer-script-log-group-name"
  setting_value = aws_cloudwatch_log_group.ssm_automation[0].name

  depends_on = [aws_cloudwatch_log_group.ssm_automation]
}

# Disable public sharing of Systems Manager documents.
resource "aws_ssm_service_setting" "document_public_sharing" {
  count = var.enable_ssm_automation_logging ? 1 : 0

  setting_id    = "${local.ssm_service_setting_arn_prefix}/ssm/documents/console/public-sharing-permission"
  setting_value = "Disable"
}

##############################################################################
# Locals
##############################################################################

locals {
  create_ddb_backup_role_name   = "create_ddb_backup_role"
  remove_ddb_backup_role_name   = "remove_ddb_backup_role"
  create_ddb_backup_policy_name = "create_ddb_backup_policy"
  remove_ddb_backup_policy_name = "remove_ddb_backup_policy"
  lambda_logging_policy_name    = "lambda_logging"
}

##############################################################################
# Trust policy - allows the Lambda service to assume both roles
##############################################################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

##############################################################################
# IAM Roles assumable by Lambda
##############################################################################

resource "aws_iam_role" "create_ddb_backup_role" {
  name               = local.create_ddb_backup_role_name
  description        = "Lambda execution role used to create DynamoDB backups."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = {
    Name = local.create_ddb_backup_role_name
  }
}

resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = local.remove_ddb_backup_role_name
  description        = "Lambda execution role used to list and delete DynamoDB backups."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = {
    Name = local.remove_ddb_backup_role_name
  }
}

##############################################################################
# Customer-managed policy documents
##############################################################################

data "aws_iam_policy_document" "create_ddb_backup" {
  statement {
    sid    = "CreateDynamoDBBackups"
    effect = "Allow"
    actions = [
      "dynamodb:CreateBackup",
      "dynamodb:DescribeBackup",
      "dynamodb:DescribeTable",
      "dynamodb:ListTables",
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "remove_ddb_backup" {
  statement {
    sid    = "ListAndDeleteDynamoDBBackups"
    effect = "Allow"
    actions = [
      "dynamodb:DeleteBackup",
      "dynamodb:DescribeBackup",
      "dynamodb:ListBackups",
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    sid    = "CloudWatchLogsWrite"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["*"]
  }
}

##############################################################################
# Customer-managed policies
##############################################################################

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = local.create_ddb_backup_policy_name
  description = "Allows creation of DynamoDB backups."
  policy      = data.aws_iam_policy_document.create_ddb_backup.json

  tags = {
    Name = local.create_ddb_backup_policy_name
  }
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = local.remove_ddb_backup_policy_name
  description = "Allows listing and deletion of DynamoDB backups."
  policy      = data.aws_iam_policy_document.remove_ddb_backup.json

  tags = {
    Name = local.remove_ddb_backup_policy_name
  }
}

# Shared customer-managed policy granting CloudWatch Logs write access.
resource "aws_iam_policy" "lambda_logging" {
  name        = local.lambda_logging_policy_name
  description = "Allows Lambda functions to write logs to CloudWatch Logs."
  policy      = data.aws_iam_policy_document.lambda_logging.json

  tags = {
    Name = local.lambda_logging_policy_name
  }
}

##############################################################################
# Policy attachments
##############################################################################

resource "aws_iam_role_policy_attachment" "create_ddb_backup" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_logging" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_logging" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

##############################################################################
# Outputs
##############################################################################

output "create_ddb_backup_role_arn" {
  description = "ARN of the create_ddb_backup_role IAM role."
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "create_ddb_backup_role_name" {
  description = "Name of the create_ddb_backup_role IAM role."
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the remove_ddb_backup_role IAM role."
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the remove_ddb_backup_role IAM role."
  value       = aws_iam_role.remove_ddb_backup_role.name
}

data "aws_partition" "current" {}

locals {
  admin_group_name           = "admin"
  admin_read_only_group_name = "admin_read_only"
  developer_group_name       = "developer_group"

  admin_membership_name           = "admin_team"
  admin_read_only_membership_name = "read_only_admin_team"
  developer_membership_name       = "developers"

  administrator_access_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AdministratorAccess"
  read_only_access_policy_arn     = "arn:${data.aws_partition.current.partition}:iam::aws:policy/ReadOnlyAccess"
  s3_full_access_policy_arn       = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
  iam_user_change_password_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/IAMUserChangePassword"
}

