###############################################################################
# GitHub Actions OIDC identity provider for AWS
#
# Creates the IAM OIDC identity provider used by GitHub Actions to obtain
# short-lived AWS credentials via sts:AssumeRoleWithWebIdentity, and optionally
# creates GitHub-federated IAM roles (none are created by default).
#
# Thumbprint list = live CA fingerprints from the issuer's TLS certificate
# chain + GitHub's two published thumbprints (de-duplicated).
###############################################################################

###############################################################################
# Variables
###############################################################################

variable "github_oidc_roles" {
  description = <<-EOT
    Optional map of GitHub Actions federated IAM roles to create. The map key is
    used as the Terraform identifier for the role. The map defaults to empty, so
    no roles are created unless explicitly configured.
  EOT
  type = map(object({
    name                 = optional(string)
    description          = optional(string)
    subject_claims       = optional(list(string), ["repo:my-org/my-repo:ref:refs/heads/main"])
    managed_policy_arns  = optional(list(string), [])
    inline_policies      = optional(map(string), {})
    max_session_duration = optional(number, 3600)
    tags                 = optional(map(string), {})
  }))
  default = {}
}

variable "tags" {
  description = "Common tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  github_oidc_url = "https://token.actions.githubusercontent.com"

  # GitHub's two published OIDC thumbprints. These are retained as a stable
  # fallback alongside the live CA fingerprints fetched from the issuer's TLS
  # certificate, so the provider stays valid even if a certificate rotates.
  github_published_thumbprints = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]
}

###############################################################################
# Fetch the CA fingerprints from the issuer's TLS certificate chain
###############################################################################

data "tls_certificate" "github" {
  url = local.github_oidc_url
}

locals {
  # SHA-1 fingerprints of every certificate in the issuer's chain (leaf -> root).
  github_ca_thumbprints = [
    for cert in data.tls_certificate.github.certificates : cert.sha1_fingerprint
  ]

  # Combine the live CA fingerprints with GitHub's published thumbprints,
  # de-duplicating any overlap.
  github_thumbprint_list = distinct(concat(
    local.github_ca_thumbprints,
    local.github_published_thumbprints,
  ))
}

###############################################################################
# IAM OIDC identity provider
###############################################################################

resource "aws_iam_openid_connect_provider" "github" {
  url = local.github_oidc_url

  client_id_list = ["sts.amazonaws.com"]

  thumbprint_list = local.github_thumbprint_list

  tags = merge(var.tags, { Name = "github-actions-oidc" })
}

###############################################################################
# Optional GitHub-federated IAM roles (none created by default)
###############################################################################

data "aws_iam_policy_document" "github_assume_role" {
  for_each = var.github_oidc_roles

  statement {
    sid     = "AllowGitHubActionsAssumeRoleWithWebIdentity"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = each.value.subject_claims
    }
  }
}

resource "aws_iam_role" "github" {
  for_each = var.github_oidc_roles

  name                 = coalesce(each.value.name, "github-actions-${each.key}")
  description          = coalesce(each.value.description, "GitHub Actions federated role managed by Terraform")
  assume_role_policy   = data.aws_iam_policy_document.github_assume_role[each.key].json
  max_session_duration = each.value.max_session_duration

  tags = merge(
    var.tags,
    each.value.tags,
    { Name = coalesce(each.value.name, "github-actions-${each.key}") },
  )
}

resource "aws_iam_role_policy_attachment" "github" {
  for_each = {
    for pair in flatten([
      for role_key, role in var.github_oidc_roles : [
        for arn in role.managed_policy_arns : {
          key      = "${role_key}::${arn}"
          role_key = role_key
          arn      = arn
        }
      ]
    ]) : pair.key => pair
  }

  role       = aws_iam_role.github[each.value.role_key].name
  policy_arn = each.value.arn
}

resource "aws_iam_role_policy" "github" {
  for_each = {
    for pair in flatten([
      for role_key, role in var.github_oidc_roles : [
        for policy_name, policy_json in role.inline_policies : {
          key         = "${role_key}::${policy_name}"
          role_key    = role_key
          policy_name = policy_name
          policy_json = policy_json
        }
      ]
    ]) : pair.key => pair
  }

  name   = each.value.policy_name
  role   = aws_iam_role.github[each.value.role_key].id
  policy = each.value.policy_json
}

###############################################################################
# Outputs
###############################################################################

output "github_oidc_provider_arn" {
  description = "ARN of the GitHub Actions IAM OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.arn
}

output "github_oidc_provider_url" {
  description = "Issuer URL of the GitHub Actions IAM OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.url
}

output "github_federated_role_arns" {
  description = "Map of GitHub-federated role keys to their ARNs (empty by default)."
  value       = { for k, role in aws_iam_role.github : k => role.arn }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name            = "projectvpc"
  vpc_cidr            = "10.0.0.0/16"
  public_subnet_cidr  = "10.0.1.0/24"
  private_subnet_cidr = "10.0.2.0/24"
  azs                 = data.aws_availability_zones.available.names
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidr
  availability_zone = local.azs[0]

  tags = {
    Name = "${local.vpc_name}-public-subnet"
    Type = "public"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidr
  availability_zone = local.azs[1]

  tags = {
    Name = "${local.vpc_name}-private-subnet"
    Type = "private"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-igw"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.vpc_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "${local.vpc_name}-nat-gateway"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${local.vpc_name}-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "${local.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

