locals {
  dev_vpc_cidr  = "10.0.0.0/16"
  test_vpc_cidr = "172.24.0.0/16"
  peer_name     = "dev-test-vpc-peer"

  public_subnet_offsets  = [101, 102]
  private_subnet_offsets = [1, 2]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)
}

# ---------------------------------------------------------------------------
# VPCs
# ---------------------------------------------------------------------------

resource "aws_vpc" "dev" {
  cidr_block           = local.dev_vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "dev"
  }
}

resource "aws_vpc" "test" {
  cidr_block           = local.test_vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test"
  }
}

# ---------------------------------------------------------------------------
# Internet gateways (make public subnets routable to the internet)
# ---------------------------------------------------------------------------

resource "aws_internet_gateway" "dev" {
  vpc_id = aws_vpc.dev.id

  tags = {
    Name = "dev-igw"
  }
}

resource "aws_internet_gateway" "test" {
  vpc_id = aws_vpc.test.id

  tags = {
    Name = "test-igw"
  }
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------

resource "aws_subnet" "dev_public" {
  count = length(local.public_subnet_offsets)

  vpc_id                  = aws_vpc.dev.id
  cidr_block              = cidrsubnet(local.dev_vpc_cidr, 8, local.public_subnet_offsets[count.index])
  availability_zone       = local.azs[count.index]

  tags = {
    Name = "dev-public-${count.index + 1}"
    Tier = "public"
  }
}

resource "aws_subnet" "dev_private" {
  count = length(local.private_subnet_offsets)

  vpc_id            = aws_vpc.dev.id
  cidr_block        = cidrsubnet(local.dev_vpc_cidr, 8, local.private_subnet_offsets[count.index])
  availability_zone = local.azs[count.index]

  tags = {
    Name = "dev-private-${count.index + 1}"
    Tier = "private"
  }
}

resource "aws_subnet" "test_public" {
  count = length(local.public_subnet_offsets)

  vpc_id                  = aws_vpc.test.id
  cidr_block              = cidrsubnet(local.test_vpc_cidr, 8, local.public_subnet_offsets[count.index])
  availability_zone       = local.azs[count.index]

  tags = {
    Name = "test-public-${count.index + 1}"
    Tier = "public"
  }
}

resource "aws_subnet" "test_private" {
  count = length(local.private_subnet_offsets)

  vpc_id            = aws_vpc.test.id
  cidr_block        = cidrsubnet(local.test_vpc_cidr, 8, local.private_subnet_offsets[count.index])
  availability_zone = local.azs[count.index]

  tags = {
    Name = "test-private-${count.index + 1}"
    Tier = "private"
  }
}

# ---------------------------------------------------------------------------
# VPC peering connection
# ---------------------------------------------------------------------------

resource "aws_vpc_peering_connection" "dev_test" {
  vpc_id      = aws_vpc.dev.id
  peer_vpc_id = aws_vpc.test.id
  auto_accept = true

  tags = {
    Name = local.peer_name
  }
}

resource "aws_vpc_peering_connection_options" "dev_test" {
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id

  requester {
    allow_remote_vpc_dns_resolution = true
  }

  accepter {
    allow_remote_vpc_dns_resolution = true
  }
}

# ---------------------------------------------------------------------------
# Route tables
# ---------------------------------------------------------------------------

resource "aws_route_table" "dev_public" {
  vpc_id = aws_vpc.dev.id

  tags = {
    Name = "dev-public-rt"
  }
}

resource "aws_route_table" "dev_private" {
  vpc_id = aws_vpc.dev.id

  tags = {
    Name = "dev-private-rt"
  }
}

resource "aws_route_table" "test_public" {
  vpc_id = aws_vpc.test.id

  tags = {
    Name = "test-public-rt"
  }
}

resource "aws_route_table" "test_private" {
  vpc_id = aws_vpc.test.id

  tags = {
    Name = "test-private-rt"
  }
}

# ---------------------------------------------------------------------------
# Routes
# ---------------------------------------------------------------------------

resource "aws_route" "dev_public_internet" {
  route_table_id         = aws_route_table.dev_public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.dev.id
}

resource "aws_route" "test_public_internet" {
  route_table_id         = aws_route_table.test_public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.test.id
}

resource "aws_route" "dev_public_peer" {
  route_table_id            = aws_route_table.dev_public.id
  destination_cidr_block    = local.test_vpc_cidr
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "dev_private_peer" {
  route_table_id            = aws_route_table.dev_private.id
  destination_cidr_block    = local.test_vpc_cidr
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "test_public_peer" {
  route_table_id            = aws_route_table.test_public.id
  destination_cidr_block    = local.dev_vpc_cidr
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "test_private_peer" {
  route_table_id            = aws_route_table.test_private.id
  destination_cidr_block    = local.dev_vpc_cidr
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

# ---------------------------------------------------------------------------
# Route table associations
# ---------------------------------------------------------------------------

resource "aws_route_table_association" "dev_public" {
  count = length(local.public_subnet_offsets)

  subnet_id      = aws_subnet.dev_public[count.index].id
  route_table_id = aws_route_table.dev_public.id
