resource "aws_iam_role_policy_attachment" "test_role2_test_policy2" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

# ---------------------------------------------------------------------------
# Single named policy attachment: test-policy3 to both roles
# ---------------------------------------------------------------------------

resource "aws_iam_policy_attachment" "test_attachment5" {
  name       = "test-attachment5"
  policy_arn = aws_iam_policy.test_policy3.arn
  roles      = [aws_iam_role.test_role.name, aws_iam_role.test_role2.name]
}

variable "role_name" {
  description = "Name of the IAM role assumed by GitHub Actions via OIDC web identity federation."
  type        = string
  default     = "github-actions-oidc-role"
}

variable "github_repository_patterns" {
  description = "List of GitHub repository subject patterns (e.g. \"repo:my-org/my-repo:*\") allowed to assume the role. Empty by default, meaning no repository subject is permitted to assume the role."
  type        = list(string)
  default     = []
}

variable "github_oidc_thumbprints" {
  description = "List of thumbprints for the GitHub Actions OIDC identity provider certificate chain."
  type        = list(string)
  default = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]
}

locals {
  # GitHub OIDC trust policies must scope the token subject (StringEquals /
  # StringLike on token.actions.githubusercontent.com:sub or
  # token.actions.githubusercontent.com:job_workflow_ref). When the configured
  # pattern list is empty (the default) we supply a sentinel pattern that
  # matches no repository so the policy stays valid while no subject is granted
  # access.
  effective_repository_patterns = length(var.github_repository_patterns) > 0 ? var.github_repository_patterns : ["repo:__none__/__none__:*"]
}

resource "aws_iam_openid_connect_provider" "github_actions" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = var.github_oidc_thumbprints

  tags = {
    Name = "github-actions-oidc"
  }
}

data "aws_iam_policy_document" "github_actions_assume_role" {
  statement {
    sid     = "GitHubActionsWebIdentity"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github_actions.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:iss"
      values   = ["https://token.actions.githubusercontent.com"]
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = local.effective_repository_patterns
    }
  }
}

resource "aws_iam_role" "github_actions" {
  name                  = var.role_name
  path                  = "/"
  description           = "IAM role assumed by GitHub Actions through OIDC web identity federation."
  assume_role_policy    = data.aws_iam_policy_document.github_actions_assume_role.json
  force_detach_policies = true

  tags = {
    Name = var.role_name
  }
}

output "role_arn" {
  description = "ARN of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.arn
}

output "role_name" {
  description = "Name of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.name
}

output "role_path" {
  description = "Path of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.path
}

output "role_unique_id" {
  description = "Unique ID of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.unique_id
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

locals {
  policy_name = "managed-force-mfa-policy"
  account_id  = data.aws_caller_identity.current.account_id
  partition   = data.aws_partition.current.partition
}

resource "aws_iam_policy" "managed_force_mfa" {
  name        = local.policy_name
  path        = "/"
  description = "Allows IAM users to view basic account information and manage their own password and virtual MFA device. MFA deactivation and broader self-inspection are only permitted when the user is signed in with MFA."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowViewAccountInfo"
        Effect = "Allow"
        Action = [
          "iam:GetAccountPasswordPolicy",
          "iam:GetAccountSummary",
          "iam:ListVirtualMFADevices"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowManageOwnPasswords"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser"
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnVirtualMFADevice"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnUserMFA"
        Effect = "Allow"
        Action = [
          "iam:EnableMFADevice",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowDeactivateOwnMFADeviceOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice"
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "AllowBroaderSelfInspectionOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "iam:ListAccessKeys",
          "iam:GetAccessKeyLastUsed",
          "iam:ListSSHPublicKeys",
          "iam:GetSSHPublicKey",
          "iam:ListSigningCertificates",
          "iam:ListServiceSpecificCredentials",
          "iam:GetLoginProfile"
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

