data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# IAM Groups
# ---------------------------------------------------------------------------
resource "aws_iam_group" "billing" {
  name = "BillingGroup"
  path = "/"
}

resource "aws_iam_group" "admin" {
  name = "AdminGroup"
  path = "/"
}

resource "aws_iam_group" "suport" {
  name = "SuportGroup"
  path = "/"
}

# ---------------------------------------------------------------------------
# IAM Users
# ---------------------------------------------------------------------------
resource "aws_iam_user" "billing" {
  name = "Billing"
  path = "/"
}

resource "aws_iam_user" "admin" {
  name = "Admin"
  path = "/"
}

resource "aws_iam_user" "suport" {
  name = "Suport"
  path = "/"
}

# ---------------------------------------------------------------------------
# Console login profiles (8-character generated password)
# ---------------------------------------------------------------------------
resource "aws_iam_user_login_profile" "billing" {
  user                    = aws_iam_user.billing.name
  password_length         = 8
  password_reset_required = true
}

resource "aws_iam_user_login_profile" "admin" {
  user                    = aws_iam_user.admin.name
  password_length         = 8
  password_reset_required = true
}

resource "aws_iam_user_login_profile" "suport" {
  user                    = aws_iam_user.suport.name
  password_length         = 8
  password_reset_required = true
}

# ---------------------------------------------------------------------------
# Group membership
# ---------------------------------------------------------------------------
resource "aws_iam_user_group_membership" "billing" {
  user   = aws_iam_user.billing.name
  groups = [aws_iam_group.billing.name]
}

resource "aws_iam_user_group_membership" "admin" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "suport" {
  user   = aws_iam_user.suport.name
  groups = [aws_iam_group.suport.name]
}

# ---------------------------------------------------------------------------
# Billing read-only policy (custom)
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "billing" {
  statement {
    sid    = "BillingReadOnly"
    effect = "Allow"

    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
      "budgets:ViewBudget",
      "budgets:DescribeBudgets",
      "budgets:DescribeBudgetActionsForAccount",
      "budgets:DescribeBudgetActionsForBudget",
      "budgets:DescribeBudgetPerformanceHistory",
      "budgets:DescribeBudgetNotificationsForAccount",
      "ce:GetCostAndUsage",
      "ce:GetCostForecast",
      "ce:GetDimensionValues",
      "ce:GetReservationCoverage",
      "ce:GetReservationPurchaseRecommendation",
      "ce:GetReservationUtilization",
      "ce:GetRightsizingRecommendation",
      "ce:GetSavingsPlansCoverage",
      "ce:GetSavingsPlansPurchaseRecommendation",
      "ce:GetSavingsPlansUtilization",
      "ce:GetSavingsPlansUtilizationDetails",
      "ce:GetTags",
      "ce:GetUsageForecast",
      "cur:DescribeReportDefinitions",
      "pricing:DescribeServices",
      "pricing:GetAttributeValues",
      "pricing:GetProducts",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing" {
  name        = "BillingPolicy"
  description = "Read-only billing, usage, budget, cost report, and pricing visibility"
  policy      = data.aws_iam_policy_document.billing.json
}

resource "aws_iam_group_policy_attachment" "billing" {
  group      = aws_iam_group.billing.name
  policy_arn = aws_iam_policy.billing.arn
}

# ---------------------------------------------------------------------------
# Admin group - AWS managed AdministratorAccess
# ---------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "admin" {
  group      = aws_iam_group.admin.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AdministratorAccess"
}

# ---------------------------------------------------------------------------
# Support read-only policy (custom)
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "suport" {
  statement {
    sid    = "SupportReadOnly"
    effect = "Allow"

    actions = [
      "ec2:Describe*",
      "ec2:Get*",
      "ec2:List*",
      "s3:Describe*",
      "s3:Get*",
      "s3:List*",
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
      "rds:Describe*",
      "rds:List*",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "suport" {
  name        = "SuportPolicy"
  description = "Read-only describe, get, and list access to EC2, S3, CloudWatch, and RDS"
  policy      = data.aws_iam_policy_document.suport.json
}

resource "aws_iam_group_policy_attachment" "suport" {
  group      = aws_iam_group.suport.name
  policy_arn = aws_iam_policy.suport.arn
}

