      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

locals {
  efs_name = "shared-storage-testing"
}

# Terraform-generated creation token for the EFS file system.
resource "random_id" "efs_creation_token" {
  byte_length = 16
}

resource "aws_efs_file_system" "shared" {
  creation_token   = random_id.efs_creation_token.hex
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = {
    Name = local.efs_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_backup_policy" "shared" {
  file_system_id = aws_efs_file_system.shared.id

  backup_policy {
    status = "ENABLED"
  }
}

############################################################################
# Context data sources (static, provider-provided metadata only)
############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

############################################################################
# Local values
############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  # Remote state bucket: fixed prefix + current account ID
  state_bucket_name = "my-terraform-state-bucket-${local.account_id}"

  # NLP pipeline resources referenced by the service roles
  nlp_bucket_name = "nlp-pipeline-bucket"
  nlp_bucket_arn  = "arn:${local.partition}:s3:::${local.nlp_bucket_name}"

  nlp_results_table_name = "NLPResults"
  nlp_results_table_arn  = "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/${local.nlp_results_table_name}"

  state_machine_name = "YourStateMachineName"
  state_machine_arn  = "arn:${local.partition}:states:${local.region}:${local.account_id}:stateMachine:${local.state_machine_name}"

  # AWS managed policy ARNs (AWS-owned, global)
  glue_service_policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSGlueServiceRole"
  lambda_basic_policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

############################################################################
# KMS customer managed key for remote state encryption
############################################################################

data "aws_iam_policy_document" "state_kms_key" {
  statement {
    sid       = "EnableRootAccountAccess"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowAwsServicesUseOfKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]

    principals {
      type = "Service"
      identifiers = [
        "s3.amazonaws.com",
        "dynamodb.amazonaws.com",
      ]
    }
  }
}

resource "aws_kms_key" "terraform_state" {
  description             = "Customer managed KMS key for Terraform remote state encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.state_kms_key.json

  lifecycle {
    prevent_destroy = true
  }
}

############################################################################
# Terraform remote state S3 bucket
############################################################################

resource "aws_s3_bucket" "terraform_state" {
  bucket        = local.state_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

############################################################################
# Terraform remote state lock table
############################################################################

resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.terraform_state.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

############################################################################
# IAM trust policies
############################################################################

data "aws_iam_policy_document" "glue_assume_role" {
  statement {
    sid     = "GlueAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["glue.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "comprehend_assume_role" {
  statement {
    sid     = "ComprehendAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["comprehend.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "LambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "step_functions_assume_role" {
  statement {
    sid     = "StepFunctionsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

############################################################################
# Inline permission policies
############################################################################

# Shared object read/write access to the NLP pipeline bucket
data "aws_iam_policy_document" "nlp_bucket_object_access" {
  statement {
    sid    = "NlpBucketObjectAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = ["${local.nlp_bucket_arn}/*"]
  }
}

# Lambda execution permissions
data "aws_iam_policy_document" "lambda_execution_access" {
  statement {
    sid    = "NlpBucketObjectAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = ["${local.nlp_bucket_arn}/*"]
  }

  statement {
    sid    = "DynamoDbResultsWrite"
    effect = "Allow"

    actions = [
      "dynamodb:PutItem",
      "dynamodb:UpdateItem",
    ]

    resources = [local.nlp_results_table_arn]
  }

  statement {
    sid       = "StartNlpStateMachine"
    effect    = "Allow"
    actions   = ["states:StartExecution"]
    resources = [local.state_machine_arn]
  }
}

# Step Functions orchestration permissions
data "aws_iam_policy_document" "step_functions_access" {
  statement {
    sid       = "InvokeAnyLambdaFunction"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = ["arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"]
  }

  statement {
    sid       = "StartAnyGlueJobRun"
    effect    = "Allow"
    actions   = ["glue:StartJobRun"]
    resources = ["arn:${local.partition}:glue:${local.region}:${local.account_id}:job/*"]
  }
}

############################################################################
# Service roles
############################################################################

resource "aws_iam_role" "glue_service_role" {
  name                 = "glue-service-role"
  description          = "Service role assumed by AWS Glue for the NLP data pipeline"
  assume_role_policy   = data.aws_iam_policy_document.glue_assume_role.json
}

resource "aws_iam_role" "comprehend_service_role" {
  name               = "comprehend-service-role"
  description        = "Service role assumed by Amazon Comprehend for the NLP data pipeline"
  assume_role_policy = data.aws_iam_policy_document.comprehend_assume_role.json
}

resource "aws_iam_role" "lambda_execution_role" {
  name               = "lambda-execution-role"
  description        = "Execution role assumed by AWS Lambda functions in the NLP data pipeline"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

resource "aws_iam_role" "step_functions_service_role" {
  name               = "step-functions-service-role"
  description        = "Service role assumed by AWS Step Functions to orchestrate the NLP data pipeline"
  assume_role_policy = data.aws_iam_policy_document.step_functions_assume_role.json
}

############################################################################
# Managed policy attachments
############################################################################

resource "aws_iam_role_policy_attachment" "glue_service_role" {
  role       = aws_iam_role.glue_service_role.name
  policy_arn = local.glue_service_policy_arn
}

resource "aws_iam_role_policy_attachment" "lambda_execution_role" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = local.lambda_basic_policy_arn
}

############################################################################
# Inline role policies
############################################################################

resource "aws_iam_role_policy" "glue_s3_access" {
  name   = "glue-s3-object-access"
  role   = aws_iam_role.glue_service_role.id
  policy = data.aws_iam_policy_document.nlp_bucket_object_access.json
}

resource "aws_iam_role_policy" "comprehend_s3_access" {
  name   = "comprehend-s3-object-access"
  role   = aws_iam_role.comprehend_service_role.id
  policy = data.aws_iam_policy_document.nlp_bucket_object_access.json
}

resource "aws_iam_role_policy" "lambda_execution_access" {
  name   = "lambda-execution-access"
  role   = aws_iam_role.lambda_execution_role.id
  policy = data.aws_iam_policy_document.lambda_execution_access.json
}

resource "aws_iam_role_policy" "step_functions_access" {
  name   = "step-functions-access"
  role   = aws_iam_role.step_functions_service_role.id
  policy = data.aws_iam_policy_document.step_functions_access.json
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id    = data.aws_caller_identity.current.account_id
  region        = data.aws_region.current.name
  partition     = data.aws_partition.current.partition
  zenml_version = "0.12.0"

  artifact_bucket_name = "demo-artifact-store${data.aws_caller_identity.current.account_id}"

  common_tags = {
    managedBy   = "terraform"
    application = "demo"
