resource "aws_kms_key" "artifact_store" {
  description             = "Customer-managed key for ZenML artifact store SSE-KMS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "artifact_store" {
  name          = "alias/${local.artifact_bucket_name}"
  target_key_id = aws_kms_key.artifact_store.key_id
}

resource "aws_s3_bucket" "artifact_store" {
  bucket        = local.artifact_bucket_name
  force_destroy = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "artifact_store" {
  depends_on = [aws_s3_bucket_ownership_controls.artifact_store]

  bucket = aws_s3_bucket.artifact_store.id
  acl    = "private"
}

resource "aws_s3_bucket_public_access_block" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.artifact_store.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_ecr_repository" "zenml_kubernetes" {
  name                 = "zenml-kubernetes"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "local_file" "zenml_stack" {
  filename        = "${path.module}/zenml_stack.yaml"
  file_permission = "0644"

  content = <<-YAML
    # ZenML stack definition
    zenml_version: "${local.zenml_version}"

    artifact_store:
      name: demo-artifact-store
      flavor: s3
      type: s3
      config:
        path: "s3://${aws_s3_bucket.artifact_store.bucket}/zenml-artifacts"
        region: "${local.region}"

    container_registry:
      name: zenml-kubernetes
      flavor: aws
      type: aws
      config:
        uri: "${aws_ecr_repository.zenml_kubernetes.repository_url}"
        region: "${local.region}"

    secrets_manager:
      name: demo-secrets-manager
      flavor: aws
      type: aws
      config:
        region_name: "${local.region}"
  YAML
}

###############################################################################
# Locals
###############################################################################

locals {
  # Shared name prefix used to derive every resource name in this template.
  name_prefix = "nim"
}

###############################################################################
# Variables
###############################################################################

variable "container_registry_username" {
  description = "Username for the container registry credential stored in Secrets Manager."
  type        = string
  default     = "AWS"
}

variable "container_registry_password" {
  description = "Password for the container registry credential. Empty by default; supply a value at apply time."
  type        = string
  default     = ""
  sensitive   = true
}

###############################################################################
# Data Sources
###############################################################################

# Well-known AWS-managed policy: grants the permissions required by the ECS
# task execution role (pull images from ECR, write logs, etc.).
data "aws_iam_policy" "ecs_task_execution" {
  name = "AmazonECSTaskExecutionRolePolicy"
}

###############################################################################
# IAM Role for ECS Task Execution
###############################################################################

resource "aws_iam_role" "ecs_task_execution" {
  name_prefix = "${local.name_prefix}-ecs_task_execution-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-ecs_task_execution"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = data.aws_iam_policy.ecs_task_execution.arn
}

###############################################################################
# Secrets Manager Secret: Container Registry Credentials
###############################################################################

resource "aws_secretsmanager_secret" "repo_secret" {
  name_prefix             = "${local.name_prefix}-reposecret-"
  recovery_window_in_days = 0

  tags = {
    Name = "${local.name_prefix}-reposecret"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "repo_secret" {
  secret_id = aws_secretsmanager_secret.repo_secret.id

  secret_string = jsonencode({
    username = var.container_registry_username
    password = var.container_registry_password
  })
}

###############################################################################
# Inline Policy: Allow the task execution role to read only its secret
###############################################################################

resource "aws_iam_role_policy" "ecs_task_access_secrets" {
  name = "ECSTaskAccessSecretsPolicy"
  role = aws_iam_role.ecs_task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = aws_secretsmanager_secret.repo_secret.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# AWS Organization
#
# Creates a single AWS Organization with all features enabled and the
# AI services opt-out, backup, service control, and tag policy types enabled
# on the organization root.
# ---------------------------------------------------------------------------

resource "aws_organizations_organization" "this" {
  feature_set = "ALL"

  enabled_policy_types = [
    "AISERVICES_OPT_OUT_POLICY",
    "BACKUP_POLICY",
    "SERVICE_CONTROL_POLICY",
    "TAG_POLICY",
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Optional nested organizational unit hierarchy
#
# Callers supply a list of slash-delimited paths, e.g.
#   ["Sandbox", "Sandbox/TeamA", "Sandbox/TeamA/SubTeam"]
# The list defaults to empty, in which case no organizational units are
# created. Each path may define up to five levels of nesting.
# ---------------------------------------------------------------------------

variable "organizational_units" {
  description = "Optional list of slash-delimited organizational unit paths (for example Sandbox/TeamA/SubTeam). Supports up to five levels of nesting. Defaults to an empty list so no organizational units are created."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for path in var.organizational_units :
      length(trim(path, "/")) > 0 &&
      length(split("/", trim(path, "/"))) <= 5 &&
      alltrue([for segment in split("/", trim(path, "/")) : length(trimspace(segment)) > 0])
    ])
    error_message = "Each organizational unit path must be non-empty, be composed of non-empty slash-delimited segments, and contain at most five levels."
  }
}

locals {
  # Normalize the incoming paths by stripping stray leading/trailing slashes.
  ou_paths = [for path in var.organizational_units : trim(path, "/")]

  # Derive the unique set of OU paths that must exist at each nesting level.
  # Intermediate organizational units are created implicitly, even when only a
  # deeper leaf path is supplied.
  ou_level_1 = distinct([for path in local.ou_paths : split("/", path)[0]])

  ou_level_2 = distinct([
    for path in local.ou_paths : join("/", slice(split("/", path), 0, 2))
    if length(split("/", path)) >= 2
  ])

  ou_level_3 = distinct([
    for path in local.ou_paths : join("/", slice(split("/", path), 0, 3))
    if length(split("/", path)) >= 3
  ])

  ou_level_4 = distinct([
    for path in local.ou_paths : join("/", slice(split("/", path), 0, 4))
    if length(split("/", path)) >= 4
  ])

  ou_level_5 = distinct([
    for path in local.ou_paths : join("/", slice(split("/", path), 0, 5))
    if length(split("/", path)) >= 5
  ])

  organization_root_id = aws_organizations_organization.this.roots[0].id
}

resource "aws_organizations_organizational_unit" "level_1" {
  for_each = toset(local.ou_level_1)

  name      = each.value
  parent_id = local.organization_root_id
}

resource "aws_organizations_organizational_unit" "level_2" {
  for_each = toset(local.ou_level_2)

  name      = split("/", each.value)[1]
  parent_id = aws_organizations_organizational_unit.level_1[split("/", each.value)[0]].id
}

resource "aws_organizations_organizational_unit" "level_3" {
  for_each = toset(local.ou_level_3)

  name      = split("/", each.value)[2]
  parent_id = aws_organizations_organizational_unit.level_2[join("/", slice(split("/", each.value), 0, 2))].id
}

resource "aws_organizations_organizational_unit" "level_4" {
  for_each = toset(local.ou_level_4)

  name      = split("/", each.value)[3]
  parent_id = aws_organizations_organizational_unit.level_3[join("/", slice(split("/", each.value), 0, 3))].id
}

resource "aws_organizations_organizational_unit" "level_5" {
  for_each = toset(local.ou_level_5)

  name      = split("/", each.value)[4]
  parent_id = aws_organizations_organizational_unit.level_4[join("/", slice(split("/", each.value), 0, 4))].id
}

###############################################################################
# Availability Zones
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Local values
###############################################################################

locals {
  # First two availability zones in the current region
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  # One entry per environment; "octet" is the /16 prefix used for all subnets
  environments = {
    dev = {
      cidr  = "10.16.0.0/16"
      octet = "10.16"
    }
    rec = {
      cidr  = "10.32.0.0/16"
      octet = "10.32"
    }
  }

  # Tier -> AZ letter -> third octet
  # public:   a (first zone) = x.12.0/24, b (second zone) = x.11.0/24
  # internal: a (first zone) = x.1.0/24,  b (second zone) = x.2.0/24
  # external: a (first zone) = x.5.0/24,  b (second zone) = x.6.0/24
  subnet_tiers = {
    public   = { a = "12", b = "11" }
    internal = { a = "1", b = "2" }
    external = { a = "5", b = "6" }
  }

  # AZ letter -> availability zone index
  subnet_az_index = {
    a = 0
    b = 1
  }

  # Flattened map of every subnet: key = "<env>_<tier>_<az>"
  subnets = {
    for s in flatten([
      for env_key, env in local.environments : [
        for tier_key, zones in local.subnet_tiers : [
          for az_key, octet in zones : {
            key     = "${env_key}_${tier_key}_${az_key}"
            env     = env_key
            cidr    = "${env.octet}.${octet}.0/24"
            az_name = local.azs[local.subnet_az_index[az_key]]
          }
        ]
      ]
    ]) : s.key => s
  }
}

###############################################################################
# VPCs
###############################################################################

resource "aws_vpc" "this" {
  for_each = local.environments

  cidr_block                       = each.value.cidr
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "vpc_${each.key}"
  }
}

###############################################################################
# Subnets (6 per VPC)
###############################################################################

resource "aws_subnet" "this" {
  for_each = local.subnets

  vpc_id                  = aws_vpc.this[each.value.env].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az_name
  map_public_ip_on_launch = false

  tags = {
    Name = "subnet_${each.key}"
  }
}

###############################################################################
# Internet gateways
###############################################################################

resource "aws_internet_gateway" "this" {
  for_each = local.environments

  vpc_id = aws_vpc.this[each.key].id

  tags = {
    Name = "gatway_${each.key}"
  }
}

###############################################################################
# Default (main) route tables with IPv4 + IPv6 internet routes
###############################################################################

resource "aws_default_route_table" "this" {
  for_each = local.environments

  default_route_table_id = aws_vpc.this[each.key].default_route_table_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this[each.key].id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.this[each.key].id
  }

  tags = {
    Name = "rtb_main_${each.key}"
  }
}

###############################################################################
# Outputs
###############################################################################

output "vpc_dev_id" {
  description = "ID of the development VPC (vpc_dev)"
  value       = aws_vpc.this["dev"].id
}

output "vpc_rec_id" {
  description = "ID of the recette/staging VPC (vpc_rec)"
  value       = aws_vpc.this["rec"].id
}

###############################################################################
# Cloud Posse style label / naming conventions (emulated inline so the
# configuration stays fully self-contained with no external module dependency).
#
# Cloud Posse convention: <namespace>-<environment>-<stage>-<name>[-<attributes>]
# rendered lowercase and delimited by "-".
###############################################################################

locals {
  namespace   = "acme"
  environment = "use1"
  stage       = "prod"
  name        = "guardduty"
  delimiter   = "-"

  label_id = join(
    local.delimiter,
    compact([
      local.namespace,
      local.environment,
      local.stage,
      local.name,
    ]),
  )

  # Cloud Posse style standard tag set.
  tags = {
    Name        = local.label_id
    Namespace   = local.namespace
    Environment = local.environment
    Stage       = local.stage
    ManagedBy   = "Terraform"
  }

  # Both notification mechanisms are optional and disabled by default, so no
  # SNS topic, topic policy, or EventBridge rule/target is created implicitly.
  create_sns_topic    = var.enable_sns_notifications
  create_event_rules  = var.enable_eventbridge_rules && var.enable_sns_notifications
}

###############################################################################
# Variables
###############################################################################

variable "enable_sns_notifications" {
  description = "Create an SNS topic (and topic policy) used to notify on GuardDuty findings. Disabled by default."
  type        = bool
  default     = false
}

variable "enable_eventbridge_rules" {
  description = "Create EventBridge rules that forward GuardDuty findings to the SNS topic. Disabled by default."
  type        = bool
  default     = false
}

variable "enable_s3_protection" {
  description = "Enable the GuardDuty S3 protection data source. S3 protection is turned off by default."
  type        = bool
  default     = false
}

variable "finding_publishing_frequency" {
  description = "GuardDuty finding publication frequency. SIX_HOURS is the AWS service default."
  type        = string
  default     = "SIX_HOURS"

  validation {
    condition     = contains(["FIFTEEN_MINUTES", "ONE_HOUR", "SIX_HOURS"], var.finding_publishing_frequency)
    error_message = "finding_publishing_frequency must be one of FIFTEEN_MINUTES, ONE_HOUR, or SIX_HOURS."
  }
}

###############################################################################
# Data sources (static / local lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Amazon GuardDuty detector (account level, in the provider region: us-east-1)
###############################################################################

resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = var.finding_publishing_frequency
  tags                         = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# S3 protection explicitly turned off (disabled by default unless enabled).
resource "aws_guardduty_detector_feature" "s3_protection" {
  detector_id = aws_guardduty_detector.this.id
  name        = "S3_DATA_EVENTS"
  status      = var.enable_s3_protection ? "ENABLED" : "DISABLED"
}

###############################################################################
# Optional: SNS topic + topic policy for GuardDuty findings (disabled by default)
###############################################################################

resource "aws_sns_topic" "findings" {
  count             = local.create_sns_topic ? 1 : 0
  name              = "${local.label_id}-findings"
  kms_master_key_id = "alias/aws/sns"
  tags              = local.tags
}

data "aws_iam_policy_document" "findings" {
  count = local.create_sns_topic ? 1 : 0

  statement {
    sid    = "AllowEventBridgePublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.findings[count.index].arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "findings" {
  count  = local.create_sns_topic ? 1 : 0
  arn    = aws_sns_topic.findings[count.index].arn
  policy = data.aws_iam_policy_document.findings[count.index].json
}

###############################################################################
# Optional: EventBridge rules for GuardDuty findings (disabled by default)
###############################################################################

resource "aws_cloudwatch_event_rule" "findings" {
  count       = local.create_event_rules ? 1 : 0
  name        = "${local.label_id}-findings"
  description = "Forward Amazon GuardDuty findings to SNS"
  event_pattern = jsonencode({
    source        = ["aws.guardduty"]
    "detail-type" = ["GuardDuty Finding"]
  })
  tags = local.tags
}

resource "aws_cloudwatch_event_target" "findings" {
  count     = local.create_event_rules ? 1 : 0
  rule      = aws_cloudwatch_event_rule.findings[count.index].name
  target_id = "${local.label_id}-findings"
  arn       = aws_sns_topic.findings[count.index].arn
}

###############################################################################
# Outputs
###############################################################################

output "guardduty_detector_id" {
  description = "The ID of the GuardDuty detector."
  value       = aws_guardduty_detector.this.id
}

output "guardduty_findings_sns_topic_arn" {
  description = "ARN of the GuardDuty findings SNS topic, if notifications are enabled."
  value       = try(aws_sns_topic.findings[0].arn, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# Six-character lowercase alphanumeric suffix used to make every resource name unique.
resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  prefix     = "sudo-backup-${random_string.suffix.result}"
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# -----------------------------------------------------------------------------
# Customer-managed KMS key used to encrypt the backup vault
# -----------------------------------------------------------------------------
resource "aws_kms_key" "backup" {
  description             = "Customer managed KMS key for AWS Backup (${local.prefix})"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAwsBackupService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowBackupRoleUseOfKey"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.backup.arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]
  }
}

# -----------------------------------------------------------------------------
# Backup vault encrypted with the customer-managed KMS key
# -----------------------------------------------------------------------------
resource "aws_backup_vault" "backup" {
  name        = "${local.prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Backup plan with a single daily rule
# -----------------------------------------------------------------------------
resource "aws_backup_plan" "backup" {
  name = "${local.prefix}-backup-plan"

  rule {
    rule_name         = "${local.prefix}-backup-rule"
    target_vault_name = aws_backup_vault.backup.name
    schedule          = "cron(0 12 * * ? *)"

    # No transition or expiration configured (AWS Backup defaults apply).
    lifecycle {}

    recovery_point_tags = {
      Name = local.prefix
    }
  }
}

# -----------------------------------------------------------------------------
# IAM role assumed by AWS Backup
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "backup" {
  name               = "${local.prefix}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# -----------------------------------------------------------------------------
# Backup selection that targets resources tagged backup=true
# -----------------------------------------------------------------------------
resource "aws_backup_selection" "backup" {
  name         = "${local.prefix}-backup-selection"
  plan_id      = aws_backup_plan.backup.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup"
    value = "true"
  }
}

###############################################################################
# Amazon Cognito authentication for the "coop-tweets" application
#
# Creates:
#   - Cognito User Pool "coop-tweets" (admin-only user creation, strict password
#     policy, hosted UI domain "coop-tweets-domain")
#   - Cognito Identity Pool "coop tweets" (no unauthenticated identities)
#   - Two IAM roles (authenticated / unauthenticated) that trust only this
#     identity pool via Cognito federated identities
#   - Two customer-managed IAM policies (mobile analytics, Cognito Sync and
#     Cognito Identity actions) attached to the respective roles
###############################################################################

locals {
  app_name           = "coop-tweets"
  identity_pool_name = "coop tweets"
  domain_prefix      = "coop-tweets-domain"

  auth_role_name   = "coop-tweets_cognito_auth_role"
  unauth_role_name = "coop-tweets_cognito_unauth_role"

  auth_policy_name   = "cognito_kibana_auth_coop-tweets"
  unauth_policy_name = "cognito_kibana_unauth_coop-tweets"

  # Actions granted to Cognito authenticated/unauthenticated identities:
  # Amazon Mobile Analytics events, Cognito Sync and Cognito Identity actions.
  cognito_identity_actions = [
    "mobileanalytics:PutEvents",
    "cognito-sync:*",
    "cognito-identity:*",
  ]

  common_tags = {
    Application = "coop-tweets"
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# User Pool
###############################################################################

resource "aws_cognito_user_pool" "main" {
  name = local.app_name

  # Only administrators may create users.
  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  # Minimum 6 characters, must include numbers, uppercase letters and symbols.
  password_policy {
    minimum_length    = 6
    require_lowercase = false
    require_numbers   = true
    require_symbols   = true
    require_uppercase = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Hosted user pool domain with prefix "coop-tweets-domain".
resource "aws_cognito_user_pool_domain" "main" {
  domain       = local.domain_prefix
  user_pool_id = aws_cognito_user_pool.main.id
}

###############################################################################
# Identity Pool
###############################################################################

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = local.identity_pool_name
  allow_unauthenticated_identities = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM assume-role policies (trust Cognito federated identities for this pool only)
###############################################################################

data "aws_iam_policy_document" "cognito_auth_assume_role" {
  statement {
    sid     = "AllowCognitoAuthenticatedIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

data "aws_iam_policy_document" "cognito_unauth_assume_role" {
  statement {
    sid     = "AllowCognitoUnauthenticatedIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["unauthenticated"]
    }
  }
}

###############################################################################
# IAM roles
###############################################################################

resource "aws_iam_role" "cognito_auth" {
  name               = local.auth_role_name
  assume_role_policy = data.aws_iam_policy_document.cognito_auth_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role" "cognito_unauth" {
  name               = local.unauth_role_name
  assume_role_policy = data.aws_iam_policy_document.cognito_unauth_assume_role.json

  tags = local.common_tags
}

###############################################################################
# Customer-managed IAM policies
###############################################################################

data "aws_iam_policy_document" "cognito_auth" {
  statement {
    sid       = "CognitoAuthAccess"
    effect    = "Allow"
    actions   = local.cognito_identity_actions
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "cognito_unauth" {
  statement {
    sid       = "CognitoUnauthAccess"
    effect    = "Allow"
    actions   = local.cognito_identity_actions
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cognito_auth" {
  name        = local.auth_policy_name
  description = "Allows authenticated Cognito identities to use mobile analytics, Cognito Sync and Cognito Identity."
  policy      = data.aws_iam_policy_document.cognito_auth.json

  tags = local.common_tags
}

resource "aws_iam_policy" "cognito_unauth" {
  name        = local.unauth_policy_name
  description = "Allows unauthenticated Cognito identities to use mobile analytics, Cognito Sync and Cognito Identity."
  policy      = data.aws_iam_policy_document.cognito_unauth.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "cognito_auth" {
  role       = aws_iam_role.cognito_auth.name
  policy_arn = aws_iam_policy.cognito_auth.arn
}

resource "aws_iam_role_policy_attachment" "cognito_unauth" {
  role       = aws_iam_role.cognito_unauth.name
  policy_arn = aws_iam_policy.cognito_unauth.arn
}

###############################################################################
# Attach the roles to the identity pool
###############################################################################

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    "authenticated"   = aws_iam_role.cognito_auth.arn
    "unauthenticated" = aws_iam_role.cognito_unauth.arn
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "enable_findings_export" {
  description = "When true, GuardDuty findings are exported to an S3 bucket through a publishing destination. Disabled by default."
  type        = bool
  default     = false
}

variable "findings_export_bucket_name" {
  description = "Globally unique name for the GuardDuty findings export bucket. Defaults to a name derived from the account ID."
  type        = string
  default     = null
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  findings_export_bucket_name = coalesce(
    var.findings_export_bucket_name,
    "guardduty-findings-export-${local.account_id}"
  )

  common_tags = {
    Project   = "guardduty-findings"
    ManagedBy = "Terraform"
  }
}

###############################################################################
# Customer managed KMS key used by GuardDuty for findings export encryption
###############################################################################

resource "aws_kms_key" "guardduty" {
  description             = "Customer managed KMS key used by Amazon GuardDuty for encrypting findings exports"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  is_enabled              = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "guardduty-key-policy"
    Statement = [
      {
        Sid    = "EnableAccountFullAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowGuardDutyToGenerateDataKeys"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:Decrypt",
          "kms:DescribeKey",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "AllowS3ToUseKeyForFindingsExport"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt",
          "kms:DescribeKey",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.key_id
}

###############################################################################
# Amazon GuardDuty detector (one enabled detector per account/region)
###############################################################################

resource "aws_guardduty_detector" "guardduty" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  tags = local.common_tags
}

###############################################################################
# EventBridge rule matching GuardDuty Finding events
###############################################################################

resource "aws_cloudwatch_event_rule" "guardduty_finding_events" {
  name        = "guardduty-finding-events"
  description = "Matches Amazon GuardDuty Finding events"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })

  tags = local.common_tags
}

###############################################################################
# Optional: export GuardDuty findings to an S3 bucket (disabled by default)
###############################################################################

resource "aws_s3_bucket" "findings_export" {
  count = var.enable_findings_export ? 1 : 0

  bucket        = local.findings_export_bucket_name
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "findings_export" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings_export[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_export" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings_export[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.guardduty.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "findings_export" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings_export[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGuardDutyToWriteFindingsExport"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action   = ["s3:PutObject"]
        Resource = "${aws_s3_bucket.findings_export[0].arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "DenyInsecureTransport"
        Effect = "Deny"
        Principal = {
          AWS = "*"
        }
        Action   = ["s3:*"]
        Resource = [
          aws_s3_bucket.findings_export[0].arn,
          "${aws_s3_bucket.findings_export[0].arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.findings_export]
}

resource "aws_guardduty_publishing_destination" "findings_export" {
  count = var.enable_findings_export ? 1 : 0

  detector_id     = aws_guardduty_detector.guardduty.id
  destination_arn = aws_s3_bucket.findings_export[0].arn
  kms_key_arn     = aws_kms_key.guardduty.arn

  depends_on = [aws_s3_bucket_policy.findings_export]
}

locals {
  bucket_acl       = "private"
  sse_algorithm    = "aws:kms"
  object_ownership = "BucketOwnerPreferred"
}

# Customer managed key used for the bucket's default server-side encryption.
resource "aws_kms_key" "s3" {
  description             = "Customer managed key for S3 bucket default encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "s3" {
  name          = "alias/s3-default-encryption"
  target_key_id = aws_kms_key.s3.key_id
}

# Private S3 bucket with an auto-generated name. force_destroy allows the bucket
# to be torn down (including any objects it contains) without manual cleanup.
resource "aws_s3_bucket" "main" {
  force_destroy = true

  tags = {
    Name = "private-bucket"
  }
}

# All four public access block settings enabled.
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Versioning enabled with MFA delete disabled.
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

# Default server-side encryption using a customer managed KMS key with bucket keys enabled.
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = aws_kms_key.s3.arn
    }
    bucket_key_enabled = true
  }
}

# Object ownership set to "BucketOwnerPreferred" so ACLs remain usable on the bucket.
resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = local.object_ownership
  }
}

# Private canned ACL applied after the ownership controls are in place.
resource "aws_s3_bucket_acl" "main" {
  bucket = aws_s3_bucket.main.id
  acl    = local.bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

###############################################################################
# Billing console delegation: IAM roles, customer-managed policies and groups
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  billing_full_access_role_name   = "billing-full-access"
  billing_view_access_role_name   = "billing-view-access"
  billing_full_access_group_name  = "billing-full-access"
  billing_view_access_group_name  = "billing-view-access"
  billing_full_access_policy_name = "billing-full-access"
  billing_view_access_policy_name = "billing-view-access"

  billing_full_access_assume_role_policy_name = "billing-full-access-assume-role"
  billing_view_access_assume_role_policy_name = "billing-view-access-assume-role"
}

###############################################################################
# Trust policy: only principals of the current account, only with MFA present
###############################################################################

data "aws_iam_policy_document" "billing_assume_role_mfa" {
  statement {
    sid     = "AllowCurrentAccountPrincipalsWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "AWS"
      identifiers = [
        "arn:${local.partition}:iam::${local.account_id}:root",
      ]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

###############################################################################
# Customer-managed policy: full billing access
###############################################################################

data "aws_iam_policy_document" "billing_full_access" {
  statement {
    sid    = "BillingFullAccess"
    effect = "Allow"
    actions = [
      "aws-portal:*",
      "account:*",
      "budgets:*",
      "ce:*",
      "cur:*",
      "purchase-orders:*",
      "aws-marketplace:*",
      "savingsplans:*",
      "freetier:*",
      "pricing:*",
      "tax:*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_full_access" {
  name        = local.billing_full_access_policy_name
  description = "Full access to manage billing, usage, payment methods and budgets."
  policy      = data.aws_iam_policy_document.billing_full_access.json
}

###############################################################################
# Customer-managed policy: view-only billing access
###############################################################################

data "aws_iam_policy_document" "billing_view_access" {
  statement {
    sid    = "BillingViewAccess"
    effect = "Allow"
    actions = [
      "aws-portal:View*",
      "account:Get*",
      "account:List*",
      "budgets:ViewBudget",
      "budgets:Describe*",
      "ce:Describe*",
      "ce:Get*",
      "ce:List*",
      "cur:Describe*",
      "cur:Get*",
      "purchase-orders:View*",
      "purchase-orders:List*",
      "aws-marketplace:View*",
      "aws-marketplace:List*",
      "savingsplans:Describe*",
      "savingsplans:List*",
      "freetier:Get*",
      "pricing:Get*",
      "pricing:Describe*",
      "pricing:List*",
      "tax:Get*",
      "tax:List*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_view_access" {
  name        = local.billing_view_access_policy_name
  description = "View-only access to billing, usage, account, payment methods and budgets."
  policy      = data.aws_iam_policy_document.billing_view_access.json
}

###############################################################################
# IAM roles
###############################################################################

resource "aws_iam_role" "billing_full_access" {
  name               = local.billing_full_access_role_name
  description        = "Full billing access; assumable only by current-account principals with MFA."
  assume_role_policy = data.aws_iam_policy_document.billing_assume_role_mfa.json
}

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

resource "aws_iam_role" "billing_view_access" {
  name               = local.billing_view_access_role_name
  description        = "View-only billing access; assumable only by current-account principals with MFA."
  assume_role_policy = data.aws_iam_policy_document.billing_assume_role_mfa.json
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

###############################################################################
# Assume-role policies for groups
###############################################################################

data "aws_iam_policy_document" "billing_full_access_assume_role" {
  statement {
    sid       = "AssumeBillingFullAccessRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_full_access.arn]
  }
}

resource "aws_iam_policy" "billing_full_access_assume_role" {
  name        = local.billing_full_access_assume_role_policy_name
  description = "Allows group members to assume the billing-full-access role."
  policy      = data.aws_iam_policy_document.billing_full_access_assume_role.json
}

data "aws_iam_policy_document" "billing_view_access_assume_role" {
  statement {
    sid       = "AssumeBillingViewAccessRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_view_access.arn]
  }
}

resource "aws_iam_policy" "billing_view_access_assume_role" {
  name        = local.billing_view_access_assume_role_policy_name
  description = "Allows group members to assume the billing-view-access role."
  policy      = data.aws_iam_policy_document.billing_view_access_assume_role.json
}

###############################################################################
# IAM groups
###############################################################################

resource "aws_iam_group" "billing_full_access" {
  name = local.billing_full_access_group_name
  path = "/"
}

resource "aws_iam_group_policy_attachment" "billing_full_access_assume_role" {
  group      = aws_iam_group.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access_assume_role.arn
}

resource "aws_iam_group" "billing_view_access" {
  name = local.billing_view_access_group_name
  path = "/"
}

resource "aws_iam_group_policy_attachment" "billing_view_access_assume_role" {
  group      = aws_iam_group.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access_assume_role.arn
}

###############################################################################
# Optional group memberships (empty by default -> no memberships created)
###############################################################################

variable "billing_full_access_group_users" {
  description = "IAM user names to add to the billing-full-access group. Empty by default."
  type        = list(string)
  default     = []
}

variable "billing_view_access_group_users" {
  description = "IAM user names to add to the billing-view-access group. Empty by default."
  type        = list(string)
  default     = []
}

resource "aws_iam_group_membership" "billing_full_access" {
  count = length(var.billing_full_access_group_users) > 0 ? 1 : 0
  name  = local.billing_full_access_group_name
  group = aws_iam_group.billing_full_access.name
  users = var.billing_full_access_group_users
}

resource "aws_iam_group_membership" "billing_view_access" {
  count = length(var.billing_view_access_group_users) > 0 ? 1 : 0
  name  = local.billing_view_access_group_name
  group = aws_iam_group.billing_view_access.name
  users = var.billing_view_access_group_users
}

###############################################################################
# Outputs
###############################################################################

output "billing_full_access_role_arn" {
  description = "ARN of the billing-full-access IAM role."
  value       = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  description = "ARN of the billing-view-access IAM role."
  value       = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  description = "ARN of the billing-full-access IAM group."
  value       = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  description = "ARN of the billing-view-access IAM group."
  value       = aws_iam_group.billing_view_access.arn
}

###############################################################################
# Helper lookups for the current partition, region, and account.
# These are pure provider metadata lookups (no pre-existing remote state) and
# feed the ARNs used throughout the configuration.
###############################################################################

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Random naming / identifiers
###############################################################################

# Base name: "cognito" + random pet-name suffix (e.g. cognito-happy-otter).
resource "random_pet" "name" {
  prefix = "cognito"
  length = 2
}

# Random 16-character uppercase external ID used by the Cognito SMS role.
resource "random_string" "external_id" {
  length  = 16
  upper   = true
  lower   = false
  numeric = false
  special = false
}

locals {
  # Helper values derived from the current partition, region, and account.
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.region
  account_id = data.aws_caller_identity.current.account_id

  # All resources are named from the base name suffix.
  base_name = random_pet.name.id
  pool_name = replace(local.base_name, "-", "_")

  external_id = random_string.external_id.result

  tags = {
    Name      = local.base_name
    ManagedBy = "Terraform"
  }
}

###############################################################################
# Cognito user pool
###############################################################################

resource "aws_cognito_user_pool" "main" {
  name = local.pool_name

  # MFA turned off.
  mfa_configuration = "OFF"

  # Email is auto-verified.
  auto_verified_attributes = ["email"]

  # SMS sending is delegated to an IAM role Cognito can assume.
  sms_configuration {
    external_id    = local.external_id
    sns_caller_arn = aws_iam_role.sms.arn
  }

  # Required, immutable email attribute.
  schema {
    name                     = "email"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = false
    required                 = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  # Optional, immutable phone number attribute.
  schema {
    name                     = "phone_number"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = false
    required                 = false

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  # Mutable custom profile attributes.
  schema {
    name                     = "custom:profile_id"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  schema {
    name                     = "custom:email"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  schema {
    name                     = "custom:first_name"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  schema {
    name                     = "custom:last_name"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  schema {
    name                     = "custom:gender"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  schema {
    name                     = "custom:age"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  schema {
    name                     = "custom:persona"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }

  # Cognito validates the SMS caller role's SNS policy during pool creation,
  # so the inline policy must exist first.
  depends_on = [
    aws_iam_role_policy.sms
  ]
}

###############################################################################
# App client (no client secret)
###############################################################################

resource "aws_cognito_user_pool_client" "main" {
  name            = "${local.base_name}-app-client"
  user_pool_id    = aws_cognito_user_pool.main.id
  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM role Cognito assumes to send SMS through SNS
###############################################################################

resource "aws_iam_role" "sms" {
  name = "${local.base_name}-sms"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cognito-idp.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = local.external_id
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "sms" {
  name = "${local.base_name}-sms-publish"
  role = aws_iam_role.sms.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sns:Publish"
        ]
        Resource = [
          "*"
        ]
      }
    ]
  })
}

###############################################################################
# Cognito identity pool
###############################################################################

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = local.pool_name
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.main.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  identity_pool_arn  = "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
  identity_sync_arn  = "arn:${local.partition}:cognito-sync:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
}

###############################################################################
# Roles attached to the identity pool
###############################################################################

# Authenticated (signed-in) users role.
resource "aws_iam_role" "authenticated" {
  name = "${local.base_name}-signed-users"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })

  tags = local.tags
}

# Unauthenticated (anonymous) users role.
resource "aws_iam_role" "unauthenticated" {
  name = "${local.base_name}-anonymous-users"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "unauthenticated"
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    "authenticated"   = aws_iam_role.authenticated.arn
    "unauthenticated" = aws_iam_role.unauthenticated.arn
  }
}

###############################################################################
# Policies for the identity pool roles
###############################################################################

# Authenticated role: Cognito Identity + Cognito Sync scoped to this pool.
resource "aws_iam_role_policy" "authenticated" {
  name = "${local.base_name}-signed-users-policy"
  role = aws_iam_role.authenticated.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-identity:GetId",
          "cognito-identity:GetCredentialsForIdentity",
          "cognito-identity:GetOpenIdToken",
          "cognito-identity:GetOpenIdTokenForDeveloperIdentity",
          "cognito-identity:DescribeIdentity",
          "cognito-identity:ListIdentities",
          "cognito-identity:ListIdentityPools",
          "cognito-identity:LookupDeveloperIdentity",
          "cognito-identity:MergeDeveloperIdentities",
          "cognito-identity:UnlinkDeveloperIdentity",
          "cognito-identity:UnlinkIdentity",
          "cognito-identity:DeleteIdentities"
        ]
        Resource = [
          local.identity_pool_arn
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "cognito-sync:DescribeDataset",
          "cognito-sync:DescribeIdentityPoolUsage",
          "cognito-sync:DescribeIdentityUsage",
          "cognito-sync:GetBulkPublishDetails",
          "cognito-sync:GetCognitoEvents",
          "cognito-sync:GetIdentityPoolConfiguration",
          "cognito-sync:ListDatasets",
          "cognito-sync:ListIdentityPoolUsage",
          "cognito-sync:ListRecords",
          "cognito-sync:SubscribeToDataset",
          "cognito-sync:UnsubscribeFromDataset",
          "cognito-sync:UpdateRecords",
          "cognito-sync:RegisterDevice",
          "cognito-sync:DeleteDataset"
        ]
        Resource = [
          local.identity_sync_arn,
          "${local.identity_sync_arn}/*"
        ]
      }
    ]
  })
}

# Unauthenticated role: Cognito Identity permissions only, scoped to this pool.
resource "aws_iam_role_policy" "unauthenticated" {
  name = "${local.base_name}-anonymous-users-policy"
  role = aws_iam_role.unauthenticated.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-identity:GetId",
          "cognito-identity:GetCredentialsForIdentity",
          "cognito-identity:GetOpenIdToken",
          "cognito-identity:DescribeIdentity",
          "cognito-identity:UnlinkIdentity"
        ]
        Resource = [
          local.identity_pool_arn
        ]
      }
    ]
  })
}

###############################################################################
# Data sources (static / well-known lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

# AWS-managed Amazon Linux 2023 ECS-optimized AMI (well-known public image).
data "aws_ami" "ecs_optimized_al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-ecs-hvm-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

###############################################################################
# Local values
###############################################################################

locals {
  # Every resource is named after the Terraform workspace plus a "-batch" suffix.
  name_prefix = "${terraform.workspace}-batch"

  account_id  = data.aws_caller_identity.current.account_id
  bucket_name = "benchmark-batch-results-${data.aws_caller_identity.current.account_id}"

  # Second availability zone of the region.
  second_az = data.aws_availability_zones.available.names[1]

  common_tags = {
    Workspace = terraform.workspace
    ManagedBy = "Terraform"
    Project   = "batch"
  }
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = local.second_az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-subnet" })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = local.second_az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-subnet" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-eip" })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "batch_compute" {
  name        = "${local.name_prefix}-compute-sg"
  description = "Security group for the ${local.name_prefix} AWS Batch compute environment"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "HTTPS to the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-compute-sg" })
}

###############################################################################
# KMS key for the results bucket
###############################################################################

resource "aws_kms_key" "results" {
  description             = "Customer-managed key for the ${local.bucket_name} results bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-results-key" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Results S3 bucket
###############################################################################

resource "aws_s3_bucket" "results" {
  bucket = local.bucket_name

  tags = merge(local.common_tags, { Name = local.bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.results.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

###############################################################################
# IAM - ECS instance role / instance profile
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_instance" {
  name               = "${local.name_prefix}-ecs-instance-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-ecs-instance-role" })
}

resource "aws_iam_instance_profile" "ecs_instance" {
  name = "${local.name_prefix}-ecs-instance-profile"
  role = aws_iam_role.ecs_instance.name

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-ecs-instance-profile" })
}

resource "aws_iam_role_policy_attachment" "ecs_instance_ecs_policy" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

###############################################################################
# IAM - custom ECS/S3 policy
###############################################################################

data "aws_iam_policy_document" "ecs_s3_policy" {
  statement {
    sid    = "S3ReadListGeneral"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:ListAllMyBuckets",
      "s3:GetBucketLocation",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "S3ReadWriteDeleteResultsBucket"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.results.arn,
      "${aws_s3_bucket.results.arn}/*",
    ]
  }

  statement {
    sid    = "KMSDecryptGenerateDataKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.results.arn]
  }
}

resource "aws_iam_policy" "ecs_s3_policy" {
  name        = "ecs_s3_policy"
  description = "Read/list on S3, read/write/delete on the results bucket, and KMS decrypt/generate-data-key on its key"
  policy      = data.aws_iam_policy_document.ecs_s3_policy.json

  tags = merge(local.common_tags, { Name = "ecs_s3_policy" })
}

resource "aws_iam_role_policy_attachment" "ecs_instance_s3_policy" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = aws_iam_policy.ecs_s3_policy.arn
}

###############################################################################
# IAM - Batch service role
###############################################################################

data "aws_iam_policy_document" "batch_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["batch.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "batch_service" {
  name               = "${local.name_prefix}-batch-service-role"
  assume_role_policy = data.aws_iam_policy_document.batch_assume_role.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-batch-service-role" })
}

resource "aws_iam_role_policy_attachment" "batch_service_policy" {
  role       = aws_iam_role.batch_service.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBatchServiceRole"
}

###############################################################################
# AWS Batch compute environment
###############################################################################

resource "aws_batch_compute_environment" "this" {
  name         = "${local.name_prefix}-compute-env"
  type         = "MANAGED"
  state        = "ENABLED"
  service_role = aws_iam_role.batch_service.arn

  compute_resources {
    type                = "EC2"
    allocation_strategy = "BEST_FIT"
    min_vcpus           = 0
    max_vcpus           = 4
    instance_type       = ["optimal"]
    image_id            = data.aws_ami.ecs_optimized_al2023.id

    subnets            = [aws_subnet.private.id]
    security_group_ids = [aws_security_group.batch_compute.id]
    instance_role      = aws_iam_instance_profile.ecs_instance.arn
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-compute-env" })

  depends_on = [
    aws_iam_role_policy_attachment.batch_service_policy,
    aws_iam_role_policy_attachment.ecs_instance_ecs_policy,
    aws_iam_role_policy_attachment.ecs_instance_s3_policy,
  ]
}

###############################################################################
# AWS Batch job queue
###############################################################################

resource "aws_batch_job_queue" "this" {
  name     = "${local.name_prefix}-queue"
  state    = "ENABLED"
  priority = 1

  compute_environment_order {
    order               = 1
    compute_environment = aws_batch_compute_environment.this.arn
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-queue" })
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  region      = data.aws_region.current.name
  partition   = data.aws_partition.current.partition
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"

  # AWS-managed KMS key used by S3 for server-side encryption.
  s3_kms_key_arn = "arn:${local.partition}:kms:${local.region}:${local.account_id}:alias/aws/s3"
}

resource "aws_kms_key" "endpoint_backup" {
  description             = "Customer managed key for endpoint-backup S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "endpoint-backup"
  }
}

resource "aws_kms_alias" "endpoint_backup" {
  name          = "alias/endpoint-backup"
  target_key_id = aws_kms_key.endpoint_backup.key_id
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = local.bucket_name

  # Transfer acceleration is suspended (default) and object lock is disabled.
  object_lock_enabled = false

  tags = {
    Name        = local.bucket_name
    Description = "Secure backup bucket for endpoint backups"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
    }

    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "endpoint_backup" {
  statement {
    sid    = "DenyInsecureConnections"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyComplianceModeRetentionGreaterThan90Days"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
    ]

    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }

    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup.json
}

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"
  path = "/"

  tags = {
    Name = "endpoint-backup"
  }
}

data "aws_iam_policy_document" "endpoint_backup_bucket_read_write_access" {
  statement {
    sid    = "ListBucket"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:ListBucketMultipartUploads",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
    ]

    resources = [aws_s3_bucket.endpoint_backup.arn]
  }

  statement {
    sid    = "ReadWriteDeleteObject"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectAttributes",
      "s3:GetObjectVersionAttributes",
      "s3:GetObjectTagging",
      "s3:GetObjectVersionTagging",
      "s3:PutObject",
      "s3:PutObjectTagging",
      "s3:PutObjectVersionTagging",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:DeleteObjectTagging",
    ]

    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
  }

  statement {
    sid    = "ObjectRetentionAndRestore"
    effect = "Allow"

    actions = [
      "s3:GetObjectRetention",
      "s3:PutObjectRetention",
      "s3:GetObjectLegalHold",
      "s3:PutObjectLegalHold",
      "s3:RestoreObject",
    ]

    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
  }

  statement {
    sid    = "S3KmsDecryptAndDataKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [
      aws_kms_key.endpoint_backup.arn,
      local.s3_kms_key_arn,
    ]
  }
}

resource "aws_iam_policy" "endpoint_backup_bucket_read_write_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "List, read, write, delete, version, retention, and restore access to the endpoint-backup bucket, plus decrypt/data-key access on the AWS-managed S3 KMS key."
  policy      = data.aws_iam_policy_document.endpoint_backup_bucket_read_write_access.json

  tags = {
    Name = "endpoint-backup-bucket-read-write-access"
  }
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_read_write_access.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "app_name" {
  description = "Name of the application this VPC belongs to."
  type        = string
  default     = "terraform"
}

variable "environment" {
  description = "Deployment environment (e.g. testing, staging, production)."
  type        = string
  default     = "testing"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "IPv4 CIDR blocks for the public subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_subnet_cidrs" {
  description = "IPv4 CIDR blocks for the private subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.22.0/24", "10.0.33.0/24"]
}

variable "enable_dns_hostnames" {
  description = "Whether to enable DNS hostnames for the VPC. Disabled by default."
  type        = bool
  default     = false
}

variable "enable_ipv6" {
  description = "Whether to associate an IPv6 CIDR block with the VPC. Disabled by default."
  type        = bool
  default     = false
}

variable "enable_transit_gateway_attachment" {
  description = "Whether to create a transit gateway and attach the VPC to it. Disabled by default."
  type        = bool
  default     = false
}

variable "enable_ipv6_egress_routing" {
  description = "Whether to route private subnet IPv6 traffic through an egress-only internet gateway. Disabled by default."
  type        = bool
  default     = false
}

###############################################################################
# Data sources
###############################################################################

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_name             = "vpc-${var.app_name}-${var.environment}"
  db_subnet_group_name = "db-subnet-${var.app_name}-${var.environment}"

  # Use one availability zone per subnet, spread across the region.
  azs = slice(data.aws_availability_zones.available.names, 0, length(var.public_subnet_cidrs))

  common_tags = {
    App         = var.app_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = var.enable_ipv6

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-default-sg"
  })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  ipv6_cidr_block = var.enable_ipv6 ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index) : null

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  ipv6_cidr_block = var.enable_ipv6 ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + length(var.public_subnet_cidrs)) : null

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

###############################################################################
# Internet gateway and public routing
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# NAT gateway and shared private routing
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Optional IPv6 egress routing (disabled by default)
###############################################################################

resource "aws_egress_only_internet_gateway" "main" {
  count = var.enable_ipv6 && var.enable_ipv6_egress_routing ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-eigw"
  })
}

resource "aws_route" "private_ipv6_egress" {
  count = var.enable_ipv6 && var.enable_ipv6_egress_routing ? 1 : 0

  route_table_id              = aws_route_table.private.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main[0].id
}

###############################################################################
# Optional transit gateway attachment (disabled by default)
###############################################################################

resource "aws_ec2_transit_gateway" "main" {
  count = var.enable_transit_gateway_attachment ? 1 : 0

  description = "Transit gateway for ${local.vpc_name}"
  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-tgw"
  })
}

resource "aws_ec2_transit_gateway_vpc_attachment" "main" {
  count = var.enable_transit_gateway_attachment ? 1 : 0

  subnet_ids         = aws_subnet.private[*].id
  transit_gateway_id = aws_ec2_transit_gateway.main[0].id
  vpc_id             = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-tgw-attachment"
  })
}

###############################################################################
# DB subnet group
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = local.db_subnet_group_name
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = local.db_subnet_group_name
  })
}

###############################################################################
# Outputs
###############################################################################

output "region" {
  description = "AWS region the VPC is deployed in."
  value       = data.aws_region.current.name
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_arn" {
  description = "ARN of the VPC."
  value       = aws_vpc.main.arn
}

output "vpc_cidr_block" {
  description = "IPv4 CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "IPv6 CIDR block of the VPC (empty when IPv6 is disabled)."
  value       = aws_vpc.main.ipv6_cidr_block
}

output "availability_zones" {
  description = "Availability zones the subnets are spread across."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "public_subnet_cidr_blocks" {
  description = "IPv4 CIDR blocks of the public subnets."
  value       = aws_subnet.public[*].cidr_block
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "private_subnet_cidr_blocks" {
  description = "IPv4 CIDR blocks of the private subnets."
  value       = aws_subnet.private[*].cidr_block
}

output "default_security_group_id" {
  description = "ID of the VPC default security group."
  value       = aws_default_security_group.default.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the shared private route table."
  value       = aws_route_table.private.id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway."
  value       = aws_nat_gateway.main.id
}

output "nat_gateway_public_ip" {
  description = "Public (Elastic) IP address of the NAT gateway."
  value       = aws_eip.nat.public_ip
}

output "nat_gateway_private_ip" {
  description = "Private IP address of the NAT gateway."
  value       = aws_nat_gateway.main.private_ip
}

output "nat_gateway_subnet_id" {
  description = "Subnet the NAT gateway is deployed in."
  value       = aws_nat_gateway.main.subnet_id
}

output "db_subnet_group_name" {
  description = "Name of the DB subnet group."
  value       = aws_db_subnet_group.main.name
}

output "db_subnet_group_id" {
  description = "ID of the DB subnet group."
  value       = aws_db_subnet_group.main.id
}

output "transit_gateway_id" {
  description = "ID of the transit gateway (empty when disabled)."
  value       = var.enable_transit_gateway_attachment ? aws_ec2_transit_gateway.main[0].id : null
}

output "transit_gateway_attachment_id" {
  description = "ID of the transit gateway VPC attachment (empty when disabled)."
  value       = var.enable_transit_gateway_attachment ? aws_ec2_transit_gateway_vpc_attachment.main[0].id : null
}

output "ipv6_egress_only_internet_gateway_id" {
  description = "ID of the egress-only internet gateway (empty when disabled)."
  value       = var.enable_ipv6 && var.enable_ipv6_egress_routing ? aws_egress_only_internet_gateway.main[0].id : null
}

# -----------------------------------------------------------------------------
# Argo CD GitOps bridge - CodeCommit repositories, SSH access and IAM
# -----------------------------------------------------------------------------

locals {
  gitops_user_name = "gitops-bridge-gitops"
  ssh_key_filename = "gitops_ssh.pem"
}

# -----------------------------------------------------------------------------
# SSH key pair used to authenticate to CodeCommit (4096-bit RSA)
# -----------------------------------------------------------------------------

resource "tls_private_key" "gitops" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# -----------------------------------------------------------------------------
# CodeCommit repositories
# -----------------------------------------------------------------------------

resource "aws_codecommit_repository" "apps" {
  repository_name = "gitops-apps"
  description     = "Argo CD GitOps bridge - applications repository"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_codecommit_repository" "platform" {
  repository_name = "gitops-platform"
  description     = "Argo CD GitOps bridge - platform repository"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_codecommit_repository" "addons" {
  repository_name = "gitops-addons"
  description     = "Argo CD GitOps bridge - addons repository"

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# IAM user that authenticates over SSH and its uploaded public key
# -----------------------------------------------------------------------------

resource "aws_iam_user" "gitops" {
  name = local.gitops_user_name
  path = "/"
}

resource "aws_iam_user_ssh_key" "gitops" {
  username   = aws_iam_user.gitops.name
  encoding   = "SSH"
  public_key = trimspace(tls_private_key.gitops.public_key_openssh)
}

# -----------------------------------------------------------------------------
# Customer managed IAM policy granting Git pull/push to only these repositories
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "codecommit_gitops" {
  statement {
    sid    = "CodeCommitGitPullPush"
    effect = "Allow"

    actions = [
      "codecommit:GitPull",
      "codecommit:GitPush",
    ]

    resources = [
      aws_codecommit_repository.apps.arn,
      aws_codecommit_repository.platform.arn,
      aws_codecommit_repository.addons.arn,
    ]
  }
}

resource "aws_iam_policy" "codecommit_gitops" {
  name        = local.gitops_user_name
  description = "Git pull and push access to the Argo CD GitOps bridge CodeCommit repositories"
  policy      = data.aws_iam_policy_document.codecommit_gitops.json
}

resource "aws_iam_user_policy_attachment" "codecommit_gitops" {
  user       = aws_iam_user.gitops.name
  policy_arn = aws_iam_policy.codecommit_gitops.arn
}

# -----------------------------------------------------------------------------
# Random suffix and Secrets Manager secret holding the generated private key
# -----------------------------------------------------------------------------

resource "random_string" "secret_suffix" {
  length  = 5
  upper   = false
  special = false
}

resource "aws_secretsmanager_secret" "codecommit_key" {
  name        = "codecommit-key-${random_string.secret_suffix.result}"
  description = "SSH private key for the ${local.gitops_user_name} CodeCommit user"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "codecommit_key" {
  secret_id     = aws_secretsmanager_secret.codecommit_key.id
  secret_string = tls_private_key.gitops.private_key_pem
}

# -----------------------------------------------------------------------------
# Write the private key locally into the user's SSH directory
# -----------------------------------------------------------------------------

resource "local_file" "gitops_ssh_key" {
  content         = tls_private_key.gitops.private_key_pem
  filename        = pathexpand("~/.ssh/${local.ssh_key_filename}")
  file_permission = "0600"
}

# -----------------------------------------------------------------------------
# Matching SSH config entry for the CodeCommit Git endpoints
# -----------------------------------------------------------------------------

resource "local_file" "ssh_config" {
  content = <<-EOT
    Host git-codecommit.*.amazonaws.com
      User ${aws_iam_user_ssh_key.gitops.ssh_public_key_id}
      IdentityFile ~/.ssh/${local.ssh_key_filename}
  EOT

  filename        = pathexpand("~/.ssh/config")
  file_permission = "0600"
}

###############################################################################
# Reusable single EC2 instance "module"
#
# With its DEFAULT settings this configuration provisions a complete,
# self-contained network (VPC + public subnet + IGW + route table), a hardened
# EC2 instance, an SSH key pair, an Elastic IP, an IAM role/instance profile,
# a locked-down security group and a CloudWatch auto-reboot alarm.
#
# Optional extra EBS volumes and additional network interfaces (with Elastic
# IPs) are supported but NOT created by default.
###############################################################################

###############################################################################
# Variables (module inputs)
###############################################################################

variable "vpc_cidr" {
  description = "CIDR block for the VPC created by this module."
  type        = string
  default     = "10.70.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the single public subnet."
  type        = string
  default     = "10.70.0.0/24"
}

variable "instance_name" {
  description = "Name tag of the EC2 instance."
  type        = string
  default     = "benchmark-instance"
}

variable "instance_type" {
  description = "EC2 instance type."
  type        = string
  default     = "t2.micro"
}

variable "key_name" {
  description = "Name of the SSH key pair to create."
  type        = string
  default     = "benchmark-d8bc612be4e0-key"
}

variable "public_key" {
  description = "SSH public key material to import into the created key pair."
  type        = string
  default     = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAABAgMEBQYHCAkKCwwNDg8QERITFBUWFxgZGhscHR4f benchmark"
}

variable "root_volume_size" {
  description = "Size (GiB) of the encrypted root EBS volume."
  type        = number
  default     = 10
}

variable "root_volume_type" {
  description = "EBS volume type of the root volume."
  type        = string
  default     = "gp2"
}

variable "extra_ebs_volumes" {
  description = "Optional additional EBS volumes keyed by device name (e.g. /dev/sdf). Empty by default."
  type = map(object({
    size      = number
    type      = string
    encrypted = bool
  }))
  default = {}
}

variable "extra_network_interfaces" {
  description = "Optional additional network interfaces keyed by a logical name. Empty by default."
  type = map(object({
    device_index       = number
    subnet_id          = string
    private_ip         = string
    security_group_ids = list(string)
    associate_eip      = bool
  }))
  default = {}
}

###############################################################################
# Provider / account metadata (static lookups only)
###############################################################################

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_kms_key" "ebs" {
  description             = "Customer managed key for EBS volume encryption (${var.instance_name})"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "${var.instance_name}-ebs-key"
  }
}

resource "aws_kms_alias" "ebs" {
  name          = "alias/${var.instance_name}-ebs"
  target_key_id = aws_kms_key.ebs.key_id
}

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"] # Canonical

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.instance_name}-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.instance_name}-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.instance_name}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.instance_name}-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# SSH key pair
###############################################################################

resource "aws_key_pair" "instance" {
  key_name   = var.key_name
  public_key = var.public_key

  tags = {
    Name = var.key_name
  }
}

###############################################################################
# Security group - egress only to the VPC CIDR, no ingress by default
###############################################################################

resource "aws_security_group" "instance" {
  name        = "${var.instance_name}-sg"
  description = "Allow egress only to the VPC CIDR block; no ingress."
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Egress to the VPC CIDR block only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.instance_name}-sg"
  }
}

###############################################################################
# IAM role + instance profile assumable by EC2 (least privilege, no inline
# policies / wildcards).
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "instance" {
  name               = "${var.instance_name}-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name = "${var.instance_name}-role"
  }
}

resource "aws_iam_instance_profile" "instance" {
  name = "${var.instance_name}-profile"
  role = aws_iam_role.instance.name

  tags = {
    Name = "${var.instance_name}-profile"
  }
}

###############################################################################
# EC2 instance
###############################################################################

resource "aws_instance" "main" {
  ami                         = data.aws_ami.ubuntu.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.main.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  key_name                    = aws_key_pair.instance.key_name
  monitoring                  = true
  associate_public_ip_address = true
  iam_instance_profile        = aws_iam_instance_profile.instance.name

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required" # IMDSv2 required
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size           = var.root_volume_size
    volume_type           = var.root_volume_type
    encrypted             = true
    kms_key_id            = aws_kms_key.ebs.arn
    delete_on_termination = true
  }

  tags = {
    Name = var.instance_name
  }
}

###############################################################################
# Elastic IP attached to the instance
###############################################################################

resource "aws_eip" "main" {
  domain   = "vpc"
  instance = aws_instance.main.id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.instance_name}-eip"
  }
}

###############################################################################
# CloudWatch alarm - reboot the instance on repeated instance status failures
###############################################################################

resource "aws_cloudwatch_metric_alarm" "status_check_failed_instance" {
  alarm_name          = "${var.instance_name}-status-check-failed-instance"
  alarm_description   = "Reboot ${var.instance_name} when StatusCheckFailed_Instance is >= 1 for 5 consecutive 60s periods."
  namespace           = "AWS/EC2"
  metric_name         = "StatusCheckFailed_Instance"
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 5
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"

  dimensions = {
    InstanceId = aws_instance.main.id
  }

  alarm_actions = [
    "arn:${data.aws_partition.current.partition}:automate:${data.aws_region.current.region}:ec2:reboot"
  ]

  tags = {
    Name = "${var.instance_name}-status-check-failed-instance"
  }
}

###############################################################################
# Optional additions (not created by default)
###############################################################################

resource "aws_ebs_volume" "extra" {
  for_each = var.extra_ebs_volumes

  availability_zone = aws_subnet.main.availability_zone
  size              = each.value.size
  type              = each.value.type
  encrypted         = each.value.encrypted

  tags = {
    Name = "${var.instance_name}-ebs-${each.key}"
  }
}

resource "aws_volume_attachment" "extra" {
  for_each = aws_ebs_volume.extra

  device_name = each.key
  volume_id   = each.value.id
  instance_id = aws_instance.main.id
}

resource "aws_network_interface" "extra" {
  for_each = var.extra_network_interfaces

  subnet_id       = each.value.subnet_id
  private_ips     = [each.value.private_ip]
  security_groups = each.value.security_group_ids

  tags = {
    Name = "${var.instance_name}-eni-${each.key}"
  }
}

resource "aws_network_interface_attachment" "extra" {
  for_each = aws_network_interface.extra

  instance_id          = aws_instance.main.id
  network_interface_id = each.value.id
  device_index         = var.extra_network_interfaces[each.key].device_index
}

resource "aws_eip" "extra" {
  for_each = {
    for k, v in var.extra_network_interfaces : k => v if v.associate_eip
  }

  domain            = "vpc"
  network_interface = aws_network_interface.extra[each.key].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.instance_name}-eip-${each.key}"
  }
}

###############################################################################
# Cross-region S3 replication for Env = "dev" log buckets
#
# Topology (four regions):
#   source region 1  (us-east-1)      : log1a.veerum-<acct>, log1b.veerum-<acct>
#   source region 2  (us-west-2)      : log2a.veerum-<acct>, log2b.veerum-<acct>
#   replica region 1 (eu-west-1)      : <source>-replica1-<acct>   (x4)
#   replica region 2 (ap-southeast-1) : <source>-replica2-<acct>   (x4)
#
# Every bucket is private, versioned, has all public access blocked and uses
# default SSE-KMS encryption with a customer-managed key created in the same
# region. Each source bucket carries two enabled replication rules (one per
# replica region) that copy all objects - including SSE-KMS encrypted ones -
# in the STANDARD storage class, re-encrypting with that region's replica key.
###############################################################################

###############################################################################
# Provider configuration - one alias per region
###############################################################################

provider "aws" {
  alias  = "source1"
  region = "us-east-1"
}

provider "aws" {
  alias  = "source2"
  region = "us-west-2"
}

provider "aws" {
  alias  = "replica1"
  region = "eu-west-1"
}

provider "aws" {
  alias  = "replica2"
  region = "ap-southeast-1"
}

###############################################################################
# Context
###############################################################################

data "aws_caller_identity" "current" {
  provider = aws.source1
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  env        = "dev"

  # Base (account-suffixed) names of the four source buckets.
  source1_buckets = {
    log1a = "log1a.veerum"
    log1b = "log1b.veerum"
  }

  source2_buckets = {
    log2a = "log2a.veerum"
    log2b = "log2b.veerum"
  }

  # Every source bucket, keyed so the matching replica bucket can be looked up
  # in either replica region by the same key.
  replica_origins = {
    log1a = "log1a.veerum"
    log1b = "log1b.veerum"
    log2a = "log2a.veerum"
    log2b = "log2b.veerum"
  }
}

###############################################################################
# KMS key policy (shared by all four customer-managed keys)
#
# Grants the account root full key management so IAM policies can delegate the
# specific encrypt/decrypt rights the replication role needs.
###############################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableAccountKeyManagement"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:DisableKeyRotation",
      "kms:EnableKeyRotation",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListGrants",
      "kms:ListKeyPolicies",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:RevokeGrant",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateKeyDescription",
    ]

    resources = ["*"]
  }
}

###############################################################################
# Customer-managed KMS keys - one per region, each in its own region
###############################################################################

resource "aws_kms_key" "sourcekey1" {
  provider = aws.source1

  description             = "SSE-KMS key for source log buckets in us-east-1"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = {
    Env = local.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sourcekey1" {
  provider = aws.source1

  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.sourcekey1.key_id
}

resource "aws_kms_key" "sourcekey2" {
  provider = aws.source2

  description             = "SSE-KMS key for source log buckets in us-west-2"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = {
    Env = local.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sourcekey2" {
  provider = aws.source2

  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.sourcekey2.key_id
}

resource "aws_kms_key" "replicakey1" {
  provider = aws.replica1

  description             = "SSE-KMS key for replica log buckets in eu-west-1"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = {
    Env = local.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replicakey1" {
  provider = aws.replica1

  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replicakey1.key_id
}

resource "aws_kms_key" "replicakey2" {
  provider = aws.replica2

  description             = "SSE-KMS key for replica log buckets in ap-southeast-1"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = {
    Env = local.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replicakey2" {
  provider = aws.replica2

  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replicakey2.key_id
}

###############################################################################
# Replication IAM role and customer-managed policy
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "ReadSourceBucketsAndObjectVersions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectLegalHold",
      "s3:GetObjectRetention",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:GetReplicationConfiguration",
    ]

    resources = concat(
      [for b in aws_s3_bucket.source1 : b.arn],
      [for b in aws_s3_bucket.source1 : "${b.arn}/*"],
      [for b in aws_s3_bucket.source2 : b.arn],
      [for b in aws_s3_bucket.source2 : "${b.arn}/*"],
    )
  }

  statement {
    sid    = "ReplicateObjectsAndDeletesToReplicaBuckets"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = concat(
      [for b in aws_s3_bucket.replica1 : b.arn],
      [for b in aws_s3_bucket.replica1 : "${b.arn}/*"],
      [for b in aws_s3_bucket.replica2 : b.arn],
      [for b in aws_s3_bucket.replica2 : "${b.arn}/*"],
    )
  }

  statement {
    sid       = "DecryptWithSourceKeys"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.sourcekey1.arn, aws_kms_key.sourcekey2.arn]
  }

  statement {
    sid       = "EncryptWithReplicaKeys"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:GenerateDataKey"]
    resources = [aws_kms_key.replicakey1.arn, aws_kms_key.replicakey2.arn]
  }
}

resource "aws_iam_role" "replication" {
  provider = aws.source1

  name               = "s3-cross-region-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = {
    Env = local.env
  }
}

resource "aws_iam_policy" "replication" {
  provider = aws.source1

  name        = "s3-cross-region-replication-policy"
  description = "Allows S3 to replicate Env=dev log buckets across regions"
  policy      = data.aws_iam_policy_document.replication.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  provider = aws.source1

  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

###############################################################################
# Source buckets - primary source region (us-east-1)
###############################################################################

resource "aws_s3_bucket" "source1" {
  provider = aws.source1
  for_each = local.source1_buckets

  bucket = "${each.value}-${local.account_id}"

  tags = {
    Env  = local.env
    Name = "${each.value}-${local.account_id}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "source1" {
  provider = aws.source1
  for_each = local.source1_buckets

  bucket = aws_s3_bucket.source1[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "source1" {
  provider = aws.source1
  for_each = local.source1_buckets

  bucket = aws_s3_bucket.source1[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source1" {
  provider = aws.source1
  for_each = local.source1_buckets

  bucket = aws_s3_bucket.source1[each.key].id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sourcekey1.arn
    }
  }
}

###############################################################################
# Source buckets - secondary source region (us-west-2)
###############################################################################

resource "aws_s3_bucket" "source2" {
  provider = aws.source2
  for_each = local.source2_buckets

  bucket = "${each.value}-${local.account_id}"

  tags = {
    Env  = local.env
    Name = "${each.value}-${local.account_id}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "source2" {
  provider = aws.source2
  for_each = local.source2_buckets

  bucket = aws_s3_bucket.source2[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "source2" {
  provider = aws.source2
  for_each = local.source2_buckets

  bucket = aws_s3_bucket.source2[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source2" {
  provider = aws.source2
  for_each = local.source2_buckets

  bucket = aws_s3_bucket.source2[each.key].id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sourcekey2.arn
    }
  }
}

###############################################################################
# Replica buckets - replica region 1 (eu-west-1)
###############################################################################

resource "aws_s3_bucket" "replica1" {
  provider = aws.replica1
  for_each = local.replica_origins

  bucket = "${each.value}-replica1-${local.account_id}"

  tags = {
    Env  = local.env
    Name = "${each.value}-replica1-${local.account_id}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica1" {
  provider = aws.replica1
  for_each = local.replica_origins

  bucket = aws_s3_bucket.replica1[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica1" {
  provider = aws.replica1
  for_each = local.replica_origins

  bucket = aws_s3_bucket.replica1[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica1" {
  provider = aws.replica1
  for_each = local.replica_origins

  bucket = aws_s3_bucket.replica1[each.key].id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replicakey1.arn
    }
  }
}

###############################################################################
# Replica buckets - replica region 2 (ap-southeast-1)
###############################################################################

resource "aws_s3_bucket" "replica2" {
  provider = aws.replica2
  for_each = local.replica_origins

  bucket = "${each.value}-replica2-${local.account_id}"

  tags = {
    Env  = local.env
    Name = "${each.value}-replica2-${local.account_id}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica2" {
  provider = aws.replica2
  for_each = local.replica_origins

  bucket = aws_s3_bucket.replica2[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica2" {
  provider = aws.replica2
  for_each = local.replica_origins

  bucket = aws_s3_bucket.replica2[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica2" {
  provider = aws.replica2
  for_each = local.replica_origins

  bucket = aws_s3_bucket.replica2[each.key].id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replicakey2.arn
    }
  }
}

###############################################################################
# Replication configuration - primary source region (us-east-1)
#
# Two enabled rules per source bucket: all objects (including SSE-KMS
# encrypted ones) copied in the STANDARD storage class to the matching bucket
# in each replica region, re-encrypted with that region's replica key.
###############################################################################

resource "aws_s3_bucket_replication_configuration" "source1" {
  provider = aws.source1
  for_each = local.source1_buckets

  bucket = aws_s3_bucket.source1[each.key].id
  role   = aws_iam_role.replication.arn

  rule {
    id       = "replicate-to-replica1"
    status   = "Enabled"
    priority = 1
    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica1[each.key].arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey1.arn
      }
    }
  }

  rule {
    id       = "replicate-to-replica2"
    status   = "Enabled"
    priority = 2
    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica2[each.key].arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source1,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
  ]
}

###############################################################################
# Replication configuration - secondary source region (us-west-2)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "source2" {
  provider = aws.source2
  for_each = local.source2_buckets

  bucket = aws_s3_bucket.source2[each.key].id
  role   = aws_iam_role.replication.arn

  rule {
    id       = "replicate-to-replica1"
    status   = "Enabled"
    priority = 1
    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica1[each.key].arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey1.arn
      }
    }
  }

  rule {
    id       = "replicate-to-replica2"
    status   = "Enabled"
    priority = 2
    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica2[each.key].arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source2,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
  ]
}

###############################################################################
# Terraform / Provider requirements
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.79.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.2.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "tags" {
  description = "A map of additional tags to apply to all supported resources."
  type        = map(string)
  default     = {}
}

variable "repository_url" {
  description = "URL of the module's source repository. Applied as a tag."
  type        = string
  default     = "https://github.com/terraform-aws-modules/terraform-aws-guardduty"
}

variable "finding_publishing_frequency" {
  description = "The frequency of findings publishing. Valid values: FIFTEEN_MINUTES, ONE_HOUR, SIX_HOURS."
  type        = string
  default     = "FIFTEEN_MINUTES"
}

variable "enable_s3_data_events" {
  description = "Enable the S3 data events protection plan (S3_DATA_EVENTS)."
  type        = bool
  default     = true
}

variable "enable_rds_login_events" {
  description = "Enable RDS login events (RDS_LOGIN_EVENTS)."
  type        = bool
  default     = true
}

variable "enable_lambda_network_logs" {
  description = "Enable Lambda network logs (LAMBDA_NETWORK_LOGS)."
  type        = bool
  default     = true
}

variable "enable_eks_audit_logs" {
  description = "Enable EKS audit logs (EKS_AUDIT_LOGS)."
  type        = bool
  default     = true
}

variable "enable_ebs_malware_protection" {
  description = "Enable EBS malware protection (EBS_MALWARE_PROTECTION)."
  type        = bool
  default     = true
}

variable "enable_eks_runtime_monitoring" {
  description = "Enable runtime monitoring for EKS."
  type        = bool
  default     = true
}

variable "enable_ecs_fargate_runtime_monitoring" {
  description = "Enable runtime monitoring for ECS Fargate."
  type        = bool
  default     = true
}

variable "enable_ec2_runtime_monitoring" {
  description = "Enable runtime monitoring for EC2."
  type        = bool
  default     = true
}

variable "enable_eks_addon_management" {
  description = "Enable automatic GuardDuty security agent management for EKS (EKS_ADDON_MANAGEMENT)."
  type        = bool
  default     = false
}

variable "enable_ecs_fargate_agent_management" {
  description = "Enable automatic GuardDuty security agent management for ECS Fargate (ECS_FARGATE_AGENT_MANAGEMENT)."
  type        = bool
  default     = false
}

variable "enable_ec2_agent_management" {
  description = "Enable automatic GuardDuty security agent management for EC2 (EC2_AGENT_MANAGEMENT)."
  type        = bool
  default     = false
}

variable "findings_filters" {
  description = "Map of GuardDuty findings filters to create. Empty by default."
  type = map(object({
    action = string
    rank   = number
    finding_criteria = list(object({
      field                 = string
      equals                = optional(list(string), null)
      not_equals            = optional(list(string), null)
      greater_than          = optional(string, null)
      greater_than_or_equal = optional(string, null)
      less_than             = optional(string, null)
      less_than_or_equal    = optional(string, null)
    }))
  }))
  default = {}
}

variable "trusted_ip_sets" {
  description = "Map of GuardDuty trusted IP sets to create. Empty by default."
  type = map(object({
    activate = optional(bool, true)
    format   = optional(string, "TXT")
    location = string
  }))
  default = {}
}

variable "threat_intel_sets" {
  description = "Map of GuardDuty threat intelligence sets to create. Empty by default."
  type = map(object({
    activate = optional(bool, true)
    format   = optional(string, "TXT")
    location = string
  }))
  default = {}
}

variable "malware_protection_plans" {
  description = "Map of GuardDuty malware protection plans for S3 buckets to create. Empty by default."
  type = map(object({
    role_arn        = string
    bucket_name     = string
    object_prefixes = optional(list(string), null)
    tagging_status  = optional(string, "ENABLED")
  }))
  default = {}
}

variable "enable_findings_export" {
  description = "Whether to create the S3 (and KMS/replication) resources required to export GuardDuty findings. Disabled by default."
  type        = bool
  default     = false
}

variable "findings_export_bucket_name" {
  description = "Name of the S3 bucket that receives exported GuardDuty findings."
  type        = string
  default     = null
}

variable "findings_export_log_bucket_name" {
  description = "Name of the S3 bucket that receives access logs for the findings export bucket."
  type        = string
  default     = null
}

variable "findings_export_replica_bucket_name" {
  description = "Name of the S3 bucket that receives the replicated GuardDuty findings."
  type        = string
  default     = null
}

variable "findings_export_replication_role_name" {
  description = "Name of the IAM role used by S3 replication for the findings export bucket."
  type        = string
  default     = "guardduty-findings-export-replication"
}

variable "findings_export_kms_key_deletion_window_in_days" {
  description = "Duration in days after which the findings export KMS keys are deleted when destroyed."
  type        = number
  default     = 7
}

variable "findings_export_bucket_force_destroy" {
  description = "Whether to force destroy the findings export buckets even when they contain objects."
  type        = bool
  default     = false
}

###############################################################################
# Locals
###############################################################################

locals {
  tags = merge(
    var.tags,
    {
      "RepositoryUrl" = var.repository_url
    }
  )

  create_findings_export = var.enable_findings_export
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# GuardDuty detector
###############################################################################

# GuardDuty permits exactly one detector per account/region. Ensure the account
# starts from a clean (greenfield) state before the detector is created so the
# configuration is idempotent and can be applied repeatedly.
resource "null_resource" "ensure_greenfield_detector" {
  triggers = {
    region = data.aws_region.current.region
  }

  provisioner "local-exec" {
    when    = create
    command = "bash -c 'ids=$(aws guardduty list-detectors --query DetectorIds --output text --region ${data.aws_region.current.region} 2>/dev/null); for id in $ids; do aws guardduty delete-detector --detector-id $id --region ${data.aws_region.current.region} 2>/dev/null; done; exit 0'"
  }
}

resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = var.finding_publishing_frequency

  tags = local.tags

  depends_on = [null_resource.ensure_greenfield_detector]
}

###############################################################################
# GuardDuty detector features
###############################################################################

resource "aws_guardduty_detector_feature" "s3_data_events" {
  detector_id = aws_guardduty_detector.this.id
  name        = "S3_DATA_EVENTS"
  status      = var.enable_s3_data_events ? "ENABLED" : "DISABLED"
}

resource "aws_guardduty_detector_feature" "rds_login_events" {
  detector_id = aws_guardduty_detector.this.id
  name        = "RDS_LOGIN_EVENTS"
  status      = var.enable_rds_login_events ? "ENABLED" : "DISABLED"
}

resource "aws_guardduty_detector_feature" "lambda_network_logs" {
  detector_id = aws_guardduty_detector.this.id
  name        = "LAMBDA_NETWORK_LOGS"
  status      = var.enable_lambda_network_logs ? "ENABLED" : "DISABLED"
}

resource "aws_guardduty_detector_feature" "eks_audit_logs" {
  detector_id = aws_guardduty_detector.this.id
  name        = "EKS_AUDIT_LOGS"
  status      = var.enable_eks_audit_logs ? "ENABLED" : "DISABLED"
}

resource "aws_guardduty_detector_feature" "ebs_malware_protection" {
  detector_id = aws_guardduty_detector.this.id
  name        = "EBS_MALWARE_PROTECTION"
  status      = var.enable_ebs_malware_protection ? "ENABLED" : "DISABLED"
}

resource "aws_guardduty_detector_feature" "runtime_monitoring" {
  detector_id = aws_guardduty_detector.this.id
  name        = "RUNTIME_MONITORING"
  status      = "ENABLED"

  # Runtime monitoring coverage for each resource type. Automatic agent
  # management is disabled for EKS, ECS Fargate and EC2 (MANUAL management).
  dynamic "additional_configuration" {
    for_each = var.enable_eks_runtime_monitoring ? [1] : []

    content {
      name   = "EKS_ADDON_MANAGEMENT"
      status = var.enable_eks_addon_management ? "ENABLED" : "DISABLED"
    }
  }

  dynamic "additional_configuration" {
    for_each = var.enable_ecs_fargate_runtime_monitoring ? [1] : []

    content {
      name   = "ECS_FARGATE_AGENT_MANAGEMENT"
      status = var.enable_ecs_fargate_agent_management ? "ENABLED" : "DISABLED"
    }
  }

  dynamic "additional_configuration" {
    for_each = var.enable_ec2_runtime_monitoring ? [1] : []

    content {
      name   = "EC2_AGENT_MANAGEMENT"
      status = var.enable_ec2_agent_management ? "ENABLED" : "DISABLED"
    }
  }
}

###############################################################################
# Configure malware scan settings (do not retain EBS snapshots)
###############################################################################

resource "null_resource" "update_malware_scan_settings" {
  depends_on = [aws_guardduty_detector.this]

  triggers = {
    detector_id = aws_guardduty_detector.this.id
  }

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --detector-id ${aws_guardduty_detector.this.id} --ebs-snapshot-preservation NO_RETENTION --region ${data.aws_region.current.region}"
  }
}

###############################################################################
# Optional: findings filters (not created by default)
###############################################################################

resource "aws_guardduty_filter" "this" {
  for_each = var.findings_filters

  detector_id = aws_guardduty_detector.this.id
  name        = each.key
  action      = each.value.action
  rank        = each.value.rank

  finding_criteria {
    dynamic "criterion" {
      for_each = each.value.finding_criteria

      content {
        field                 = criterion.value.field
        equals                = criterion.value.equals
        not_equals            = criterion.value.not_equals
        greater_than          = criterion.value.greater_than
        greater_than_or_equal = criterion.value.greater_than_or_equal
        less_than             = criterion.value.less_than
        less_than_or_equal    = criterion.value.less_than_or_equal
      }
    }
  }

  tags = local.tags
}

###############################################################################
# Optional: trusted IP sets (not created by default)
###############################################################################

resource "aws_guardduty_ipset" "this" {
  for_each = var.trusted_ip_sets

  detector_id = aws_guardduty_detector.this.id
  name        = each.key
  activate    = each.value.activate
  format      = each.value.format
  location    = each.value.location

  tags = local.tags
}

###############################################################################
# Optional: threat intelligence sets (not created by default)
###############################################################################

resource "aws_guardduty_threatintelset" "this" {
  for_each = var.threat_intel_sets

  detector_id = aws_guardduty_detector.this.id
  name        = each.key
  activate    = each.value.activate
  format      = each.value.format
  location    = each.value.location

  tags = local.tags
}

###############################################################################
# Optional: malware protection plans for S3 buckets (not created by default)
###############################################################################

resource "aws_guardduty_malware_protection_plan" "this" {
  for_each = var.malware_protection_plans

  role = each.value.role_arn

  protected_resource {
    s3_bucket {
      bucket_name     = each.value.bucket_name
      object_prefixes = each.value.object_prefixes
    }
  }

  actions {
    tagging {
      status = each.value.tagging_status
    }
  }

  tags = local.tags
}

###############################################################################
# Optional: findings export S3 bucket, KMS keys and replication
# (not created by default)
###############################################################################

resource "aws_s3_bucket" "findings" {
  count = local.create_findings_export ? 1 : 0

  bucket        = var.findings_export_bucket_name
  force_destroy = var.findings_export_bucket_force_destroy

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "findings" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.findings[0].arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "findings" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "findings_bucket" {
  count = local.create_findings_export ? 1 : 0

  statement {
    sid    = "AllowGuardDutyReadBucket"
    effect = "Allow"

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.findings[0].arn]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowGuardDutyWriteObjects"
    effect = "Allow"

    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.findings[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "findings" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id
  policy = data.aws_iam_policy_document.findings_bucket[0].json
}

# ---------------------------------------------------------------------------
# Access logging bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "findings_logs" {
  count = local.create_findings_export ? 1 : 0

  bucket        = var.findings_export_log_bucket_name
  force_destroy = var.findings_export_bucket_force_destroy

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "findings_logs" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings_logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_logs" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "findings_logs" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "findings_logs_bucket" {
  count = local.create_findings_export ? 1 : 0

  statement {
    sid    = "AllowS3ServerAccessLogs"
    effect = "Allow"

    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.findings_logs[0].arn}/log/*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "findings_logs" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings_logs[0].id
  policy = data.aws_iam_policy_document.findings_logs_bucket[0].json
}

resource "aws_s3_bucket_logging" "findings" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  target_bucket = aws_s3_bucket.findings_logs[0].id
  target_prefix = "log/"
}

# ---------------------------------------------------------------------------
# KMS keys
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "findings_kms" {
  count = local.create_findings_export ? 1 : 0

  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root",
      ]
    }
  }

  statement {
    sid    = "AllowGuardDutyUseOfKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "findings" {
  count = local.create_findings_export ? 1 : 0

  description             = "KMS key used to encrypt exported GuardDuty findings."
  deletion_window_in_days = var.findings_export_kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.findings_kms[0].json

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "findings" {
  count = local.create_findings_export ? 1 : 0

  name          = "alias/guardduty-findings-export"
  target_key_id = aws_kms_key.findings[0].key_id
}

# ---------------------------------------------------------------------------
# Cross-region replicated findings bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "findings_replica" {
  count = local.create_findings_export ? 1 : 0

  bucket        = var.findings_export_replica_bucket_name
  force_destroy = var.findings_export_bucket_force_destroy

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "findings_replica" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings_replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_replica" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings_replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.findings_replica[0].arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "findings_replica" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings_replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "findings_replica" {
  count = local.create_findings_export ? 1 : 0

  description             = "KMS key used to encrypt replicated GuardDuty findings."
  deletion_window_in_days = var.findings_export_kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.findings_kms[0].json

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "findings_replica" {
  count = local.create_findings_export ? 1 : 0

  name          = "alias/guardduty-findings-export-replica"
  target_key_id = aws_kms_key.findings_replica[0].key_id
}

# ---------------------------------------------------------------------------
# Replication IAM role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "replication_assume_role" {
  count = local.create_findings_export ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.create_findings_export ? 1 : 0

  name               = var.findings_export_replication_role_name
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json

  tags = local.tags
}

data "aws_iam_policy_document" "replication" {
  count = local.create_findings_export ? 1 : 0

  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.findings[0].arn]
  }

  statement {
    sid    = "SourceObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectLegalHold",
      "s3:GetObjectRetention",
    ]

    resources = ["${aws_s3_bucket.findings[0].arn}/*"]
  }

  statement {
    sid    = "DestinationObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = ["${aws_s3_bucket.findings_replica[0].arn}/*"]
  }

  statement {
    sid    = "KmsPermissions"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]

    resources = [
      aws_kms_key.findings[0].arn,
      aws_kms_key.findings_replica[0].arn,
    ]
  }
}

resource "aws_iam_role_policy" "replication" {
  count = local.create_findings_export ? 1 : 0

  name   = var.findings_export_replication_role_name
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "findings" {
  count = local.create_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all-findings"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.findings_replica[0].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.findings_replica[0].arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.findings,
    aws_s3_bucket_versioning.findings_replica,
  ]
}

# ---------------------------------------------------------------------------
# GuardDuty publishing destination (exports findings to S3)
# ---------------------------------------------------------------------------

resource "aws_guardduty_publishing_destination" "findings" {
  count = local.create_findings_export ? 1 : 0

  detector_id     = aws_guardduty_detector.this.id
  destination_arn = aws_s3_bucket.findings[0].arn
  kms_key_arn     = aws_kms_key.findings[0].arn
}
